window.__BOOK__={"meta":{"title_es":"El Principito","title_zh":"小王子","author_es":"Antoine de Saint-Exupéry","author_zh":"安托万·德·圣埃克苏佩里","voice":"es-ES-ElviraNeural (edge-tts)","ipa_note":"音标为宽式音位转写（西班牙本土发音，ce/ci/z 发 θ），仅供参考；重音未标注。","n_chapters":28,"n_paras":570,"n_sents":1422,"audio_paras":570},"chapters":[{"id":"ch00","title_es":"A Léon Werth","title_zh":"献词","paras":[{"id":"ch00p00","audio":true,"sents":[{"es":"A Léon Werth.","zh":"献给列昂·维尔特","t":[100,1762]},{"es":"Pido perdón a los niños por haber dedicado este libro a una persona mayor.","zh":"我请求孩子们原谅，我把这本书献给了一个大人。","t":[1762,6400]},{"es":"Tengo una excusa seria: esa persona mayor es el mejor amigo que tengo en el mundo.","zh":"不过我有一个充分的理由。","t":[6400,11862]},{"es":"Tengo otra excusa: esa persona mayor puede comprenderlo todo, hasta los libros para niños.","zh":"这个大人——是我世界上最好的朋友。","t":[11862,18138]},{"es":"Tengo una tercera excusa: esa persona mayor vive en Francia, donde tiene hambre y frío.","zh":"还有另一个理由——他什么都懂，哪怕是写给孩子们看的书。","t":[18138,24150]},{"es":"Necesita ser consolada.","zh":"我还有第三个理由——这个大人住在法国，在那里又饿又冷。","t":[24150,26588]},{"es":"Si todas estas excusas no bastan, quiero dedicar este libro al niño que esa persona mayor fue antiguamente.","zh":"当然，得好好安慰他才是。","t":[26588,33475]},{"es":"Todas las personas grandes han sido niños primero.","zh":"如果这些理由还不够，那我情愿把这本书献给这个大人曾经当过的那个小孩子。","t":[33475,37075]},{"es":"(Pero pocas lo recuerdan).","zh":"因为所有大人曾经都是孩子，尽管没几个人记得这一点。","t":[37075,39350]},{"es":"Corrijo, pues, mi dedicatoria: A LEÓN WERTH, CUANDO ERA UN PEQUEÑO NIÑO.","zh":"所以我把这个题词改一改：献给小时候的列昂·维尔特。","t":[39350,43437]}]}]},{"id":"ch01","title_es":"Capítulo 1","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":true,"sents":[{"es":"Cuando yo tenía seis años vi en un libro sobre la selva virgen que se titulaba \"Historias vividas\", una magnífica lámina.","zh":"我六岁的时候，有一次在一本讲热带森林的书里看到一幅奇妙的画。","t":[100,7538]},{"es":"Representaba una serpiente boa que se tragaba a una fiera.","zh":"那本书叫《真实的故事》。","t":[7538,11612]},{"es":"Esta es la copia del dibujo.","zh":"大致就是下面这个样子。","t":[11612,13200]}]},{"id":"ch01p01","audio":true,"sents":[{"es":"En el libro se afirmaba: \"La serpiente boa se traga su presa entera, sin masticarla.","zh":"书里说，蟒蛇吞食猎物时是囫囵吞下、不加咀嚼的。","t":[100,5725]},{"es":"Luego ya no puede moverse y duerme durante los seis meses que dura su digestión\".","zh":"然后它们就动弹不得，要睡上六个月，直到把东西全部消化完。","t":[5725,9776]}]},{"id":"ch01p02","audio":true,"sents":[{"es":"Reflexioné mucho en ese momento sobre las aventuras de la jungla y a mi vez logré trazar con un lápiz de colores mi primer dibujo.","zh":"那时我常常幻想丛林里的种种奇遇，所以也用彩色铅笔画了一幅画。","t":[100,7538]},{"es":"Mi dibujo número 1 era de esta manera:","zh":"它大致是这个样子。","t":[7538,9737]}]},{"id":"ch01p03","audio":true,"sents":[{"es":"Enseñé mi obra de arte a las personas mayores y les pregunté si mi dibujo les daba miedo.","zh":"我把我的杰作拿给大人们看，问他们害不害怕。","t":[100,5550]},{"es":"-¿por qué habría de asustar un sombrero?","zh":"他们却回答我说——一顶帽子有什么好怕的？","t":[5550,8475]},{"es":"- me respondieron.","zh":"那是一条正在消化大象的蟒蛇。","t":[8475,9438]}]},{"id":"ch01p04","audio":true,"sents":[{"es":"Mi dibujo no representaba un sombrero.","zh":"于是为了让他们看明白，我又画了蟒蛇肚子里的情况。","t":[100,3188]},{"es":"Representaba una serpiente boa que digiere un elefante.","zh":"大人们嘛，凡事总得向他们解释个明白。","t":[3188,7125]},{"es":"Dibujé entonces el interior de la serpiente boa a fin de que las personas mayores pudieran comprender.","zh":"我的第二号作品就是这样的。","t":[7125,13112]},{"es":"Siempre estas personas tienen necesidad de explicaciones.","zh":"就这样，六岁的我放弃了成为名画家的梦想。","t":[13112,17250]},{"es":"Mi dibujo número 2 era así:","zh":"我的两幅画——第一号和第二号——彻底失败，让我大失所望。","t":[17250,19038]}]},{"id":"ch01p05","audio":true,"sents":[{"es":"Las personas mayores me aconsejaron abandonar el dibujo de serpientes boas, ya fueran abiertas o cerradas, y poner más interés en la geografía, la historia, el cálculo y la gramática.","zh":"大人们自己什么也不懂，孩子们总得反反复复向他们解释，真是累人。","t":[100,11325]},{"es":"De esta manera a la edad de seis años abandoné una magnífica carrera de pintor.","zh":"我学会了驾驶飞机。","t":[11325,16412]},{"es":"Había quedado desilusionado por el fracaso de mis dibujos número 1 y número 2.","zh":"我差不多飞遍了全世界。","t":[16412,20350]},{"es":"Las personas mayores nunca pueden comprender algo por sí solas y es muy aburrido para los niños tener que darles una y otra vez explicaciones.","zh":"所以说，地理知识还真帮了我忙。","t":[20350,29126]}]},{"id":"ch01p06","audio":true,"sents":[{"es":"Tuve, pues, que elegir otro oficio y aprendía pilotear aviones.","zh":"我能一眼就分辨出中国和亚利桑那。","t":[100,4538]},{"es":"He volado un poco por todo el mundo y la geografía, en efecto, me ha servido de mucho; al primer vistazo podía distinguir perfectamente la China de Arizona.","zh":"这一生里，我跟一大堆严肃的人打过交道。","t":[4538,13800]},{"es":"Esto es muy útil, sobre todo si se pierde uno durante la noche.A lo largo de mi vida he tenido multitud de contactos con multitud de gente seria.","zh":"我常常生活在大人中间。","t":[13800,22300]},{"es":"Viví mucho con personas mayores y las he conocido muy de cerca; pero esto no ha mejorado demasiado mi opinión sobre ellas.","zh":"我也常近距离地打量他们，尽管这并没有改善我对他们的看法。","t":[22300,28713]}]},{"id":"ch01p07","audio":true,"sents":[{"es":"Cuando me he encontrado con alguien que me parecía un poco lúcido, lo he sometido a la experiencia de mi dibujo número 1 que he conservado siempre.","zh":"我给他看我一直随身带着的第一号作品。","t":[100,8275]},{"es":"Quería saber si verdaderamente era un ser comprensivo.","zh":"我想知道这个大人到底有多懂事。","t":[8275,12038]},{"es":"E invariablemente me contestaban siempre: \"Es un sombrero\".","zh":"可他总是回答我说，那是一顶帽子。","t":[12038,16175]},{"es":"Me abstenía de hablarles de la serpiente boa, de la selva virgen y de las estrellas.","zh":"所以我也就不跟他说什么蟒蛇、热带森林或者星星了。","t":[16175,21438]},{"es":"Poniéndome a su altura, les hablaba del bridge, del golf, de política y de corbatas.","zh":"我跟他说桥牌，说高尔夫，说政治，说领带。","t":[21438,25837]}]},{"id":"ch01p08","audio":true,"sents":[{"es":"Y mi interlocutor se quedaba muy contento de conocer a un hombre tan razonable.","zh":"于是这个大人就很高兴，能结识我这样一个通情达理的人。","t":[100,4038]}]}]},{"id":"ch02","title_es":"Capítulo 2","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":true,"sents":[{"es":"Viví así, solo, nadie con quien poder hablar verdaderamente, hasta cuando hace seis años tuve una avería en el desierto de Sahara.","zh":"后来我独自生活，连个能说真心话的人都没有。","t":[100,7888]},{"es":"Algo se había estropeado en el motor.","zh":"这种情况一直持续到六年前，我在撒哈拉沙漠上空出了事故。","t":[7888,10788]},{"es":"Como no llevaba conmigo ni mecánico ni pasajero alguno, me dispuse a realizar, yo solo, una reparación difícil.","zh":"飞机引擎里某个零件坏了。","t":[10788,18062]},{"es":"Era para mí una cuestión de vida o muerte, pues apenas tenía agua de beber para ocho días.","zh":"因为身边既没有机械师也没有乘客，我只好自己动手，对付这个棘手的故障。","t":[18062,22687]}]},{"id":"ch02p01","audio":true,"sents":[{"es":"La primera noche me dormí sobre la arena, a unas mil millas de distancia del lugar habitado más próximo.","zh":"我带的水不多——只够喝八天。","t":[100,6625]},{"es":"Estaba más aislado que un náufrago en una balsa en medio del océano.","zh":"第一天傍晚，我在离人烟千里之外的沙地上睡着了。","t":[6625,11075]},{"es":"Imagínense, pues, mi sorpresa cuando al amanecer me despertó una extraña vocecita que decía: - ¡Por favor…","zh":"所以，当黎明时分一个细细的嗓音把我唤醒时，您可想而知我有多惊讶。","t":[11075,16725]},{"es":"píntame un cordero!","zh":"他说：——求求你……给我画一只小羊！","t":[16725,18662]},{"es":"-¿Eh?","zh":"——什么？","t":[18662,19838]},{"es":"-¡Píntame un cordero!","zh":"——给我画一只小羊！","t":[19838,20874]}]},{"id":"ch02p02","audio":true,"sents":[{"es":"Me puse en pie de un salto como herido por el rayo.","zh":"我腾地一下跳了起来，就像身边劈下一道闪电。","t":[100,2762]}]},{"id":"ch02p03","audio":true,"sents":[{"es":"Me froté los ojos.","zh":"我使劲揉了揉眼睛，朝四下里张望。","t":[100,2262]},{"es":"Miré a mi alrededor.","zh":"我看见一个完全不寻常的小家伙，正一本正经地打量着我。","t":[2262,4462]},{"es":"Vi a un extraordinario muchachito que me miraba gravemente.","zh":"这是我后来为他画的最满意的一幅肖像。","t":[4462,7587]}]},{"id":"ch02p04","audio":true,"sents":[{"es":"Ahí tienen el mejor retrato que más tarde logré hacer de él, aunque mi dibujo, ciertamente es menos encantador que el modelo.","zh":"虽说画上的他不如本人那么好看。","t":[100,7388]},{"es":"Pero no es mía la culpa.","zh":"不过这不能怪我。","t":[7388,8637]}]},{"id":"ch02p05","audio":true,"sents":[{"es":"Las personas mayores me desanimaron de mi carrera de pintor a la edad de seis años y no había aprendido a dibujar otra cosa que boas cerradas y boas abiertas.","zh":"要知道，我六岁那年，大人们就打消了我当画家的念头，除了外面和里面的蟒蛇，我什么都不会画。","t":[100,8062]}]},{"id":"ch02p06","audio":true,"sents":[{"es":"Miré, pues, aquella aparición con los ojos redondos de admiración.","zh":"于是，我瞪大眼睛望着这个不可思议的小家伙。","t":[100,4550]},{"es":"No hay que olvidar que me encontraba a unas mil millas de distancia del lugar habitado más próximo.","zh":"而这个小家伙，看起来既不像迷了路，也不像受了惊，更不像快要饿死或渴死的样子。","t":[4550,10225]},{"es":"Y ahora bien, el muchachito no me parecía ni perdido, ni muerto de cansancio, de hambre, de sed o de miedo.","zh":"他完全不像一个在离人烟数百里的沙漠中央迷了路的孩子。","t":[10225,17038]},{"es":"No tenía en absoluto la apariencia de un niño perdido en el desierto, a mil millas de distancia del lugar habitado más próximo.","zh":"等我恢复了说话的能力，便问他：——可是……你在这儿干什么呢？","t":[17038,24612]},{"es":"Cuando logré, por fin, articular palabra, le dije:","zh":"他却轻声而认真地把话重复了一遍：——求求你……给我画一只小羊！","t":[24612,27687]}]},{"id":"ch02p07","audio":true,"sents":[{"es":"-Pero…","zh":"眼前这一切在我眼里是个解不开又令人震撼的谜，我不敢拒绝。","t":[100,425]},{"es":"¿qué haces tú por aquí?","zh":"尽管在离人烟千里、生死交界的地方，这显得多么不合时宜，我还是从口袋里掏出了纸和笔。","t":[425,1575]}]},{"id":"ch02p08","audio":true,"sents":[{"es":"Y él respondió entonces, suavemente, como algo muy importante: -¡Por favor…","zh":"不过我想起，我主要学的是地理、历史、算术和拼写。","t":[100,4138]},{"es":"píntame un cordero!","zh":"于是我带着几分沮丧，对小家伙说我不会画画。","t":[4138,5138]}]},{"id":"ch02p09","audio":true,"sents":[{"es":"Cuando el misterio es demasiado impresionante, es imposible desobedecer.","zh":"他却回答我说：——没关系。","t":[100,4800]},{"es":"Por absurdo que aquello me pareciera, a mil millas de distancia de todo lugar habitado y en peligro de muerte, saqué de mi bolsillo una hoja de papel y una pluma fuente.","zh":"——画一只小羊吧。","t":[4800,14125]},{"es":"Recordé que yo había estudiado especialmente geografía, historia, cálculo y gramática y le dije al muchachito (ya un poco malhumorado), que no sabía dibujar.","zh":"因为我从来没画过小羊，就给他重画了我会画的两幅画里的一幅——外面的蟒蛇。","t":[14125,22750]}]},{"id":"ch02p10","audio":true,"sents":[{"es":"-No importa - me respondió-, píntame un cordero!","zh":"——我不要蟒蛇肚子里的大象。","t":[100,2675]}]},{"id":"ch02p11","audio":true,"sents":[{"es":"Como nunca había dibujado un cordero, rehíce para él uno de los dos únicos dibujos que yo era capaz de realizar: el de la serpiente boa cerrada.","zh":"——蟒蛇太危险，大象又太大了。","t":[100,8650]},{"es":"Y quedé estupefacto cuando oí decir al hombrecito: - ¡No, no!","zh":"——我家里的一切都特别小。","t":[8650,12762]},{"es":"Yo no quiero un elefante en una serpiente.","zh":"——我要的是一只小羊。","t":[12762,15888]},{"es":"La serpiente es muy peligrosa y el elefante ocupa mucho sitio.","zh":"——给我画一只小羊吧。","t":[15888,20138]},{"es":"En mi tierra es todo muy pequeño.","zh":"于是我就给他画了一只。","t":[20138,22838]},{"es":"Necesito un cordero.","zh":"他仔细看了看，说：——不行。","t":[22838,25038]},{"es":"Píntame un cordero.","zh":"——这只太弱不禁风了。","t":[25038,26075]}]},{"id":"ch02p12","audio":true,"sents":[{"es":"Dibujé un cordero.","zh":"——再画一只别的吧。","t":[100,1138]}]},{"id":"ch02p13","audio":true,"sents":[{"es":"Lo miró atentamente y dijo: ¡No!","zh":"于是我又画了第二只小羊。","t":[100,2862]},{"es":"Este está ya muy enfermo.","zh":"我的新朋友宽厚地笑了笑。","t":[2862,5312]},{"es":"Haz otro.","zh":"——你没看见吗？","t":[5312,5888]}]},{"id":"ch02p14","audio":true,"sents":[{"es":"Volví a dibujar.","zh":"——它还有角呢……","t":[100,1038]}]},{"id":"ch02p15","audio":true,"sents":[{"es":"Mi amigo sonrió dulcemente, con indulgencia.","zh":"于是我又改画了一张。","t":[100,3538]},{"es":"-¿Ves?","zh":"可他又像前面几只一样拒绝了：——这只小羊太老了。","t":[3538,4875]},{"es":"Esto no es un cordero, es un carnero.","zh":"——我要的是能活很久很久的小羊。","t":[4875,8038]},{"es":"Tiene Cuernos…","zh":"这下我没了耐心，因为我得赶紧修我的引擎。","t":[8038,8876]}]},{"id":"ch02p16","audio":true,"sents":[{"es":"Rehice nuevamente mi dibujo: fue rechazado igual que los anteriores.","zh":"我胡乱画了下面这张，满不在乎地嘟囔道：","t":[100,3963]}]},{"id":"ch02p17","audio":true,"sents":[{"es":"-Este es demasiado viejo.","zh":"——给你，这是个箱子。","t":[100,2550]},{"es":"Quiero un cordero que viva mucho tiempo.","zh":"——你要的小羊就在里面待着呢。","t":[2550,4550]}]},{"id":"ch02p18","audio":true,"sents":[{"es":"Falto ya de paciencia y deseoso de comenzar a desmontar el motor, garrapateé rápidamente este dibujo, se lo enseñé, y le agregué:","zh":"可是，当我看到我这位小批评家脸上顿时绽开光彩时，我惊讶极了：——这正是我想要的！","t":[100,7487]}]},{"id":"ch02p19","audio":true,"sents":[{"es":"-Esta es la caja.","zh":"——你说，这只小羊得吃很多草吗？","t":[100,2100]},{"es":"El cordero que quieres está adentro.","zh":"——怎么啦？","t":[2100,4938]},{"es":"Con gran sorpresa mía el rostro de mi joven juez se iluminó: -¡Así es como yo lo quería!","zh":"——因为我家的一切都特别小……","t":[4938,10562]},{"es":"¿Crees que sea necesario mucha hierba para este cordero?","zh":"——它本来就那么小嘛。","t":[10562,14425]},{"es":"-¿Por qué?","zh":"他俯下身去看那幅画。","t":[14425,14812]}]},{"id":"ch02p20","audio":true,"sents":[{"es":"-Porque en mi tierra es todo tan pequeño…","zh":"——也没那么小呀。","t":[100,2088]}]},{"id":"ch02p21","audio":true,"sents":[{"es":"Se inclinó hacia el dibujo y exclamó: -¡Bueno, no tan pequeño…!","zh":"——你瞧！","t":[100,4450]},{"es":"Está dormido…","zh":"——它睡着了。","t":[4450,5250]}]},{"id":"ch02p22","audio":true,"sents":[{"es":"Y así fue como conocí al principito.","zh":"就这样，我结识了小王子。","t":[100,2075]}]}]},{"id":"ch03","title_es":"Capítulo 3","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":true,"sents":[{"es":"Me costó mucho tiempo comprender de dónde venía.","zh":"我没能马上弄明白，他是从哪儿来的。","t":[100,3575]},{"es":"El principito, que me hacía muchas preguntas, jamás parecía oír las mías.","zh":"小王子问了我许多问题，却仿佛根本不听我问他的话。","t":[3575,8712]},{"es":"Fueron palabras pronunciadas al azar, las que poco a poco me revelaron todo.","zh":"不过，留意他偶然吐露的只言片语，我渐渐明白了是怎么回事。","t":[8712,13675]},{"es":"Así, cuando distinguió por vez primera mi avión (no dibujaré mi avión, por tratarse de un dibujo demasiado complicado para mí) me preguntó: -¿Qué cosa es esa?","zh":"他第一次看到我的飞机时（我就不画它了——那幅画对我来说太难了），问我：——这是个什么玩意儿？","t":[13675,23188]},{"es":"-Eso no es una cosa.","zh":"——这不是玩意儿。","t":[23188,25412]},{"es":"Eso vuela.","zh":"——这是飞机。","t":[25412,27038]},{"es":"Es un avión, mi avión.","zh":"——它会飞。","t":[27038,28488]}]},{"id":"ch03p01","audio":true,"sents":[{"es":"Me sentía orgulloso al decirle que volaba.","zh":"——这是我的飞机。","t":[100,3338]},{"es":"El entonces gritó: -¡Cómo!","zh":"我得意地告诉他，我就是乘着它飞的。","t":[3338,5775]},{"es":"¿Has caído del cielo?","zh":"——是吗？","t":[5775,7912]},{"es":"-Sí -le dije modestamente.","zh":"——这么说，你是从天上掉下来的？","t":[7912,10462]},{"es":"-¡Ah, que curioso!","zh":"——是啊，——我谦逊地答道。","t":[10462,11450]}]},{"id":"ch03p02","audio":true,"sents":[{"es":"Y el principito lanzó una graciosa carcajada que me irritó mucho.","zh":"——啊……","t":[100,4400]},{"es":"Me gusta que mis desgracias se tomen en serio.","zh":"——真有意思……","t":[4400,7762]},{"es":"Y añadió:","zh":"小王子朗声大笑起来，这让我有点不快。","t":[7762,8337]}]},{"id":"ch03p03","audio":true,"sents":[{"es":"-Entonces ¿tú también vienes del cielo?","zh":"我觉得，对我这般绝境，该严肃对待才是。","t":[100,3288]},{"es":"¿De qué planeta eres tú?","zh":"接着他又说：——这么说，你也是从天上来的？","t":[3288,4537]}]},{"id":"ch03p04","audio":true,"sents":[{"es":"Divisé una luz en el misterio de su presencia y le pregunté bruscamente: -¿Tu vienes, pues, de otro planeta?","zh":"——那你是来自哪颗行星？","t":[100,5613]}]},{"id":"ch03p05","audio":true,"sents":[{"es":"Pero no me respondió; movía lentamente la cabeza mirando detenidamente mi avión.","zh":"这时我开始猜到他来历的秘密，便直截了当地问他：——这么说是你从别的星球来的？","t":[100,4463]}]},{"id":"ch03p06","audio":true,"sents":[{"es":"-Es cierto, que, encima de eso, no puedes venir de muy lejos…","zh":"可他没有回答我。","t":[100,3462]}]},{"id":"ch03p07","audio":true,"sents":[{"es":"Y se hundió en un ensueño durante largo tiempo.","zh":"他只是摇了摇头，望着我的飞机说：——乘这个玩意儿，你恐怕飞不了多远吧……","t":[100,3575]},{"es":"Luego sacando de su bolsillo mi cordero se abismó en la contemplación de su tesoro.","zh":"他沉默下来，想了很久。","t":[3575,7787]}]},{"id":"ch03p08","audio":true,"sents":[{"es":"Imagínense cómo me intrigó esta semiconfidencia sobre los otros planetas.","zh":"后来，他从口袋里掏出我画的那只小羊，端详起这份珍贵的礼物来。","t":[100,4950]},{"es":"Me esforcé, pues, en saber algo más: -¿De dónde vienes, muchachito?","zh":"您想想看，听到他提起别的星球，我有多么惊讶。","t":[4950,9525]},{"es":"¿Dónde está \"tu casa\"?","zh":"于是我尽量多打听些这方面的事。","t":[9525,11712]},{"es":"¿Dónde quieres llevarte mi cordero?","zh":"——那么，你是从哪儿来的呢，我的小家伙？","t":[11712,13425]}]},{"id":"ch03p09","audio":true,"sents":[{"es":"Después de meditar silenciosamente me respondió:","zh":"——你说的“你家”在哪儿呀？","t":[100,2700]}]},{"id":"ch03p10","audio":true,"sents":[{"es":"-Lo bueno de la caja que me has dado es que por la noche le servirá de casa.","zh":"——你要把我的小羊带到哪儿去？","t":[100,4538]},{"es":"-Sin duda.","zh":"他沉默片刻，若有所思地答道：——还好你把它画在了箱子里。","t":[4538,6150]},{"es":"Y si eres bueno te daré también una cuerda y una estaca para atarlo durante el día.","zh":"——夜里它就可以睡在里面。","t":[6150,10287]}]},{"id":"ch03p11","audio":true,"sents":[{"es":"Esta proposición pareció chocar al principito.","zh":"——那当然。","t":[100,3488]},{"es":"-¿Atarlo?","zh":"——你要是听话，我再给你画根绳子，白天好把它拴住。","t":[3488,4975]},{"es":"¡Qué idea más rara!","zh":"——还有一根木桩。","t":[4975,7025]},{"es":"-Si no lo atas, se irá quién sabe dónde y se perderá…","zh":"可是，我这个提议似乎让小王子很不开心。","t":[7025,9676]}]},{"id":"ch03p12","audio":true,"sents":[{"es":"Mi amigo soltó una nueva carcajada.","zh":"——拴住？","t":[100,3112]},{"es":"-¿Y dónde quieres que vaya?","zh":"——多奇怪的念头！","t":[3112,5388]},{"es":"-No sé, a cualquier parte.","zh":"——可你要是不拴住它，它说不定会跑到哪儿去，走丢的……","t":[5388,7775]},{"es":"Derecho camino adelante…","zh":"这时我的小家伙又朗声笑了起来：——你以为它能跑到哪儿去呀？","t":[7775,9175]}]},{"id":"ch03p13","audio":true,"sents":[{"es":"Entonces el principito señaló con gravedad: -¡No importa, es tan pequeña mi tierra!","zh":"——去哪儿都行……","t":[100,4474]}]},{"id":"ch03p14","audio":true,"sents":[{"es":"Y agregó, quizás, con un poco de melancolía:","zh":"——随便哪儿吧。","t":[100,2462]}]},{"id":"ch03p15","audio":true,"sents":[{"es":"-Derecho, camino adelante…","zh":"于是小王子十分认真地说：——没关系，反正我那儿地方小得很……","t":[100,1612]},{"es":"no se puede ir muy lejos.","zh":"接着他有点忧伤地补了一句：——就算一直往前走，也走不了多远。","t":[1612,3050]}]}]},{"id":"ch04","title_es":"Capítulo 4","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":true,"sents":[{"es":"De esta manera supe una segunda cosa muy importante: su planeta de origen era apenas más grande que una casa.","zh":"就这样，我了解到了第二件重要的事。","t":[100,5976]}]},{"id":"ch04p01","audio":true,"sents":[{"es":"Esto no podía asombrarme mucho.","zh":"他的星球，恐怕比一栋普通的房子大不了多少！","t":[100,2988]},{"es":"Sabía muy bien que aparte de los grandes planetas como la Tierra, Júpiter, Marte, Venus, a los cuales se les ha dado nombre, existen otros centenares de ellos tan pequeños a veces, que es difícil distinguirlos aun con la ayuda del telescopio.","zh":"不过，这倒没怎么让我吃惊。","t":[2988,16462]},{"es":"Cuando un astrónomo descubre uno de estos planetas, le da por nombre un número.","zh":"其中有些小得很，用望远镜都很难看清。","t":[16462,21600]},{"es":"Le llama, por ejemplo, \"el asteroide 3251\".","zh":"每当天文学家发现这样一颗小行星，","t":[21600,25200]}]},{"id":"ch04p02","audio":true,"sents":[{"es":"Tengo poderosas razones para creer que el planeta del cual venía el principito era el asteroide B 612.","zh":"他只给它一个编号，而不给名字。","t":[100,4800]},{"es":"Este asteroide ha sido visto sólo una vez con el telescopio en 1909, por un astrónomo turco.","zh":"比如，他管它叫“小行星 3251”。","t":[4800,12324]}]},{"id":"ch04p03","audio":true,"sents":[{"es":"Este astrónomo hizo una gran demostración de su descubrimiento en un congreso Internacional de Astronomía.","zh":"我有充分的理由相信，小王子来自的那颗星球，就是 B-612 号小行星。","t":[100,6450]},{"es":"Pero nadie le creyó a causa de su manera de vestir.","zh":"他还在国际天文学大会上，就这一发现做了长篇报告。","t":[6450,9000]}]},{"id":"ch04p04","audio":true,"sents":[{"es":"Las personas mayores son así.","zh":"可是当时谁也不信他，因为他穿得太怪了。","t":[100,2875]},{"es":"Felizmente para la reputación del asteroide B 612, un dictador turco impuso a su pueblo, bajo pena de muerte, el vestido a la europea.","zh":"大人哪，就是这么一种人。","t":[2875,10875]}]},{"id":"ch04p05","audio":true,"sents":[{"es":"Entonces el astrónomo volvió a dar cuenta de su descubrimiento en 1920 y como lucía un traje muy elegante, todo el mundo aceptó su demostración.","zh":"幸亏为了 B-612 号小行星，土耳其的君主下令臣民们，违者处死，必须改穿欧式服装。","t":[100,8163]}]},{"id":"ch04p06","audio":true,"sents":[{"es":"Si les he contado de todos estos detalles sobre el asteroide B 612 y hasta les he confiado su número, es por consideración a las personas mayores.","zh":"到了 1920 年，那位天文学家重新做了一次报告。","t":[100,9312]},{"es":"A los mayores les gustan las cifras.","zh":"这一回他穿得十分体面，大家就都同意他的说法了。","t":[9312,12262]},{"es":"Cuando se les habla de un nuevo amigo, jamás preguntan sobre lo esencial del mismo.","zh":"大人们喜欢数字。","t":[12262,17575]},{"es":"Nunca se les ocurre preguntar: \"¿Qué tono tiene su voz?","zh":"当你跟他们讲起一位新朋友，他们从来不问最要紧的事。","t":[17575,21512]},{"es":"¿Qué juegos prefiere?","zh":"他们不会问他的嗓音好不好听，也不问爱玩什么游戏。","t":[21512,23600]},{"es":"¿Le gusta coleccionar mariposas?\" Pero en cambio preguntan: \"¿Qué edad tiene?","zh":"他们不关心他喜欢什么，也不关心他是不是收集蝴蝶。","t":[23600,29488]},{"es":"¿Cuántos hermanos?","zh":"他们只会问：他几岁了？","t":[29488,31450]},{"es":"¿Cuánto pesa?","zh":"体重多少？","t":[31450,33162]},{"es":"¿Cuánto gana su padre?\" Solamente con estos detalles creen conocerle.","zh":"他父亲挣多少钱？","t":[33162,38738]},{"es":"Si les decimos a las personas mayores: \"He visto una casa preciosa de ladrillo rosa, con geranios en las ventanas y palomas en el tejado\", jamás llegarán a imaginarse cómo es esa casa.","zh":"只有到这时候，他们才觉得算是了解他了。","t":[38738,48876]}]},{"id":"ch04p07","audio":true,"sents":[{"es":"Es preciso decirles: \"He visto una casa que vale cien mil pesos\".","zh":"如果你对大人们说，你看见一所漂亮的红砖房子，窗台上有天竺葵，屋顶上停着鸽子，他们是没法想象出它的。","t":[100,4762]},{"es":"Entonces exclaman entusiasmados: \"¡Oh, qué preciosa es!\"","zh":"你得对他们说，你看见的是一所值十万法郎的房子。","t":[4762,8037]}]},{"id":"ch04p08","audio":true,"sents":[{"es":"De tal manera, si les decimos: \"La prueba de que el principito ha existido está en que era un muchachito encantador, que reía y quería un cordero.","zh":"所以，如果你对他们说小王子存在，因为他与众不同，因为他会笑，还想要一只小羊（要知道，想要一只小羊，就证明你确实存在），他们只会耸耸肩，把你当成小孩子。","t":[100,8462]},{"es":"Querer un cordero es prueba de que se existe\", las personas mayores se encogerán de hombros y nos dirán que somos unos niños.","zh":"可如果你说他是乘着 B-612 号小行星来的，他们就会信以为真，不再拿这些问题来烦你。","t":[8462,15825]},{"es":"Pero si les decimos: \"el planeta de donde venía el principito era el asteroide B 612\", quedarán convencidas y no se preocuparán de hacer más preguntas.","zh":"大人们就是这么回事。","t":[15825,25312]},{"es":"Son así.","zh":"因此，也犯不着为这个生他们的气。","t":[25312,25900]}]},{"id":"ch04p09","audio":true,"sents":[{"es":"No hay por qué guardarles rencor.","zh":"孩子们对大人，应当宽宏大量才是。","t":[100,2825]},{"es":"Los niños deben ser muy indulgentes con las personas mayores.","zh":"当然，懂得生活的人，是不在乎那些数字的。","t":[2825,6137]}]},{"id":"ch04p10","audio":true,"sents":[{"es":"Pero nosotros, que sabemos comprender la vida, nos burlamos tranquilamente de los números.","zh":"我本想这样写：“从前呀，有一位小王子。","t":[100,5850]},{"es":"A mí me habría gustado más comenzar esta historia a la manera de los cuentos de hadas.","zh":"他住在一颗只比他自己大一点点的星球上。","t":[5850,10988]},{"es":"Me habría gustado decir:","zh":"他需要一个朋友……”","t":[10988,12375]}]},{"id":"ch04p11","audio":true,"sents":[{"es":"\"Era una vez un principito que habitaba un planeta apenas más grande que él y que tenía necesidad de un amigo…\" Para aquellos que comprenden la vida, esto hubiera parecido más real.","zh":"对于懂得生活的人，这样讲反倒更近乎真实。","t":[100,10087]}]},{"id":"ch04p12","audio":true,"sents":[{"es":"Porque no me gusta que mi libro sea tomado a la ligera.","zh":"我一点也不希望人们把我的书，当作消遣来读。","t":[100,3712]},{"es":"Siento tanta pena al contar estos recuerdos.","zh":"要知道，我的朋友带着他的小羊离开我，已经六年了。","t":[3712,6163]}]},{"id":"ch04p13","audio":true,"sents":[{"es":"Hace ya seis años que mi amigo se fue con su cordero.","zh":"我在这里试着把他描述下来，只是怕自己把他忘了。","t":[100,3750]},{"es":"Y si intento describirlo aquí es sólo con el fin de no olvidarlo.","zh":"要知道，忘掉一个朋友，是件叫人难过的事。","t":[3750,8162]},{"es":"Es muy triste olvidar a un amigo.","zh":"并不是每个人一生中都有过朋友。","t":[8162,10900]},{"es":"No todos han tenido un amigo.","zh":"我也可能变成那些只在乎数字的大人。","t":[10900,13525]},{"es":"Y yo puedo llegar a ser como las personas mayores, que sólo se interesan por las cifras.","zh":"到了我这把年纪，要重新学画画可真不容易，","t":[13525,19125]},{"es":"Para evitar esto he comprado una caja de lápices de colores.","zh":"尤其当初你六岁的时候，只试过两回——画外面的蟒蛇和里面的蟒蛇！","t":[19125,23088]},{"es":"¡Es muy duro, a mi edad, ponerse a aprender a dibujar, cuando en toda la vida no se ha hecho otra tentativa que la de una boa abierta y una boa cerrada a la edad de seis años!","zh":"不过，我当然会尽力画得像一些。","t":[23088,32775]},{"es":"Ciertamente que yo trataré de hacer retratos lo más parecido posibles, pero no estoy muy seguro de lograrlo.","zh":"虽说我一点也没把握能画好。","t":[32775,39525]},{"es":"Uno saldrá bien y otro no tiene parecido alguno.","zh":"这一幅画得还可以，那一幅就不大像……","t":[39525,43025]},{"es":"En las proporciones me equivoco también un poco.","zh":"至于身材的高矮，我也拿不准。","t":[43025,46412]},{"es":"Aquí el principito es demasiado grande y allá es demasiado pequeño.","zh":"他衣服的颜色，我也说不准。","t":[46412,50888]},{"es":"Dudo también sobre el color de su traje.","zh":"只好凭感觉，东猜西猜——这边试试，那边碰碰。","t":[50888,53925]},{"es":"Titubeo sobre esto y lo otro y unas veces sale bien y otras mal.","zh":"最后，有些重要的细节，我也可能画错。","t":[53925,58250]},{"es":"Es posible, en fin, que me equivoque sobre ciertos detalles muy importantes.","zh":"这一点，还请你们多多包涵。","t":[58250,63350]},{"es":"Pero habrá que perdonármelo ya que mi amigo no me daba nunca muchas explicaciones.","zh":"我的这位朋友，从来没向我解释过什么。","t":[63350,68350]},{"es":"Me creía semejante a sí mismo y yo, desgraciadamente, no sé ver un cordero a través de una caja.","zh":"可遗憾的是，我不会隔着箱壁看见小羊。","t":[68350,74512]},{"es":"Es posible que yo sea un poco como las personas mayores.","zh":"也许，我多少有点像大人了。","t":[74512,78512]},{"es":"He debido envejecer.","zh":"大概，我只是老了吧。","t":[78512,79550]}]}]},{"id":"ch05","title_es":"Capítulo 5","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":true,"sents":[{"es":"Cada día yo aprendía algo nuevo sobre el planeta, sobre la partida y sobre el viaje.","zh":"每天，我都能从他那儿知道一点关于他星球和他旅程起点的新鲜事。","t":[100,5388]},{"es":"Esto venía suavemente al azar de las reflexiones.","zh":"他总是碰到机会，才零零碎碎地讲上一点。","t":[5388,9150]},{"es":"De esta manera tuve conocimiento al tercer día, del drama de los baobabs.","zh":"而这件事，恰恰是因为那只小羊才弄明白的。","t":[9150,13112]}]},{"id":"ch05p01","audio":true,"sents":[{"es":"Fue también gracias al cordero y como preocupado por una profunda duda, cuando el principito me preguntó: -¿Es verdad que los corderos se comen los arbustos?","zh":"小王子想了很久，忽然问我：——小羊吃灌木，这是真的吧？","t":[100,8288]}]},{"id":"ch05p02","audio":true,"sents":[{"es":"-Sí, es cierto.","zh":"——是真的。","t":[100,2150]},{"es":"-¡Ah, qué contesto estoy!","zh":"——啊……那敢情好……","t":[2150,3426]}]},{"id":"ch05p03","audio":true,"sents":[{"es":"No comprendí por qué era tan importante para él que los corderos se comieran los arbustos.","zh":"可小王子又补了一句：——这么说，猴面包树它们也吃咯？","t":[100,5438]},{"es":"Pero el principito añadió:","zh":"我告诉小王子，猴面包树不是灌木，而是像教堂那么高的树；哪怕他把整整一队大象带上星球，也对付不了哪怕一棵猴面包树。","t":[5438,6738]}]},{"id":"ch05p04","audio":true,"sents":[{"es":"-Entonces se comen también los Baobabs.","zh":"想到他的星球上有一队大象，小王子不禁笑了起来。","t":[100,2137]}]},{"id":"ch05p05","audio":true,"sents":[{"es":"Le hice comprender al principito que los baobabs no son arbustos, sino árboles tan grandes como iglesias y que incluso si llevase consigo todo un rebaño de elefantes, el rebaño no lograría acabar con un solo baobab.","zh":"可他却很有见地地说：——可是猴面包树在长大之前，也曾经是小小的呀。","t":[100,11450]}]},{"id":"ch05p06","audio":true,"sents":[{"es":"Esta idea del rebaño de elefantes hizo reír al principito.","zh":"——那倒是真的！","t":[100,3250]}]},{"id":"ch05p07","audio":true,"sents":[{"es":"-Habría que poner los elefantes unos sobre otros…","zh":"——可你为什么偏要你的小羊去吃那些小猴面包树呢？","t":[100,2688]}]},{"id":"ch05p08","audio":true,"sents":[{"es":"Y luego añadió juiciosamente:","zh":"他回答我时，那神情仿佛说的是明摆着的道理：——为什么？","t":[100,1825]}]},{"id":"ch05p09","audio":true,"sents":[{"es":"-Los baobabs, antes de crecer, son muy pequeñitos.","zh":"我可是费了好大脑筋，才弄明白问题出在哪儿。","t":[100,2913]}]},{"id":"ch05p10","audio":true,"sents":[{"es":"-Es cierto.","zh":"说真的，在小王子的星球上，就像在别的星球上一样，有用的植物中间，也长着杂草。","t":[100,1738]},{"es":"Pero ¿por qué quieres que tus corderos coman los baobabs?","zh":"所以，土里既有好植物的好种子，也有坏植物的坏种子。","t":[1738,4475]}]},{"id":"ch05p11","audio":true,"sents":[{"es":"Me contestó: \"¡Bueno!","zh":"不过，种子是瞧不大出来的。","t":[100,2262]},{"es":"¡Vamos!\" como si hablara de una evidencia.","zh":"于是种子便抽出嫩芽。","t":[2262,5425]},{"es":"Me fue necesario un gran esfuerzo de inteligencia para comprender por mí mismo este problema.","zh":"起初它怯生生地朝着太阳伸展，是那么迷人又无害。","t":[5425,10012]}]},{"id":"ch05p12","audio":true,"sents":[{"es":"En efecto, en el planeta del principito había, como en todos los planetas, hierbas buenas y hierbas malas.","zh":"若是萝卜或玫瑰的嫩芽，这话倒不假。","t":[100,6350]},{"es":"Por consiguiente, de buenas semillas salían buenas hierbas y de las semillas malas, hierbas malas.","zh":"可要是杂草的芽，一认出来就得马上拔掉。","t":[6350,11187]}]},{"id":"ch05p13","audio":true,"sents":[{"es":"Pero las semillas son invisibles; duermen en el secreto de la tierra, hasta que un buen día una de ellas tiene la fantasía de despertarse.","zh":"而小王子的星球上，恰恰就有这种可怕的种子。","t":[100,8225]},{"es":"Entonces se alarga extendiendo hacia el sol, primero tímidamente, una encantadora ramita inofensiva.","zh":"那是猴面包树的种子。","t":[8225,14775]},{"es":"Si se trata de una ramita de rábano o de rosal, se la puede dejar que crezca como quiera.","zh":"星球的整片土壤，都被它们污染了。","t":[14775,19624]}]},{"id":"ch05p14","audio":true,"sents":[{"es":"Pero si se trata de una mala hierba, es preciso arrancarla inmediatamente en cuanto uno ha sabido reconocerla.","zh":"它会占满整个星球，把根须扎进星球的每一处。","t":[100,5888]}]},{"id":"ch05p15","audio":true,"sents":[{"es":"En el planeta del principito había semillas terribles…","zh":"要是星球太小，猴面包树又太多，它们干脆会把星球扯成碎片。","t":[100,3025]},{"es":"como las semillas del baobab.","zh":"所以，这是日常作息里非常重要的一条——小王子后来对我说。","t":[3025,5225]},{"es":"El suelo del planeta está infestado de ellas.","zh":"得让自己养成习惯，定期把那些小猴面包树拔掉，只要你能把它们和幼苗期的玫瑰丛分辨开来——它们小时候可像了。","t":[5225,8600]},{"es":"Si un baobab no se arranca a tiempo, no hay manera de desembarazarse de él más tarde; cubre todo el planeta y lo perfora con sus raíces.","zh":"这活儿挺乏味，不过也挺简单。","t":[8600,16900]},{"es":"Y si el planeta es demasiado pequeño y los baobabs son numerosos, lo hacen estallar.","zh":"有一回他劝我，尽量画一幅这样的画，好让我住处的孩子们能牢牢记住这件事。","t":[16900,21350]}]},{"id":"ch05p16","audio":true,"sents":[{"es":"\"Es una cuestión de disciplina, me decía más tarde el principito.","zh":"“要是他们有一天出门远行，”他对我说，“这也许能帮上他们的忙。","t":[100,4562]},{"es":"Cuando por la mañana uno termina de arreglarse, hay que hacer cuidadosamente la limpieza del planeta.","zh":"可唯独猴面包树不行。","t":[4562,10575]},{"es":"Hay que dedicarse regularmente a arrancar los baobabs, cuando se les distingue de los rosales, a los cuales se parecen mucho cuando son pequeñitos.","zh":"不然就要闯大祸。","t":[10575,19138]},{"es":"Es un trabajo muy fastidioso pero muy fácil\".","zh":"我认识一颗星球，上面住着一个懒汉。","t":[19138,21562]}]},{"id":"ch05p17","audio":true,"sents":[{"es":"Y un día me aconsejó que me dedicara a realizar un hermoso dibujo, que hiciera comprender a los niños de la tierra estas ideas.","zh":"他对三棵小苗一直不理不睬……”","t":[100,7688]},{"es":"\"Si alguna vez viajan, me decía, esto podrá servirles mucho.","zh":"我向来不爱教训人。","t":[7688,12275]},{"es":"A veces no hay inconveniente en dejar para más tarde el trabajo que se ha de hacer; pero tratándose de baobabs, el retraso es siempre una catástrofe.","zh":"然而，猴面包树带来的威胁鲜为人知，而对流落到小行星上的人来说，危险又是如此之大，这一回，我倒不妨破个例。","t":[12275,20738]},{"es":"Yo he conocido un planeta, habitado por un perezoso que descuidó tres arbustos…\"","zh":"我要说：“孩子们！","t":[20738,25175]}]},{"id":"ch05p18","audio":true,"sents":[{"es":"Siguiendo las indicaciones del principito, dibujé dicho planeta.","zh":"我正是想以此提醒我那些年轻的朋友们，留意他们早已身处的危险。","t":[100,4538]},{"es":"Aunque no me gusta el papel de moralista, el peligro de los baobabs es tan desconocido y los peligros que puede correr quien llegue a perderse en un asteroide son tan grandes, que no vacilo en hacer una excepción y exclamar: \"¡Niños, atención a los baobabs!\" Y sólo con el fin de advertir a mis amigos de estos peligros a que se exponen desde hace ya tiempo sin saberlo, es por lo que trabajé y puse tanto empeño en realizar este dibujo.","zh":"我自己也是画完这幅画，才察觉到这危险的。","t":[4538,28175]},{"es":"La lección que con él podía dar, valía la pena.","zh":"这幅画，值得好好下一番功夫。","t":[28175,31638]},{"es":"Es muy posible que alguien me pregunte por qué no hay en este libro otros dibujos tan grandiosos como el dibujo de los baobabs.","zh":"也许你会问我——为什么这本书里，没有别的画能和这幅猴面包树的画一样气派？","t":[31638,38525]},{"es":"La respuesta es muy sencilla: he tratado de hacerlos, pero no lo he logrado.","zh":"我也努力过，可就是画不出来。","t":[38525,43650]},{"es":"Cuando dibujé los baobabs estaba animado por un sentimiento de urgencia.","zh":"而当我画猴面包树时，鼓舞我的，是这件事本身的必要和紧迫。","t":[43650,47300]}]}]},{"id":"ch06","title_es":"Capítulo 6","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":true,"sents":[{"es":"¡Ah, principito, cómo he ido comprendiendo lentamente tu vida melancólica!","zh":"啊，小王子！","t":[100,4762]},{"es":"Durante mucho tiempo tu única distracción fue la suavidad de las puestas de sol.","zh":"我渐渐明白了，你为什么会那样忧伤。","t":[4762,9625]},{"es":"Este nuevo detalle lo supe al cuarto día, cuando me dijiste:","zh":"你长久以来，只用那温柔的落日余晖来慰藉自己。","t":[9625,12837]}]},{"id":"ch06p01","audio":true,"sents":[{"es":"-Me gustan mucho las puestas de sol; vamos a ver una puesta de sol…","zh":"我是在","t":[100,3676]}]},{"id":"ch06p02","audio":true,"sents":[{"es":"-Tendremos que esperar…","zh":"你生活中的这件新鲜事，是在第四天早晨得知的——那天你对我说：——我可喜欢看日落了。","t":[100,1438]},{"es":"-¿Esperar qué?","zh":"——得等一会儿……","t":[1438,2138]}]},{"id":"ch06p03","audio":true,"sents":[{"es":"-Que el sol se ponga.","zh":"——等什么呀？","t":[100,1175]}]},{"id":"ch06p04","audio":true,"sents":[{"es":"Pareciste muy sorprendido primero, y después te reíste de ti mismo.","zh":"——等到太阳开始落山呀。","t":[100,4662]},{"es":"Y me dijiste:","zh":"说这话时，你先是大觉意外，接着又自己笑起自己来。","t":[4662,5438]}]},{"id":"ch06p05","audio":true,"sents":[{"es":"-Siempre me creo que estoy en mi tierra.","zh":"——我老觉得，自己还在家里呢。","t":[100,2100]}]},{"id":"ch06p06","audio":true,"sents":[{"es":"En efecto, como todo el mundo sabe, cuando es mediodía en Estados Unidos, en Francia se está poniendo el sol.","zh":"真的——当美洲是正午，全世界都知道，法兰西的太阳已经下山了。","t":[100,6550]},{"es":"Sería suficiente poder trasladarse a Francia en un minuto para asistir a la puesta del sol, pero desgraciadamente Francia está demasiado lejos.","zh":"只要能在一分钟里赶到法兰西，就能亲眼看到这场日落。","t":[6550,15125]},{"es":"En cambio, sobre tu pequeño planeta te bastaba arrastrar la silla algunos pasos para presenciar el crepúsculo cada vez que lo deseabas…","zh":"可惜法兰西太远了。","t":[15125,22212]},{"es":"-¡Un día vi ponerse el sol cuarenta y tres veces!","zh":"这样你就能随心所欲地看黄昏，看多久都行。","t":[22212,24526]}]},{"id":"ch06p07","audio":true,"sents":[{"es":"Y un poco más tarde añadiste: -¿Sabes?","zh":"——有一天，我居然看了四十三次日落！","t":[100,3262]},{"es":"Cuando uno está verdaderamente triste le gusta ver las puestas de sol.","zh":"过了片刻你又补了一句：——你晓得吗，人一伤心，看日落就特别好……","t":[3262,6750]}]},{"id":"ch06p08","audio":true,"sents":[{"es":"-El día que la viste cuarenta y tres veces estabas muy triste ¿verdad?","zh":"——这么说来，你看那四十三次日落的时候，心里特别难过咯？","t":[100,3537]}]},{"id":"ch06p09","audio":true,"sents":[{"es":"Pero el principito no respondió.","zh":"可小王子对这个问题，什么也没回答。","t":[100,1725]}]}]},{"id":"ch07","title_es":"Capítulo 7","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":true,"sents":[{"es":"Al quinto día y también en relación con el cordero, me fue revelado este otro secreto de la vida del principito.","zh":"小王子生活里的这个秘密，是我在第五天发现的，又是因为那只小羊。","t":[100,6925]},{"es":"Me preguntó bruscamente y sin preámbulo, como resultado de un problema largamente meditado en silencio:","zh":"他忽然毫无来由地问我，仿佛这个问题已想了许久：——小羊既然吃灌木，那花是不是也吃？","t":[6925,12312]}]},{"id":"ch07p01","audio":true,"sents":[{"es":"-Si un cordero se come los arbustos, se comerá también las flores ¿no?","zh":"——带刺的花也吃？","t":[100,3912]}]},{"id":"ch07p02","audio":true,"sents":[{"es":"-Un cordero se come todo lo que encuentra.","zh":"——对，带刺的也吃。","t":[100,3175]},{"es":"-¿Y también las flores que tienen espinas?","zh":"——那刺呢？","t":[3175,5337]}]},{"id":"ch07p03","audio":true,"sents":[{"es":"-Sí; también las flores que tienen espinas.","zh":"这个我可不知道。","t":[100,2525]}]},{"id":"ch07p04","audio":true,"sents":[{"es":"-Entonces, ¿para qué le sirven las espinas?","zh":"再说我当时正忙着，想拧开发动机上一个拧不动的螺丝。","t":[100,2425]}]},{"id":"ch07p05","audio":true,"sents":[{"es":"Confieso que no lo sabía.","zh":"我心里很着急，因为故障看来相当严重。","t":[100,2488]},{"es":"Estaba yo muy ocupado tratando de destornillar un perno demasiado apretado del motor; la avería comenzaba a parecerme cosa grave y la circunstancia de que se estuviera agotando mi provisión de agua, me hacía temer lo peor.","zh":"——刺。","t":[2488,15012]},{"es":"-¿Para qué sirven las espinas?","zh":"——到底有什么用？","t":[15012,16513]}]},{"id":"ch07p06","audio":true,"sents":[{"es":"El principito no permitía nunca que se dejara sin respuesta una pregunta formulada por él.","zh":"小王子一旦开了口问，就不会罢休。","t":[100,5512]},{"es":"Irritado por la resistencia que me oponía el perno, le respondí lo primero que se me ocurrió:","zh":"——它们一点用也没有。","t":[5512,10275]}]},{"id":"ch07p07","audio":true,"sents":[{"es":"-Las espinas no sirven para nada; son pura maldad de las flores.","zh":"——是花在使坏罢了。","t":[100,4700]},{"es":"-¡Oh!","zh":"——噢！","t":[4700,4838]}]},{"id":"ch07p08","audio":true,"sents":[{"es":"Y después de un silencio, me dijo con una especie de rencor: -¡No te creo!","zh":"——花是柔弱的。","t":[100,4850]},{"es":"Las flores son débiles.","zh":"——它们单纯。","t":[4850,7225]},{"es":"Son ingenuas.","zh":"——它们尽自己的力量保护自己。","t":[7225,9162]},{"es":"Se defienden como pueden.","zh":"我什么也没回答。","t":[9162,11500]},{"es":"Se creen terribles con sus espinas…","zh":"那一刻我对自己说：“这颗螺丝要是拧不开，我就用锤子把它砸出来。”","t":[11500,13538]}]},{"id":"ch07p09","audio":true,"sents":[{"es":"No le respondí nada; en aquel momento me estaba diciendo a mí mismo: \"Si este perno me resiste un poco más, lo haré saltar de un martillazo\".","zh":"可小王子又用一个问题把我岔开：——你难道觉得……","t":[100,8700]},{"es":"El principito me interrumpió de nuevo mis pensamientos: -¿Tú crees que las flores…?","zh":"——不是啦！","t":[8700,12763]}]},{"id":"ch07p10","audio":true,"sents":[{"es":"No, no creo nada!","zh":"——不是！","t":[100,2500]},{"es":"Te he respondido cualquier cosa para que te calles.","zh":"——我什么也没觉得。","t":[2500,5975]},{"es":"Tengo que ocuparme de cosas serias.","zh":"——我正忙着正经事呢！","t":[5975,7875]}]},{"id":"ch07p11","audio":true,"sents":[{"es":"Me miró estupefacto.","zh":"他惊讶地望了望我。","t":[100,2262]},{"es":"-¡De cosas serias!","zh":"——正经事？","t":[2262,3287]}]},{"id":"ch07p12","audio":true,"sents":[{"es":"Me miraba con mi martillo en la mano, los dedos llenos de grasa e inclinado sobre algo que le parecía muy feo.","zh":"我正俯身去对付那个在他看来丑陋的物件。","t":[100,6575]},{"es":"-¡Hablas como las personas mayores!","zh":"——你说话跟大人一模一样！","t":[6575,8400]}]},{"id":"ch07p13","audio":true,"sents":[{"es":"Me avergonzó un poco.","zh":"这话让我有点发窘，他却毫不留情地补了一句：——你全乱套了……","t":[100,2312]},{"es":"Pero él, implacable, añadió: -¡Lo confundes todo…todo lo mezclas…!","zh":"——你什么也不懂！","t":[2312,6287]}]},{"id":"ch07p14","audio":true,"sents":[{"es":"Estaba verdaderamente irritado; sacudía la cabeza, agitando al viento sus cabellos dorados.","zh":"他迎风抖了抖那一头金发：——我认识一颗星球，上面住着一位面色通红的先生。","t":[100,5374]}]},{"id":"ch07p15","audio":true,"sents":[{"es":"-Conozco un planeta donde vive un señor muy colorado, que nunca ha olido una flor, ni ha mirado una estrella y que jamás ha querido a nadie.","zh":"他从来不闻花香。","t":[100,8175]},{"es":"En toda su vida no ha hecho más que sumas.","zh":"他从来没抬头看过星星。","t":[8175,11438]},{"es":"Y todo el día se lo pasa repitiendo como tú: \"¡Yo soy un hombre serio, yo soy un hombre serio!\"…","zh":"他只管算账。","t":[11438,17638]},{"es":"Al parecer esto le llema de orgullo.","zh":"他整天像你一样，翻来覆去地说：“我是个正经人！","t":[17638,20450]},{"es":"Pero eso no es un hombre, ¡es un hongo!","zh":"我是个正经人！”","t":[20450,23412]},{"es":"-¿Un qué?","zh":"可他哪里是人，简直是朵蘑菇！","t":[23412,23800]}]},{"id":"ch07p16","audio":true,"sents":[{"es":"-Un hongo.","zh":"——谁？","t":[100,650]}]},{"id":"ch07p17","audio":true,"sents":[{"es":"El principito estaba pálido de cólera.","zh":"——蘑菇！","t":[100,2087]}]},{"id":"ch07p18","audio":true,"sents":[{"es":"-Hace millones de años que las flores tiene espinas y hace también millones de años que los corderos, a pesar de las espinas, se comen las flores.","zh":"——花长刺，已经有几百万年了。","t":[100,8562]},{"es":"¿Es que no es cosa seria averiguar por qué las flores pierden el tiempo fabricando unas espinas que no les sirven para nada?","zh":"尽管几百万年来，羊一直在吃花。","t":[8562,15638]},{"es":"¿Es que no es importante la guerra de los corderos y las flores?","zh":"想弄明白，它们为何偏要长出那些毫无用处的刺，这难道不算正经？","t":[15638,19800]},{"es":"¿No es esto más serio e importante que las sumas de un señor gordo y colorado?","zh":"这难道还比不上那位红脸先生的算账，重要、正经？","t":[19800,24612]},{"es":"Y si yo sé de una flor única en el mundo y que no existe en ninguna parte más que en mi planeta; si yo sé que un buen día un corderillo puede aniquilarla sin darse cuenta de ello, ¿es que esto no es importante?","zh":"如果我明知，世上独一无二、只长在我星球上的那朵花，会在某个清晨，被一只根本不懂自己在做什么的小羊轻易毁掉——这难道无关紧要？","t":[24612,35213]}]},{"id":"ch07p19","audio":true,"sents":[{"es":"El principito enrojeció y después continuó:","zh":"他涨红了脸，接着说：——倘若你爱上了一朵花，它生长在千万颗星星之中，那么当你仰望星空时，这就足以让你感到幸福。","t":[100,2424]}]},{"id":"ch07p20","audio":true,"sents":[{"es":"-Si alguien ama a una flor de la que sólo existe un ejemplar en millones y millones de estrellas, basta que las mire para ser dichoso.","zh":"——可要是小羊把那朵花吃了，就好像所有的星星一下子都熄灭了！","t":[100,7538]},{"es":"Puede decir satisfecho: \"Mi flor está allí, en alguna parte…\" ¡Pero si el cordero se la come, para él es como si de pronto todas las estrellas se apagaran!","zh":"——这难道还不重要？！","t":[7538,17575]},{"es":"¡Y esto no es importante!","zh":"他再也说不出话，忽然放声大哭起来。","t":[17575,19013]}]},{"id":"ch07p21","audio":true,"sents":[{"es":"No pudo decir más y estalló bruscamente en sollozos.","zh":"我把手里的工具搁到一旁。","t":[100,3050]}]},{"id":"ch07p22","audio":true,"sents":[{"es":"La noche había caído.","zh":"锤子、螺丝、口渴，甚至连死亡，对我都不再重要。","t":[100,2275]},{"es":"Yo había soltado las herramientas y ya no importaban nada el martillo, el perno, la sed y la muerte.","zh":"在我的地球上，在一颗星星、一颗星球上，小王子在哭泣，得去安慰他才是。","t":[2275,8525]},{"es":"¡Había en una estrella, en un planeta, el mío, la Tierra, un principito a quien consolar!","zh":"我要给你的小羊画个嘴套。","t":[8525,14100]},{"es":"Lo tomé en mis brazos y lo mecí diciéndole: \"la flor que tú quieres no corre peligro…","zh":"给你的花画一身铠甲……”","t":[14100,18775]},{"es":"te dibujaré un bozal para tu cordero y una armadura para la flor…te…\".","zh":"我实在不知道，该说些什么才好。","t":[18775,23075]},{"es":"No sabía qué decirle, cómo consolarle y hacer que tuviera nuevamente confianza en mí; me sentía torpe.","zh":"我不知道，怎样才能叩开他的心扉，走进他的灵魂……","t":[23075,29550]},{"es":"¡Es tan misterioso el país de las lágrimas!","zh":"因为那泪水的国度，是如此难以捉摸，又如此神秘……","t":[29550,31750]}]}]},{"id":"ch08","title_es":"Capítulo 8","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":true,"sents":[{"es":"Aprendí bien pronto a conocer mejor esta flor.","zh":"不久，我对这朵花有了更多的了解。","t":[100,3438]},{"es":"Siempre había habido en el planeta del principito flores muy simples adornadas con una sola fila de pétalos que apenas ocupaban sitio y a nadie molestaban.","zh":"小王子的星球上，原本有许多朴素的小花，花瓣普普通通。","t":[3438,12338]},{"es":"Aparecían entre la hierba una mañana y por la tarde se extinguían.","zh":"它们不占多少地方，也不招谁惹谁。","t":[12338,16600]},{"es":"Pero aquella había germinado un día de una semilla llegada de quién sabe dónde, y el principito había vigilado cuidadosamente desde el primer día aquella ramita tan diferente de las que él conocía.","zh":"可那一朵，是从不知哪儿飘来的种子里长出来的；小王子仔仔细细地打量着这株与众不同的嫩芽。","t":[16600,27212]},{"es":"Podía ser una nueva especie de Baobab.","zh":"没准儿，它是某一种新型猴面包树的芽呢。","t":[27212,30200]},{"es":"Pero el arbusto cesó pronto de crecer y comenzó a echar su flor.","zh":"不过，这小灌木很快就不长了，眼看要开花。","t":[30200,34400]},{"es":"El principito observó el crecimiento de un enorme capullo y tenía le convencimiento de que habría de salir de allí una aparición milagrosa; pero la flor no acababa de preparar su belleza al abrigo de su envoltura verde.","zh":"小王子眼看着一个大花苞长出来，料定奇迹就要出现；可那花躲在绿叶的庇护下，迟迟不肯展露芳容。","t":[34400,45100]}]},{"id":"ch08p01","audio":true,"sents":[{"es":"Elegía con cuidado sus colores, se vestía lentamente y se ajustaba uno a uno sus pétalos.","zh":"它慢条斯理地梳妆，一片花瓣、一片花瓣地舒展。","t":[100,6100]},{"es":"No quería salir ya ajada como las amapolas; quería aparecer en todo el esplendor de su belleza.","zh":"它可不愿像什么罂粟似的，毛毛躁躁地就冒出来。","t":[6100,12275]},{"es":"¡Ah, era muy coqueta aquella flor!","zh":"它要的是，以绝美的姿容隆重登场。","t":[12275,15225]},{"es":"Su misteriosa preparación duraba días y días.","zh":"果然！","t":[15225,18825]},{"es":"Hasta que una mañana, precisamente al salir el sol se mostró espléndida.","zh":"它那神秘的筹备，日复一日地拖着。","t":[18825,22526]}]},{"id":"ch08p02","audio":true,"sents":[{"es":"La flor, que había trabajado con tanta precisión, dijo bostezando: -¡Ah, perdóname…","zh":"终于有一天清晨，恰在日出时分，这位美人儿露面了。","t":[100,4838]},{"es":"apenas acabo de despertarme…","zh":"虽说它为出场费了长久又勤苦的功夫，可它打了个哈欠，开口便说：——啊！","t":[4838,6600]},{"es":"estoy toda despeinada…!","zh":"——我还没完全睡醒呢……","t":[6600,7900]}]},{"id":"ch08p03","audio":true,"sents":[{"es":"El principito no pudo contener su admiración: -¡Qué hermosa eres!","zh":"——我这副模样，乱糟糟的……","t":[100,4575]},{"es":"-¿Verdad?","zh":"可小王子压不住心里的赞叹，喊道：——您太美了！","t":[4575,5962]},{"es":"-respondió dulcemente la flor-.","zh":"——当真吗？","t":[5962,8600]},{"es":"He nacido al mismo tiempo que el sol.","zh":"——她轻声说道。","t":[8600,11450]},{"es":"El principito adivinó exactamente que ella no era muy modesta ciertamente, pero ¡era tan conmovedora!","zh":"小王子明白，这花儿未免有点儿不知分寸，可它是那么惹人怜爱！","t":[11450,16874]}]},{"id":"ch08p04","audio":true,"sents":[{"es":"-Me parece que ya es hora de desayunar - añadió la flor -; si tuvieras la bondad de pensar un poco en mí…","zh":"——这会儿，该用早餐了吧，——美人儿紧接着说。","t":[100,5488]}]},{"id":"ch08p05","audio":true,"sents":[{"es":"Y el principito, muy confuso, habiendo ido a buscar una regadera la roció abundantemente con agua fresca.","zh":"——您会照应我的吧？","t":[100,5500]}]},{"id":"ch08p06","audio":true,"sents":[{"es":"Y así, ella lo había atormentado con su vanidad un poco sombría.","zh":"小王子又激动又局促，找来洒水壶，殷勤地伺候起花儿来。","t":[100,4650]},{"es":"Un día, por ejemplo, hablando de sus cuatro espinas, dijo al principito: -¡Ya pueden venir los tigres, con sus garras!","zh":"比如有一天，它谈起自己的四根刺，对他说：——没准儿，老虎会带着吓人的爪子闯到这儿来呢！","t":[4650,11074]}]},{"id":"ch08p07","audio":true,"sents":[{"es":"-No hay tigres en mi planeta -observó el principito- y, además, los tigres no comen hierba.","zh":"——我的星球上没有老虎，——小王子反驳道。","t":[100,5112]}]},{"id":"ch08p08","audio":true,"sents":[{"es":"-Yo no soy una hierba -respondió dulcemente la flor.","zh":"——再说了，老虎不吃草。","t":[100,3050]}]},{"id":"ch08p09","audio":true,"sents":[{"es":"-Perdóname…","zh":"——我又不是草，——它小声答道。","t":[100,688]}]},{"id":"ch08p10","audio":true,"sents":[{"es":"-No temo a los tigres, pero tengo miedo a las corrientes de aire.","zh":"——老虎我倒是一点也不怕，可我顶怕穿堂风。","t":[100,4438]},{"es":"¿No tendrás un biombo?","zh":"您这儿有屏风吗？","t":[4438,5625]}]},{"id":"ch08p11","audio":true,"sents":[{"es":"\"Miedo a las corrientes de aire no es una suerte para una planta -pensó el principito-.","zh":"“想想看吧！","t":[100,5325]},{"es":"Esta flor es demasiado complicada…\" -Por la noche me cubrirás con un fanal…","zh":"怕穿堂风！","t":[5325,9525]},{"es":"hace mucho frío en tu tierra.","zh":"——傍晚您得用玻璃罩把我罩起来。","t":[9525,11850]},{"es":"No se está muy a gusto; allá de donde yo vengo…","zh":"您这地方又冷又不舒服。","t":[11850,14574]}]},{"id":"ch08p12","audio":true,"sents":[{"es":"La flor se interrumpió; había llegado allí en forma de semilla y no era posible que conociera otros mundos.","zh":"我来的那个地方呀……","t":[100,6076]}]},{"id":"ch08p13","audio":true,"sents":[{"es":"Humillada por haberse dejado sorprender inventando un mentira tan ingenua, tosió dos o tres veces para atraerse la simpatía del principito.","zh":"可它说到这儿，突然住了口。","t":[100,8350]},{"es":"-¿Y el biombo?","zh":"为了掩饰自己随口撒的那个小谎，它轻轻咳了几声，好让小王子觉得自己理亏。","t":[8350,8987]}]},{"id":"ch08p14","audio":true,"sents":[{"es":"-Iba a buscarlo, pero como no dejabas de hablarme…","zh":"——那屏风到底在哪儿呀？","t":[100,2638]}]},{"id":"ch08p15","audio":true,"sents":[{"es":"Insistió en su tos para darle al menos remordimientos.","zh":"——我本要去拿，可您一直跟我说话来着！","t":[100,3163]}]},{"id":"ch08p16","audio":true,"sents":[{"es":"De esta manera el principito, a pesar de la buena voluntad de su amor, había llegado a dudar de ella.","zh":"于是它咳得更响，好让小王子更加过意不去。","t":[100,6275]},{"es":"Había tomado en serio palabras sin importancia y se sentía desgraciado.","zh":"他把花儿那些空洞的话当了真，为此受尽了折磨。","t":[6275,10000]}]},{"id":"ch08p17","audio":true,"sents":[{"es":"\"Yo no debía hacerle caso -me confesó un día el principito- nunca hay que hacer caso a las flores, basta con mirarlas y olerlas.","zh":"“我不该去听它的，”他后来对我坦白说。","t":[100,8050]},{"es":"Mi flor embalsamaba el planeta, pero yo no sabía gozar con eso…","zh":"——花儿说的话，不必去听。","t":[8050,12500]},{"es":"Aquella historia de garra y tigres que tanto me molestó, hubiera debido enternecerme\".","zh":"该欣赏它们，该去闻它们的芬芳。","t":[12500,17113]}]},{"id":"ch08p18","audio":true,"sents":[{"es":"Y me contó todavía:","zh":"那桩老虎爪子的事，本叫我那么光火，我早该警觉才是……”","t":[100,1224]}]},{"id":"ch08p19","audio":true,"sents":[{"es":"\"¡No supe comprender nada entonces!","zh":"他还对我吐露了另一桩心事：“那时我什么也不懂！","t":[100,3125]},{"es":"Debí juzgarla por sus actos y no por sus palabras.","zh":"我本该看它的行动，而不是听它的言语。","t":[3125,6875]},{"es":"¡La flor perfumaba e iluminaba mi vida y jamás debí huir de allí!","zh":"它把芬芳赠予我，照亮了我的生活。","t":[6875,11200]},{"es":"¡No supe adivinar la ternura que ocultaban sus pobres astucias!","zh":"我本该在它的耍小性子里，看出那份温柔与娇弱。","t":[11200,15575]},{"es":"¡Son tan contradictorias las flores!","zh":"花儿的心思，就是这么矛盾！","t":[15575,18662]},{"es":"Pero yo era demasiado joven para saber amarla\".","zh":"可我那时太不懂事，还不晓得怎样去爱它。”","t":[18662,21125]}]}]},{"id":"ch09","title_es":"Capítulo 9","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":true,"sents":[{"es":"Creo que el principito aprovechó la migración de una bandada de pájaros silvestres para su evasión.","zh":"我想，他是搭迁徙的候鸟，才逃离了星球。","t":[100,5875]},{"es":"La mañana de la partida, puso en orden el planeta.","zh":"临走前的那个清晨，他把星球仔仔细细地收拾了一遍。","t":[5875,9625]},{"es":"Deshollinó cuidadosamente sus volcanes en actividad, de los cuales poseía dos, que le eran muy útiles para calentar el desayuno todas las mañanas.","zh":"他星球上，有两座这样的火山。","t":[9625,18538]},{"es":"Tenía, además, un volcán extinguido.","zh":"每天早晨，借着它们热早饭，可方便啦。","t":[18538,21625]},{"es":"Deshollinó también el volcán extinguido, pues, como él decía, nunca se sabe lo que puede ocurrir.","zh":"其中一座是死火山，可小王子常对自己说：“谁知道什么时候用得着呢。”","t":[21625,27662]},{"es":"Si los volcanes están bien deshollinados, arden sus erupciones, lenta y regularmente.","zh":"所以，死火山他也照样疏通了。","t":[27662,33450]},{"es":"Las erupciones volcánicas son como el fuego de nuestras chimeneas.","zh":"火山喷发嘛，就像烟囱里迸出的火星。","t":[33450,37900]},{"es":"Es evidente que en nuestra Tierra no hay posibilidad de deshollinar los volcanes; los hombres somos demasiado pequeños.","zh":"可惜在我们地球上，人太小了，没法疏通自己的火山。","t":[37900,44875]},{"es":"Por eso nos dan tantos disgustos.","zh":"正因如此，火山才常常惹出那么多麻烦。","t":[44875,46837]}]},{"id":"ch09p01","audio":true,"sents":[{"es":"El principito arrancó también con un poco de melancolía los últimos brotes de baobabs.","zh":"小王子还带着几分不舍，把最后几株猴面包树的嫩芽也拔掉了。","t":[100,5338]},{"es":"Creía que no iba a volver nunca.","zh":"那天清晨，这桩习惯了的活计，叫他觉得格外舒心。","t":[5338,8112]},{"es":"Pero todos aquellos trabajos le parecieron aquella mañana extremadamente dulces.","zh":"当他最后一次给花浇了水，正要把它罩进玻璃罩里时，他几乎要哭出来了。","t":[8112,13300]},{"es":"Y cuando regó por última vez la flor y se dispuso a ponerla al abrigo del fanal, sintió ganas de llorar.","zh":"——再见，——他对花儿说。","t":[13300,18788]}]},{"id":"ch09p02","audio":true,"sents":[{"es":"-Adiós -le dijo a la flor.","zh":"可花儿没有回答他。","t":[100,2612]},{"es":"Esta no respondió.","zh":"美人儿轻轻咳了一声。","t":[2612,3724]}]},{"id":"ch09p03","audio":true,"sents":[{"es":"-Adiós -repitió el principito.","zh":"当然，这可不是因为感冒。","t":[100,1913]}]},{"id":"ch09p04","audio":true,"sents":[{"es":"La flor tosió, pero no porque estuviera resfriada.","zh":"——我从前真傻，——它终于开口说。","t":[100,2724]}]},{"id":"ch09p05","audio":true,"sents":[{"es":"-He sido una tonta -le dijo al fin la flor-.","zh":"——原谅我吧，你要尽量过得快活。","t":[100,3438]},{"es":"Perdóname.","zh":"他愣住了，手里还端着玻璃罩，一时不知所措。","t":[3438,5050]},{"es":"Procura ser feliz.","zh":"他没料到，它会这么温柔。","t":[5050,6100]}]},{"id":"ch09p06","audio":true,"sents":[{"es":"Se sorprendió por la ausencia de reproches y quedó desconcertado, con el fanal en el aire, no comprendiendo esta tranquila mansedumbre.","zh":"——哼，我当然是爱你的，——花儿对他说。","t":[100,7000]}]},{"id":"ch09p07","audio":true,"sents":[{"es":"-Sí, yo te quiero -le dijo la flor-, ha sido culpa mía que tú no lo sepas; pero eso no tiene importancia.","zh":"不过现在这都不打紧了。","t":[100,5750]}]},{"id":"ch09p08","audio":true,"sents":[{"es":"Y tú has sido tan tonto como yo.","zh":"你和我一样傻。","t":[100,2850]},{"es":"Trata de ser feliz…","zh":"愿你快乐。","t":[2850,4862]},{"es":"Y suelta de una vez ese fanal; ya no lo quiero.","zh":"把那个罩子扔一边去吧。","t":[4862,7562]}]},{"id":"ch09p09","audio":true,"sents":[{"es":"-Pero el viento…","zh":"——那穿堂风呢？","t":[100,800]}]},{"id":"ch09p10","audio":true,"sents":[{"es":"-No estoy tan resfriada como para…","zh":"——我还没那么容易伤风。","t":[100,2938]},{"es":"El aire fresco de la noche me hará bien.","zh":"夜里的新鲜空气，对我有好处。","t":[2938,5912]},{"es":"Soy una flor.","zh":"我好歹是朵花呀。","t":[5912,6763]}]},{"id":"ch09p11","audio":true,"sents":[{"es":"-Y los animales…","zh":"——要是我还想结识蝴蝶，挨上两三条毛毛虫，倒也不坏。","t":[100,1000]}]},{"id":"ch09p12","audio":true,"sents":[{"es":"-Será necesario que soporte dos o tres orugas, si quiero conocer las mariposas; creo que son muy hermosas.","zh":"听说，蝴蝶美极了。","t":[100,7100]},{"es":"Si no ¿quién vendrá a visitarme?","zh":"不然，谁来探望我呢？","t":[7100,9938]},{"es":"Tú estarás muy lejos.","zh":"你可是要远走他乡了。","t":[9938,12162]},{"es":"En cuanto a las fieras, no las temo: yo tengo mis garras.","zh":"我自有我的爪子呢。","t":[12162,15537]}]},{"id":"ch09p13","audio":true,"sents":[{"es":"Y le mostraba ingenuamente sus cuatro espinas.","zh":"说着，它天真地亮了亮自己的四根刺。","t":[100,3600]},{"es":"Luego añadió:","zh":"接着它又说：——行了，别磨蹭！","t":[3600,4450]}]},{"id":"ch09p14","audio":true,"sents":[{"es":"-Y no prolongues más tu despedida.","zh":"真叫人受不了！","t":[100,2912]},{"es":"Puesto que has decidido partir, vete de una vez.","zh":"它不愿让他看见自己眼泪汪汪的样子。","t":[2912,5450]}]},{"id":"ch09p15","audio":true,"sents":[{"es":"La flor no quería que la viese llorar: era tan orgullosa..","zh":"因为，这是一朵骄傲的花。","t":[100,3238]}]}]},{"id":"ch10","title_es":"Capítulo 10","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":true,"sents":[{"es":"Se encontraba en la región de los asteroides 325, 326, 327, 328, 329 y 330.","zh":"小王子来到 325、326、327、329、330 这几颗小行星附近。","t":[100,8712]},{"es":"Para ocuparse en algo e instruirse al mismo tiempo decidió visitarlos.","zh":"他决定去拜访它们，好让自己有事做，也学点东西。","t":[8712,14426]}]},{"id":"ch10p01","audio":true,"sents":[{"es":"El primero estaba habitado por un rey.","zh":"第一颗小行星上，住着一位国王。","t":[100,3025]},{"es":"El rey, vestido de púrpura y armiño, estaba sentado sobre un trono muy sencillo y, sin embargo, majestuoso.","zh":"他披着白鼬皮镶边的紫红色袍子，坐在一张简朴而又威严的宝座上。","t":[3025,9113]}]},{"id":"ch10p02","audio":true,"sents":[{"es":"-¡Ah, -exclamó el rey al divisar al principito-, aquí tenemos un súbdito!","zh":"——啊！","t":[100,3963]}]},{"id":"ch10p03","audio":true,"sents":[{"es":"El principito se preguntó:","zh":"——国王一眼瞥见小王子，叫出声来。","t":[100,1500]}]},{"id":"ch10p04","audio":true,"sents":[{"es":"\"¿Cómo es posible que me reconozca si nunca me ha visto?\"","zh":"小王子很纳闷：“他怎么认得我？","t":[100,2813]}]},{"id":"ch10p05","audio":true,"sents":[{"es":"Ignoraba que para los reyes el mundo está muy simplificado.","zh":"他可一次也没见过我呀！”","t":[100,4025]},{"es":"Todos los hombres son súbditos.","zh":"小王子不知道，在国王们眼里，世界安排得挺简单。","t":[4025,5738]}]},{"id":"ch10p06","audio":true,"sents":[{"es":"-Aproxímate para que te vea mejor -le dijo el rey, que estaba orgulloso de ser por fin el rey de alguien.","zh":"因为对他们来说，所有人都是臣民。","t":[100,6588]},{"es":"El principito buscó donde sentarse, pero el planeta estaba ocupado totalmente por el magnífico manto de armiño.","zh":"——走近一些，让我好好瞧瞧你，——国王对他说。","t":[6588,12425]}]},{"id":"ch10p07","audio":true,"sents":[{"es":"Se quedó, pues, de pie, pero como estaba cansado, bostezó.","zh":"他终于成了某个人的君主，得意极了。","t":[100,3237]}]},{"id":"ch10p08","audio":true,"sents":[{"es":"-La etiqueta no permite bostezar en presencia del rey -le dijo el monarca-.","zh":"小王子拿眼睛找地方坐，可整颗星球都被国王那件华丽的白鼬皮袍子占满了。","t":[100,5000]},{"es":"Te lo prohíbo.","zh":"他只好站着，又因为累，打了个哈欠。","t":[5000,5674]}]},{"id":"ch10p09","audio":true,"sents":[{"es":"-No he podido evitarlo -respondió el principito muy confuso-, he hecho un viaje muy largo y apenas he dormido…","zh":"——当着国王的面打哈欠，这可大违礼法，——君王对他说。","t":[100,6025]}]},{"id":"ch10p10","audio":true,"sents":[{"es":"-Entonces -le dijo el rey- te ordeno que bosteces.","zh":"——可我忍不住要打哈欠，——小王子窘得答道。","t":[100,4088]},{"es":"Hace años que no veo bostezar a nadie.","zh":"——我走了那么远的路，好久没合眼了。","t":[4088,7150]},{"es":"Los bostezos son para mí algo curioso.","zh":"——那么，——国王说，——我命令你打哈欠。","t":[7150,10288]},{"es":"¡Vamos, bosteza otra vez, te lo ordeno!","zh":"我多年没见人打哈欠了。","t":[10288,12413]}]},{"id":"ch10p11","audio":true,"sents":[{"es":"-Me da vergüenza…","zh":"打哈欠的人，怪逗我的。","t":[100,1138]},{"es":"ya no tengo ganas…","zh":"来吧！","t":[1138,2400]},{"es":"-dijo el principito enrojeciendo.","zh":"再打一个。","t":[2400,5025]},{"es":"-¡Hum, hum!","zh":"这是命令！","t":[5025,6662]},{"es":"-respondió el rey-.","zh":"——我打不出来了，——小王子涨红了脸，局促起来。","t":[6662,8688]},{"es":"¡Bueno!","zh":"——国王答道。","t":[8688,10088]},{"es":"Te ordeno tan pronto que bosteces y que no bosteces…","zh":"——那我就……","t":[10088,12725]}]},{"id":"ch10p12","audio":true,"sents":[{"es":"Tartamudeaba un poco y parecía vejado, pues el rey daba gran importancia a que su autoridad fuese respetada.","zh":"我命令你打哈欠，不然……","t":[100,5850]}]},{"id":"ch10p13","audio":true,"sents":[{"es":"Era un monarca absoluto, pero como era muy bueno, daba siempre órdenes razonables.","zh":"他嘟嘟囔囔，显得有些慌乱。","t":[100,4638]}]},{"id":"ch10p14","audio":true,"sents":[{"es":"Si yo ordenara -decía frecuentemente-, si yo ordenara a un general que se transformara en ave marina y el general no me obedeciese, la culpa no sería del general, sino mía\".","zh":"对国王来说，最要紧的是不失威严。","t":[100,10375]},{"es":"-¿Puedo sentarme?","zh":"他容不得半点违拗。","t":[10375,12212]},{"es":"-preguntó tímidamente el principito.","zh":"他是个专制的君主。","t":[12212,14124]}]},{"id":"ch10p15","audio":true,"sents":[{"es":"-Te ordeno sentarte -le respondió el rey-, recogiendo majestuosamente un faldón de su manto de armiño.","zh":"不过他心地善良，只下合乎情理的命令。","t":[100,5475]}]},{"id":"ch10p16","audio":true,"sents":[{"es":"El principito estaba sorprendido.","zh":"“要是我下令，”他常这样说，“叫某位将军变成海鸟，他若不遵命，错不在将军。","t":[100,2862]},{"es":"Aquel planeta era tan pequeño que no se explicaba sobre quién podría reinar aquel rey.","zh":"——我能坐下吗？","t":[2862,7275]}]},{"id":"ch10p17","audio":true,"sents":[{"es":"-Señor -le dijo-, perdóneme si le pregunto…","zh":"——小王子怯生生地问。","t":[100,2476]}]},{"id":"ch10p18","audio":true,"sents":[{"es":"-Te ordeno que me preguntes -se apresuró a decir el rey.","zh":"——我命令你坐下，——国王撩起白鼬皮袍子的下摆，答道。","t":[100,3050]}]},{"id":"ch10p19","audio":true,"sents":[{"es":"-Señor…","zh":"可小王子来了兴致：这么小一颗星球，能统治些什么呢？","t":[100,775]},{"es":"¿sobre qué ejerce su poder?","zh":"——陛下，——他对国王说，——恕我斗胆一问……","t":[775,2188]}]},{"id":"ch10p20","audio":true,"sents":[{"es":"-Sobre todo -contestó el rey con gran ingenuidad.","zh":"——我命令你尽管问！","t":[100,3588]},{"es":"-¿Sobre todo?","zh":"——国王抢着说。","t":[3588,4250]}]},{"id":"ch10p21","audio":true,"sents":[{"es":"El rey, con un gesto sencillo, señaló su planeta, los otros planetas y las estrellas.","zh":"——陛下……您统治的是什么呢？","t":[100,6088]},{"es":"-¿Sobre todo eso?","zh":"——统治一切！","t":[6088,8050]},{"es":"-volvió a preguntar el principito.","zh":"——国王天真地答道。","t":[8050,9713]}]},{"id":"ch10p22","audio":true,"sents":[{"es":"-Sobre todo eso…","zh":"国王谦逊地指了指自己的小星球，又指了指别的有星星的行星。","t":[100,1300]},{"es":"-respondió el rey.","zh":"——是这一切吗？","t":[1300,2338]}]},{"id":"ch10p23","audio":true,"sents":[{"es":"No era sólo un monarca absoluto, era, además, un monarca universal.","zh":"——小王子追问。","t":[100,4888]},{"es":"-¿Y las estrellas le obedecen?","zh":"——正是这一切，——国王骄傲地答道。","t":[4888,7450]},{"es":"-¡Naturalmente!","zh":"他可不单是专制君主，还是普天之下的君主呢。","t":[7450,9362]},{"es":"-le dijo el rey-.","zh":"——那么星星都听您的吗？","t":[9362,11212]},{"es":"Y obedecen en seguida, pues yo no tolero la indisciplina.","zh":"——那还用说，——国王说。","t":[11212,14362]}]},{"id":"ch10p24","audio":true,"sents":[{"es":"Un poder semejante dejó maravillado al principito.","zh":"——令出即行。","t":[100,3750]},{"es":"Si él disfrutara de un poder de tal naturaleza, hubiese podido asistir en el mismo día, no a cuarenta y tres, sino a setenta y dos, a cien, o incluso a doscientas puestas de sol, sin tener necesidad de arrastrar su silla.","zh":"我可不容人违抗！","t":[3750,17088]},{"es":"Y como se sentía un poco triste al recordar su pequeño planeta abandonado, se atrevió a solicitar una gracia al rey:","zh":"他要是有这样的权力，一天里就不止看四十四场日落，而是能看七十二场，甚至一百场、两百场，连椅子都不用挪！","t":[17088,23263]}]},{"id":"ch10p25","audio":true,"sents":[{"es":"-Me gustaría ver una puesta de sol…","zh":"小王子自离开自己的星球后一直郁郁寡欢，这会儿竟壮起胆子，向国王讨个恩典。","t":[100,2862]},{"es":"Deme ese gusto…","zh":"——我想看一场日落……","t":[2862,4938]},{"es":"Ordénele al sol que se ponga…","zh":"——劳您驾——命令太阳下山吧……","t":[4938,6512]}]},{"id":"ch10p26","audio":true,"sents":[{"es":"-Si yo le diera a un general la orden de volar de flor en flor como una mariposa, o de escribir una tragedia, o de transformarse en ave marina y el general no ejecutase la orden recibida ¿de quién sería la culpa, mía o de él?","zh":"——要是我命令某位将军像蝴蝶似的从一朵花飞到另一朵花，或者写一出伟大的悲剧，或者变成海鸟，而这位将军没执行这道命令，你说，错的是他还是我？","t":[100,12537]}]},{"id":"ch10p27","audio":true,"sents":[{"es":"-La culpa sería de usted -le dijo el principito con firmeza.","zh":"——当然是您，——小王子肯定地答道。","t":[100,3326]}]},{"id":"ch10p28","audio":true,"sents":[{"es":"-Exactamente.","zh":"——说得对。","t":[100,1950]},{"es":"Sólo hay que pedir a cada uno, lo que cada uno puede dar -continuó el rey.","zh":"对人只该要求他力所能及的事，——国王接着说。","t":[1950,6800]},{"es":"La autoridad se apoya antes que nada en la razón.","zh":"——权威，首要是建立在理性之上。","t":[6800,10300]},{"es":"Si ordenas a tu pueblo que se tire al mar, el pueblo hará la revolución.","zh":"你要是命令百姓去跳悬崖，他们就要闹革命了。","t":[10300,14912]},{"es":"Yo tengo derecho a exigir obediencia, porque mis órdenes son razonables.","zh":"——那日落的事呢？","t":[14912,20000]},{"es":"-¿Entonces mi puesta de sol?","zh":"——小王子提醒道。他一旦问出口，从不半途而废。","t":[20000,22425]},{"es":"-recordó el principito, que jamás olvidaba su pregunta una vez que la había formulado.","zh":"——你要的日落，会给你的。","t":[22425,26576]}]},{"id":"ch10p29","audio":true,"sents":[{"es":"-Tendrás tu puesta de sol.","zh":"我自会要求！","t":[100,2412]},{"es":"La exigiré.","zh":"不过得等一等。","t":[2412,4138]},{"es":"Pero, según me dicta mi ciencia gobernante, esperaré que las condiciones sean favorables.","zh":"治国之道，贵在择时。","t":[4138,9538]},{"es":"-¿Y cuándo será eso?","zh":"——那要等到什么时候呢？","t":[9538,11588]},{"es":"-¡Ejem, ejem!","zh":"——小王子问。","t":[11588,13512]},{"es":"-le respondió el rey, consultando previamente un enorme calendario-, ¡ejem, ejem!","zh":"——嗯，嗯，——国王先瞅了瞅大日历，答道。","t":[13512,18488]},{"es":"será hacia…","zh":"这事会……","t":[18488,19538]},{"es":"hacia…","zh":"会发生的……","t":[19538,20125]},{"es":"será hacia las siete cuarenta.","zh":"就在今天傍晚，七点二十分左右！","t":[20125,22575]},{"es":"Ya verás cómo se me obedece.","zh":"到时你就瞧瞧，万物是怎样听我号令的！","t":[22575,24150]}]},{"id":"ch10p30","audio":true,"sents":[{"es":"El principito bostezó.","zh":"小王子打了个哈欠。","t":[100,2288]},{"es":"Lamentaba su puesta de sol frustrada y además se estaba aburriendo ya un poco.","zh":"他已经在后悔，自己在星球上错过了那么多日落。","t":[2288,6400]}]},{"id":"ch10p31","audio":true,"sents":[{"es":"-Ya no tengo nada que hacer aquí -le dijo al rey-.","zh":"再说，他也觉得乏味了。","t":[100,3588]},{"es":"Me voy.","zh":"——看来我在这儿没什么事可做了，——他对国王说。","t":[3588,4062]}]},{"id":"ch10p32","audio":true,"sents":[{"es":"-No partas -le respondió el rey que se sentía muy orgulloso de tener un súbdito-, no te vayas y te hago ministro.","zh":"——我还是走吧。","t":[100,7075]},{"es":"-¿Ministro de qué?","zh":"——留下来吧，——国王答道。有个臣民，叫他好不得意。","t":[7075,8925]},{"es":"-¡De…","zh":"我封你当大臣……","t":[8925,9175]},{"es":"de justicia!","zh":"——什么大臣？","t":[9175,10962]},{"es":"-¡Pero si aquí no hay nadie a quien juzgar!","zh":"——嗯……司法大臣。","t":[10962,12987]}]},{"id":"ch10p33","audio":true,"sents":[{"es":"-Eso no se sabe -le dijo el rey-.","zh":"——可这儿没人好审呀！","t":[100,2925]},{"es":"Nunca he recorrido todo mi reino.","zh":"——那可难说，——国王答道。","t":[2925,5900]},{"es":"Estoy muy viejo y el caminar me cansa.","zh":"——我还没巡遍整个王国呢。","t":[5900,8988]},{"es":"Y como no hay sitio para una carroza…","zh":"我年事已高，既没有马车的位置，走路又累得慌。","t":[8988,11250]},{"es":"-¡Oh!","zh":"——是吗？","t":[11250,12300]},{"es":"Pero yo ya he visto…","zh":"可我已经都看过了，——小王子说着，弯下腰又朝星球的另一面望了一眼。","t":[12300,13588]},{"es":"-dijo el principito que se inclinó para echar una ojeada al otro lado del planeta-.","zh":"——那你审你自己吧，——国王说。","t":[13588,18688]},{"es":"Allá abajo no hay nadie tampoco..","zh":"——这可最难了。","t":[18688,20525]}]},{"id":"ch10p34","audio":true,"sents":[{"es":"-Te juzgarás a ti mismo -le respondió el rey-.","zh":"这比审别人难得多。","t":[100,3650]},{"es":"Es lo más difícil.","zh":"你能正确评判自己，才算真正有智慧。","t":[3650,5662]},{"es":"Es mucho más difícil juzgarse a sí mismo, que juzgar a los otros.","zh":"——可我，——小王子反驳道，——在哪儿都能审自己。","t":[5662,10288]},{"es":"Si consigues juzgarte rectamente es que eres un verdadero sabio.","zh":"用不着非住在这儿。","t":[10288,13800]}]},{"id":"ch10p35","audio":true,"sents":[{"es":"-Yo puedo juzgarme a mí mismo en cualquier parte y no tengo necesidad de vivir aquí.","zh":"——嗯，嗯……","t":[100,5062]},{"es":"-¡Ejem, ejem!","zh":"——国王说。","t":[5062,6988]},{"es":"Creo -dijo el rey- que en alguna parte del planeta vive una rata vieja; yo la oigo por la noche.","zh":"——不过我确知，我星球上的某个角落，住着一只老耗子。","t":[6988,13262]},{"es":"Tu podrás juzgar a esta rata vieja.","zh":"你可以审它，时不时判它死刑。","t":[13262,16188]},{"es":"La condenarás a muerte de vez en cuando.","zh":"这样，它的性命就攥在你的判决里了。","t":[16188,19162]},{"es":"Su vida dependería de tu justicia y la indultarás en cada juicio para conservarla, ya que no hay más que una.","zh":"不过每次出于仁慈和省事，你都赦免它。","t":[19162,24637]}]},{"id":"ch10p36","audio":true,"sents":[{"es":"-A mí no me gusta condenar a muerte a nadie -dijo el principito-.","zh":"毕竟它在这儿就这一个……","t":[100,4488]},{"es":"Creo que me voy a marchar.","zh":"——可我，——小王子反驳道，——我不喜欢判人死刑，所以，我还是走吧。","t":[4488,5800]}]},{"id":"ch10p37","audio":true,"sents":[{"es":"-No -dijo el rey.","zh":"——不行，不许走！","t":[100,1362]}]},{"id":"ch10p38","audio":true,"sents":[{"es":"Pero el principito, que habiendo terminado ya sus preparativos no quiso disgustar al viejo monarca, dijo:","zh":"——国王说。","t":[100,5337]}]},{"id":"ch10p39","audio":true,"sents":[{"es":"-Si Vuestra Majestad deseara ser obedecido puntualmente, podría dar una orden razonable.","zh":"可已经整装待发的小王子，不忍心让老君主伤心。","t":[100,5925]},{"es":"Podría ordenarme, por ejemplo, partir antes de un minuto.","zh":"——陛下若是想要臣民言听计从，就下一道合乎情理的命令吧。","t":[5925,9788]},{"es":"Me parece que las condiciones son favorables…","zh":"比如，您大可命令我即刻上路。","t":[9788,12137]}]},{"id":"ch10p40","audio":true,"sents":[{"es":"Como el rey no respondiera nada, el principito vaciló primero y con un suspiro emprendió la marcha.","zh":"国王对此一言不发，小王子略一犹疑，叹了口气，上路了。","t":[100,6150]},{"es":"-¡Te nombro mi embajador!","zh":"——我封你为我的使节！","t":[6150,8238]},{"es":"-se apresuró a gritar el rey.","zh":"——国王冲着他的背影喊了出来。","t":[8238,10788]},{"es":"Tenía un aspecto de gran autoridad.","zh":"那一瞬间，他神情威严十足。","t":[10788,12738]}]},{"id":"ch10p41","audio":true,"sents":[{"es":"\"Las personas mayores son muy extrañas\", se decía el principito para sí mismo durante el viaje.","zh":"“大人真是古怪，”小王子一边继续飞行，一边想。","t":[100,5063]}]}]},{"id":"ch11","title_es":"Capítulo 11","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":true,"sents":[{"es":"El segundo planeta estaba habitado por un vanidoso:","zh":"第二颗行星上，住着一个虚荣的人。","t":[100,2787]}]},{"id":"ch11p01","audio":true,"sents":[{"es":"-¡Ah!","zh":"——啊哈！","t":[100,1362]},{"es":"¡Ah!","zh":"——他老远望见小王子，就喊了起来。","t":[1362,2625]},{"es":"¡Un admirador viene a visitarme!","zh":"——我的崇拜者来了！","t":[2625,5388]},{"es":"-Gritó el vanidoso al divisar a lo lejos al principito.","zh":"要知道，在虚荣的人看来，别人统统只是他的崇拜者和仰慕者。","t":[5388,8100]}]},{"id":"ch11p02","audio":true,"sents":[{"es":"Para los vanidosos todos los demás hombres son admiradores.","zh":"——您好，——小王子说。","t":[100,4125]},{"es":"-¡Buenos días!","zh":"——您的帽子真有意思。","t":[4125,5975]},{"es":"-dijo el principito-.","zh":"——这帽子是用来致意的，——虚荣的人答道。","t":[5975,8050]},{"es":"¡Qué sombrero tan raro tiene!","zh":"——别人给我鼓掌时，我就脱帽还礼；可惜这儿从来没人来。","t":[8050,9587]}]},{"id":"ch11p03","audio":true,"sents":[{"es":"-Es para saludar a los que me aclaman -respondió el vanidoso.","zh":"——真的吗？","t":[100,3375]}]},{"id":"ch11p04","audio":true,"sents":[{"es":"Desgraciadamente nunca pasa nadie por aquí.","zh":"——小王子没怎么听懂，随口应道。","t":[100,3438]},{"es":"-¿Ah, sí?","zh":"——你把两只手掌对拍，——虚荣的人教他。","t":[3438,5050]},{"es":"-preguntó sin comprender el principito.","zh":"小王子拍起手来，虚荣的人便优雅地举起帽子，向他致意。","t":[5050,7100]}]},{"id":"ch11p05","audio":true,"sents":[{"es":"-Golpea tus manos una contra otra -le aconsejó el vanidoso.","zh":"“这儿比国王的星球热闹些，”小王子一边想。","t":[100,3438]}]},{"id":"ch11p06","audio":true,"sents":[{"es":"El principito aplaudió y el vanidoso le saludó modestamente levantando el sombrero.","zh":"他便又拍起手，虚荣的人也继续举着帽子致意。","t":[100,4225]}]},{"id":"ch11p07","audio":true,"sents":[{"es":"\"Esto parece más divertido que la visita al rey\", se dijo para sí el principito, que continuó aplaudiendo mientras el vanidoso volvía a saludarle quitándose el sombrero.","zh":"——要怎么着，帽子才会落下来呀？","t":[100,8787]}]},{"id":"ch11p08","audio":true,"sents":[{"es":"A los cinco minutos el principito se cansó con la monotonía de aquel juego.","zh":"——他问虚荣的人。","t":[100,4788]},{"es":"-¿Qué hay que hacer para que el sombrero se caiga?","zh":"可那人压根没听见。","t":[4788,7938]},{"es":"-preguntó el principito.","zh":"虚荣的人，除了赞扬，什么也听不进去。","t":[7938,9137]}]},{"id":"ch11p09","audio":true,"sents":[{"es":"Pero el vanidoso no le oyó.","zh":"——你当真对我崇拜得不得了吧？","t":[100,2462]},{"es":"Los vanidosos sólo oyen las alabanzas.","zh":"——虚荣的人问小王子。","t":[2462,5712]},{"es":"-¿Tú me admiras mucho, verdad?","zh":"——“崇拜”是什么意思？","t":[5712,8175]},{"es":"-preguntó el vanidoso al principito.","zh":"——崇拜？","t":[8175,11012]},{"es":"-¿Qué significa admirar?","zh":"意思就是承认，我是这颗星球上最优秀、最体面、最富有、最聪明的人。","t":[11012,12250]}]},{"id":"ch11p10","audio":true,"sents":[{"es":"-Admirar significa reconocer que yo soy el hombre más bello, el mejor vestido, el más rico y el más ïnteligente del planeta.","zh":"——可你在这儿就一个人哪！","t":[100,7688]},{"es":"-¡Si tú estás solo en tu planeta!","zh":"——哎呀，行行好，再对我崇拜一会儿吧！","t":[7688,10400]},{"es":"-¡Hazme ese favor, admírame de todas maneras!","zh":"——好吧，——小王子耸耸肩说。","t":[10400,14050]},{"es":"-¡Bueno!","zh":"——我崇拜你。","t":[14050,15450]},{"es":"Te admiro -dijo el principito encogiéndose de hombros-, pero ¿para qué te sirve?","zh":"可这对你有什么好处呢？","t":[15450,19362]}]},{"id":"ch11p11","audio":true,"sents":[{"es":"Y el principito se marchó.","zh":"说完，小王子便跑开了。","t":[100,1475]}]},{"id":"ch11p12","audio":true,"sents":[{"es":"\"Decididamente, las personas mayores son muy extrañas\", se decía para sí el principito durante su viaje.","zh":"“不，大人确实都是些古怪的家伙，”飞行途中他暗自想道。","t":[100,5650]}]}]},{"id":"ch12","title_es":"Capítulo 12","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":true,"sents":[{"es":"El planeta siguiente estaba habitado por un bebedor.","zh":"下一颗行星上，住着一个酒鬼。","t":[100,3612]},{"es":"Fue una visita muy corta, pues hundió al principito en una gran melancolía.","zh":"对他的造访很短，却叫小王子十分难过。","t":[3612,7387]}]},{"id":"ch12p01","audio":true,"sents":[{"es":"-¿Qué haces ahí?","zh":"——你在这儿干什么呢？","t":[100,1838]},{"es":"-preguntó al bebedor que estaba sentado en silencio ante un sinnúmero de botellas vacías y otras tantas botellas llenas.","zh":"——他问酒鬼。酒鬼正坐在一堆空瓶子和满瓶子面前。","t":[1838,8775]},{"es":"-¡Bebo!","zh":"——我喝酒，——酒鬼闷闷不乐地答道。","t":[8775,10175]},{"es":"-respondió el bebedor con tono lúgubre.","zh":"——我喝酒，——酒鬼闷闷不乐地答道。","t":[10175,13275]},{"es":"-¿Por qué bebes?","zh":"——那你为什么喝酒？","t":[13275,15000]},{"es":"-volvió a preguntar el principito.","zh":"——小王子追问。","t":[15000,16663]}]},{"id":"ch12p02","audio":true,"sents":[{"es":"-Para olvidar.","zh":"——为了忘掉，——酒鬼说。","t":[100,1762]},{"es":"-¿Para olvidar qué?","zh":"——忘掉什么？","t":[1762,3588]},{"es":"-inquirió el principito ya compadecido.","zh":"——小王子满怀同情地问。","t":[3588,5638]}]},{"id":"ch12p03","audio":true,"sents":[{"es":"-Para olvidar que siento vergüenza -confesó el bebedor bajando la cabeza.","zh":"——忘掉我的羞耻，——酒鬼低下头，承认道。","t":[100,4775]},{"es":"-¿Vergüenza de qué?","zh":"——羞耻什么？","t":[4775,6612]},{"es":"-se informó el principito deseoso de ayudarle.","zh":"——羞耻什么？","t":[6612,10112]},{"es":"-¡Vergüenza de beber!","zh":"——小王子很想帮帮他，追着问。","t":[10112,12088]},{"es":"-concluyó el bebedor, que se encerró nueva y definitivamente en el silencio.","zh":"——羞耻我喝酒，——酒鬼嘟囔了一句，便久久不说话了。","t":[12088,15750]}]},{"id":"ch12p04","audio":true,"sents":[{"es":"Y el principito, perplejo, se marchó.","zh":"小王子满心困惑，离开了这颗星球。","t":[100,2076]}]},{"id":"ch12p05","audio":true,"sents":[{"es":"\"No hay la menor duda de que las personas mayores son muy extrañas\", seguía diciéndose para sí el principito durante su viaje.","zh":"“大人确确实实非常、非常古怪，”飞行途中，他又一次暗自想道。","t":[100,6400]}]}]},{"id":"ch13","title_es":"Capítulo 13","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":true,"sents":[{"es":"El cuarto planeta estaba ocupado por un hombre de negocios.","zh":"第四颗行星上，住着一个生意人。","t":[100,4062]},{"es":"Este hombre estaba tan abstraído que ni siquiera levantó la cabeza a la llegada del principito.","zh":"这人忙得不可开交，小王子到来时，他连头都没抬一下。","t":[4062,8538]}]},{"id":"ch13p01","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"——您好，——小王子打了声招呼。","t":[100,1950]},{"es":"-le dijo éste-.","zh":"——您瞧，您的烟灭了。","t":[1950,3788]},{"es":"Su cigarro se ha apagado.Tres y dos cinco.","zh":"——三加二等于五。","t":[3788,7475]},{"es":"Cinco y siete doce.","zh":"七加五等于十二。","t":[7475,9750]},{"es":"Doce y tres quince.","zh":"十二加三等于十五。","t":[9750,11962]},{"es":"¡Buenos días!","zh":"你好。","t":[11962,13812]},{"es":"Quince y siete veintidós.","zh":"二十二加六等于二十八。","t":[13812,16300]},{"es":"Veintidós y seis veintiocho.","zh":"我没空再把它点着了。","t":[16300,18950]},{"es":"No tengo tiempo de encenderlo.","zh":"二十六加五等于三十一。","t":[18950,21638]},{"es":"Veintiocho y tres treinta y uno.","zh":"哎哟！","t":[21638,24375]},{"es":"¡Uf!","zh":"总共是五亿零一百六十二万两千七百三十一。","t":[24375,25738]},{"es":"Esto suma quinientos un millones seiscientos veintidós mil setecientos treinta y uno.","zh":"——五亿什么呀？","t":[25738,31062]},{"es":"-¿Quinientos millones de qué?","zh":"——什么？","t":[31062,33338]},{"es":"-¿Eh?","zh":"你还在这儿？","t":[33338,34512]},{"es":"¿Estás ahí todavía?","zh":"五亿零一百六十二万……","t":[34512,36588]},{"es":"Quinientos millones de…","zh":"什么来着……","t":[36588,37875]},{"es":"ya no sé…","zh":"我记不得了。","t":[37875,39438]},{"es":"¡He trabajado tanto!","zh":"我有这么多事要忙！","t":[39438,41488]},{"es":"¡Yo soy un hombre serio y no me entretengo en tonterías!","zh":"我是个正经人。","t":[41488,45375]},{"es":"Dos y cinco siete…","zh":"那些无聊的闲事，我才不理会。","t":[45375,47612]},{"es":"¿Quinientos millones de qué?","zh":"——五亿什么呀？","t":[47612,49888]},{"es":"-volvió a preguntar el principito, que nunca en su vida había renunciado a una pregunta una vez que la había formulado.","zh":"——小王子一旦问出口，从不半途而废，这会儿又问。","t":[49888,55438]}]},{"id":"ch13p02","audio":true,"sents":[{"es":"El hombre de negocios levantó la cabeza:","zh":"生意人抬起头：“在我住这颗星球的五十四年里，一共只被打扰过三次。","t":[100,2162]}]},{"id":"ch13p03","audio":true,"sents":[{"es":"-Desde hace cincuenta y cuatro años que habito este planeta, sólo me han molestado tres veces.","zh":"头一回，是二十二年前。","t":[100,5888]},{"es":"La primera, hace veintidós años, fue por un abejorro que había caído aquí de Dios sabe dónde.","zh":"不知从哪儿飞来一只金龟子。","t":[5888,11738]},{"es":"Hacía un ruido insoportable y me hizo cometer cuatro errores en una suma.","zh":"它嗡嗡直叫，害我加法算错了四次。","t":[11738,16512]},{"es":"La segunda vez por una crisis de reumatismo, hace once años.","zh":"第二回，是十一年前。","t":[16512,20038]}]},{"id":"ch13p04","audio":true,"sents":[{"es":"Yo no hago ningún ejercicio, pues no tengo tiempo de callejear.","zh":"我犯了风湿。","t":[100,4362]},{"es":"Soy un hombre serio.","zh":"我缺少运动，可我没空去散步。","t":[4362,6512]},{"es":"Y la tercera vez…","zh":"因为我是个正经人。","t":[6512,7662]},{"es":"¡la tercera vez es ésta!","zh":"第三回，就是你闯来的！","t":[7662,9938]},{"es":"Decía, pues, quinientos un millones…","zh":"所以，我刚才说到——五亿零一百六十二万……","t":[9938,12212]},{"es":"-¿Millones de qué?","zh":"——几亿个什么呢？","t":[12212,13000]}]},{"id":"ch13p05","audio":true,"sents":[{"es":"El hombre de negocios comprendió que no tenía ninguna esperanza de que lo dejaran en paz.","zh":"生意人明白，这下是甩不掉他了。","t":[100,4300]}]},{"id":"ch13p06","audio":true,"sents":[{"es":"-Millones de esas pequeñas cosas que algunas veces se ven en el cielo.","zh":"——就是天上偶尔能瞧见的那许许多多小玩意儿。","t":[100,4625]},{"es":"-¿Moscas?","zh":"——不是啦！","t":[4625,6212]},{"es":"-¡No, cositas que brillan!","zh":"是那种亮晶晶的小东西。","t":[6212,8500]},{"es":"-¿Abejas?","zh":"——蜜蜂？","t":[8500,9000]}]},{"id":"ch13p07","audio":true,"sents":[{"es":"-No.","zh":"——不是啦！","t":[100,1450]},{"es":"Unas cositas doradas que hacen desvariar a los holgazanes.","zh":"是那些金灿灿、让人忍不住做白日梦的小东西。","t":[1450,5550]},{"es":"¡Yo soy un hombre serio y no tengo tiempo de desvariar!","zh":"可我是个正经人。","t":[5550,9288]},{"es":"-¡Ah!","zh":"没空去胡思乱想。","t":[9288,10550]},{"es":"¿Estrellas?","zh":"——啊！","t":[10550,11212]}]},{"id":"ch13p08","audio":true,"sents":[{"es":"-Eso es.","zh":"星星！","t":[100,1662]},{"es":"Estrellas.","zh":"——正是，星星。","t":[1662,3400]},{"es":"-¿Y qué haces tú con quinientos millones de estrellas?","zh":"——那你拿这好几亿颗星星做什么呢？","t":[3400,5875]}]},{"id":"ch13p09","audio":true,"sents":[{"es":"-Quinientos un millones seiscientos veintidós mil setecientos treinta y uno.","zh":"——精确地说，是五亿零一百六十二万两千七百三十一颗星星。","t":[100,5075]},{"es":"Yo soy un hombre serio y exacto.","zh":"——那么你拿这些星星做什么呢？","t":[5075,7938]},{"es":"-¿Y qué haces con esas estrellas?","zh":"——我拿它们做什么？","t":[7938,10675]},{"es":"-¿Que qué hago con ellas?","zh":"——什么都不做。","t":[10675,11800]}]},{"id":"ch13p10","audio":true,"sents":[{"es":"-Sí.","zh":"我拥有它们。","t":[100,338]}]},{"id":"ch13p11","audio":true,"sents":[{"es":"-Nada.","zh":"——你拥有这些星星？","t":[100,1525]},{"es":"Las poseo.","zh":"——对。","t":[1525,3275]},{"es":"-¿Que las estrellas son tuyas?","zh":"——可我见过一位国王，他……","t":[3275,4838]}]},{"id":"ch13p12","audio":true,"sents":[{"es":"-Sí.","zh":"——国王不“拥有”。","t":[100,338]}]},{"id":"ch13p13","audio":true,"sents":[{"es":"-Yo he visto un rey que…","zh":"他们“统治”。","t":[100,1450]}]},{"id":"ch13p14","audio":true,"sents":[{"es":"-Los reyes no poseen nada…","zh":"这完全是两码事。","t":[100,2688]},{"es":"Reinan.","zh":"——那你为什么要拥有星星呢？","t":[2688,4238]},{"es":"Es muy diferente.","zh":"——为什么要拥有？","t":[4238,6200]},{"es":"-¿Y de qué te sirve poseer las estrellas?","zh":"为了当富翁。","t":[6200,8338]}]},{"id":"ch13p15","audio":true,"sents":[{"es":"-Me sirve para ser rico.","zh":"——那你又要富翁做什么？","t":[100,2488]},{"es":"-¿Y de qué te sirve ser rico?","zh":"——好等别人发现新星星时，把它们买下来呀。","t":[2488,3937]}]},{"id":"ch13p16","audio":true,"sents":[{"es":"-Me sirve para comprar más estrellas si alguien las descubre.","zh":"“这个大人，”小王子暗想，“算起账来，跟那个酒鬼差不多。”","t":[100,3137]}]},{"id":"ch13p17","audio":true,"sents":[{"es":"\"Este, se dijo a sí mismo el principito, razona poco más o menos como mi borracho\".","zh":"——那它们是谁的？","t":[100,4400]}]},{"id":"ch13p18","audio":true,"sents":[{"es":"No obstante le siguió preguntando: -¿Y cómo es posible poseer estrellas?","zh":"——生意人嘟囔着反问道。","t":[100,5062]},{"es":"-¿De quién son las estrellas?","zh":"——我不知道。","t":[5062,7600]},{"es":"-contestó punzante el hombre de negocios.","zh":"大概谁也不是。","t":[7600,9688]}]},{"id":"ch13p19","audio":true,"sents":[{"es":"-No sé…","zh":"——既然是我第一个想到要拥有它们，那它们就是我的。","t":[100,1650]},{"es":"De nadie.","zh":"——这就够了吗？","t":[1650,2237]}]},{"id":"ch13p20","audio":true,"sents":[{"es":"-Entonces son mías, puesto que he sido el primero a quien se le ha ocurrido la idea.","zh":"——完全够！","t":[100,5075]},{"es":"-¿Y eso basta?","zh":"因为你要是找到一颗没主儿的钻石，它就成了你的。","t":[5075,5862]}]},{"id":"ch13p21","audio":true,"sents":[{"es":"-Naturalmente.","zh":"你要是发现一座无主荒岛，它也是你的。","t":[100,2012]},{"es":"Si te encuentras un diamante que nadie reclama, el diamante es tuyo.","zh":"你要是头一个想出某个点子，你给它申请专利，那点子就是你的。","t":[2012,6638]},{"es":"Si encontraras una isla que a nadie pertenece, la isla es tuya.","zh":"我拥有星星，只因为从前没人想到要去占有它们。","t":[6638,11200]},{"es":"Si eres el primero en tener una idea y la haces patentar, nadie puede aprovecharla: es tuya.","zh":"——这倒是真的，——小王子说。","t":[11200,17250]},{"es":"Las estrellas son mías, puesto que nadie, antes que yo, ha pensado en poseerlas.","zh":"——那你拿它们做什么呢？","t":[17250,21450]}]},{"id":"ch13p22","audio":true,"sents":[{"es":"-Eso es verdad -dijo el principito- ¿y qué haces con ellas?","zh":"——我经营管理它们。","t":[100,3263]}]},{"id":"ch13p23","audio":true,"sents":[{"es":"-Las administro.","zh":"数一数，再数一数，——生意人说。","t":[100,2012]},{"es":"Las cuento y las recuento una y otra vez -contestó el hombre de negocios-.","zh":"不过，小王子到底还有件事没弄明白。","t":[2012,6775]},{"es":"Es algo difícil.","zh":"——我要是有一条围巾，我可以支配它——围在脖子上，带着它走。","t":[6775,8688]},{"es":"¡Pero yo soy un hombre serio!","zh":"我要是有一朵花，我可以把它摘下带走。","t":[8688,10188]}]},{"id":"ch13p24","audio":true,"sents":[{"es":"El principito no quedó del todo satisfecho.","zh":"可你总不能把星星摘下来吧！","t":[100,2412]}]},{"id":"ch13p25","audio":true,"sents":[{"es":"-Si yo tengo una bufanda, puedo ponérmela al cuello y llevármela.","zh":"——摘不下来。","t":[100,4612]},{"es":"Si soy dueño de una flor, puedo cortarla y llevármela también.","zh":"不过我可以把它们存进银行。","t":[4612,9088]},{"es":"¡Pero tú no puedes llevarte las estrellas!","zh":"——怎么个存法？","t":[9088,11113]}]},{"id":"ch13p26","audio":true,"sents":[{"es":"-Pero puedo colocarlas en un banco.","zh":"这算什么意思？","t":[100,2825]},{"es":"-¿Qué quiere decir eso?","zh":"——意思就是，我把星星的数目写在一张纸上，再把纸放进抽屉，用钥匙锁上。","t":[2825,3938]}]},{"id":"ch13p27","audio":true,"sents":[{"es":"-Quiere decir que escribo en un papel el número de estrellas que tengo y guardo bajo llave en un cajón ese papel.","zh":"——就这些？","t":[100,6338]},{"es":"-¿Y eso es todo?","zh":"——这就足够了。","t":[6338,8162]},{"es":"-¡Es suficiente!","zh":"“这真有意思，”小王子想。","t":[8162,9024]}]},{"id":"ch13p28","audio":true,"sents":[{"es":"\"Es divertido\", pensó el principito.","zh":"“听着挺美，可不太正经。”","t":[100,3025]},{"es":"\"Es incluso bastante poético.","zh":"和小大人不同，小王子对“正经事”自有一套完全不同的看法。","t":[3025,5775]},{"es":"Pero no es muy serio\".","zh":"我有三座火山，我每星期都疏通。","t":[5775,6913]}]},{"id":"ch13p29","audio":true,"sents":[{"es":"El principito tenía sobre las cosas serias ideas muy diferentes de las ideas de las personas mayores.","zh":"那座死火山，我也照样清理。","t":[100,5162]}]},{"id":"ch13p30","audio":true,"sents":[{"es":"-Yo -dijo aún- tengo una flor a la que riego todos los días; poseo tres volcanes a los que deshollino todas las semanas, pues también me ocupo del que está extinguido; nunca se sabe lo que puede ocurrir.","zh":"就这么着——以防万一呗。","t":[100,12038]},{"es":"Es útil, pues, para mis volcanes y para mi flor que yo las posea.","zh":"我拥有我的火山和我的花，对它们是有好处的。","t":[12038,16500]},{"es":"Pero tú, tú no eres nada útil para las estrellas…","zh":"可你拥有星星，对星星有什么好处呢？","t":[16500,19363]}]},{"id":"ch13p31","audio":true,"sents":[{"es":"El hombre de negocios abrió la boca, pero no encontró respuesta.","zh":"生意人张了张嘴，到底什么也没答上来。","t":[100,3575]}]},{"id":"ch13p32","audio":true,"sents":[{"es":"El principito abandonó aquel planeta.","zh":"于是小王子又上路了。","t":[100,2076]}]},{"id":"ch13p33","audio":true,"sents":[{"es":"\"Las personas mayores, decididamente, son extraordinarias\", se decía a sí mismo con sencillez durante el viaje.","zh":"“大人确确实实是些不可思议的家伙，”一路上他不住地想。","t":[100,6112]}]}]},{"id":"ch14","title_es":"Capítulo 14","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":true,"sents":[{"es":"El quinto planeta era muy curioso.","zh":"第五颗行星，可算是最奇特的了。","t":[100,3075]},{"es":"Era el más pequeño de todos, pues apenas cabían en él un farol y el farolero que lo habitaba.","zh":"在小王子见过的星球里，它最小。","t":[3075,8700]},{"es":"El principito no lograba explicarse para qué servirían allí, en el cielo, en un planeta sin casas y sin población un farol y un farolero.","zh":"上面只容得下一盏路灯和一个点灯人。","t":[8700,16800]},{"es":"Sin embargo, se dijo a sí mismo:","zh":"小王子怎么也想不通，在天上那么一颗没有房屋、没有居民的星球上，要路灯和点灯人做什么。","t":[16800,18525]}]},{"id":"ch14p01","audio":true,"sents":[{"es":"\"Este hombre, quizás, es absurdo.","zh":"不过他转念一想——这人虽说古怪，可比起国王、生意人和酒鬼，倒也并不更古怪。","t":[100,3025]},{"es":"Sin embargo, es menos absurdo que el rey, el vanidoso, el hombre de negocios y el bebedor.","zh":"他点亮路灯时，仿佛天上又多了一颗星，或是又开了一朵花。","t":[3025,8700]},{"es":"Su trabajo, al menos, tiene sentido.","zh":"他熄灭路灯时，仿佛星星或花儿就睡着了。","t":[8700,11700]},{"es":"Cuando enciende su farol, es igual que si hiciera nacer una estrella más o una flor y cuando lo apaga hace dormir a la flor o a la estrella.","zh":"这活儿挺叫人喜欢。","t":[11700,19538]},{"es":"Es una ocupación muy bonita y por ser bonita es verdaderamente útil\".","zh":"它有益，因为它创造美。","t":[19538,23224]}]},{"id":"ch14p02","audio":true,"sents":[{"es":"Cuando llegó al planeta saludó respetuosamente al farolero: -¡Buenos días!","zh":"飞近这颗星球，小王子彬彬有礼地向点灯人问好。","t":[100,4962]},{"es":"¿Por qué acabas de apagar tu farol?","zh":"——您好，——他说。","t":[4962,6738]}]},{"id":"ch14p03","audio":true,"sents":[{"es":"-Es la consigna -respondió el farolero-.","zh":"——你刚才怎么把灯灭了？","t":[100,3450]},{"es":"¡Buenos días!","zh":"——这是规矩，——点灯人答道。","t":[3450,5300]},{"es":"-¿Y qué es la consigna?","zh":"——什么规矩？","t":[5300,6462]}]},{"id":"ch14p04","audio":true,"sents":[{"es":"-Apagar mi farol.","zh":"——该灭灯了。","t":[100,2012]},{"es":"¡Buenas noches!","zh":"晚上好！","t":[2012,3962]},{"es":"Y encendió el farol.","zh":"说着，他把自己的灯点亮了。","t":[3962,6075]},{"es":"-¿Y por qué acabas de volver a encenderlo?","zh":"——那你为什么又把它点亮了？","t":[6075,8000]}]},{"id":"ch14p05","audio":true,"sents":[{"es":"-Es la consigna.","zh":"——小王子问。","t":[100,1012]}]},{"id":"ch14p06","audio":true,"sents":[{"es":"-No lo comprendo -dijo el principito.","zh":"——这是规矩，——点灯人答道。","t":[100,2050]}]},{"id":"ch14p07","audio":true,"sents":[{"es":"-No hay nada que comprender -dijo el farolero-.","zh":"——我不明白……","t":[100,3388]},{"es":"La consigna es la consigna.","zh":"——没什么好明白的，——点灯人说。","t":[3388,5938]},{"es":"¡Buenos días!","zh":"——规矩就是规矩。","t":[5938,6762]}]},{"id":"ch14p08","audio":true,"sents":[{"es":"Y apagó su farol.","zh":"早安！","t":[100,1163]}]},{"id":"ch14p09","audio":true,"sents":[{"es":"Luego se enjugó la frente con un pañuelo de cuadros rojos.","zh":"说着，他又把灯灭了。","t":[100,3263]}]},{"id":"ch14p10","audio":true,"sents":[{"es":"-Mi trabajo es algo terrible.","zh":"接着，他用红格手帕擦了擦额头。","t":[100,2662]},{"es":"En otros tiempos era razonable; apagaba el farol por la mañana y lo encendía por la tarde.","zh":"这该死的活儿，累死人。","t":[2662,8550]},{"es":"Tenía el resto del día para reposar y el resto de la noche para dormir.","zh":"从前可轻松多了。","t":[8550,13138]},{"es":"-¿Y luego cambiaron la consigna?","zh":"我早晨灭灯，傍晚点灯。","t":[13138,14750]}]},{"id":"ch14p11","audio":true,"sents":[{"es":"-Ese es el drama, que la consigna no ha cambiado -dijo el farolero-.","zh":"白天能歇着，夜里能睡个够。","t":[100,4925]},{"es":"El planeta gira cada vez más de prisa de año en año y la consigna sigue siendo la misma.","zh":"——小王子问。","t":[4925,10412]},{"es":"-¿Y entonces?","zh":"——规矩没改，——点灯人叹了口气。","t":[10412,12162]},{"es":"-dijo el principito.","zh":"——毛病就出在这儿。","t":[12162,13250]}]},{"id":"ch14p12","audio":true,"sents":[{"es":"-Como el planeta da ahora una vuelta completa cada minuto, yo no tengo un segundo de reposo.","zh":"这颗星球一年转得比一年快，规矩却还是老样子。","t":[100,5762]},{"es":"Enciendo y apago una vez por minuto.","zh":"——那现在呢？","t":[5762,8825]},{"es":"-¡Eso es raro!","zh":"——小王子问。","t":[8825,10650]},{"es":"¡Los días sólo duran en tu tierra un minuto!","zh":"——如今它一分钟就转一圈，我连一秒钟的休息都没有。","t":[10650,12976]}]},{"id":"ch14p13","audio":true,"sents":[{"es":"-Esto no tiene nada de divertido -dijo el farolero-.","zh":"我每分钟就得点一次、灭一次这盏灯。","t":[100,3925]},{"es":"Hace ya un mes que tú y yo estamos hablando.","zh":"——这么说，你的一天只有一分钟长？","t":[3925,7150]},{"es":"-¿Un mes?","zh":"——这一点都不逗！","t":[7150,7638]}]},{"id":"ch14p14","audio":true,"sents":[{"es":"-Sí, treinta minutos.","zh":"——点灯人答道。","t":[100,2425]},{"es":"¡Treinta días!","zh":"——咱俩这一聊，都已经整整一个月了！","t":[2425,4250]},{"es":"¡Buenas noches!","zh":"——一个月？","t":[4250,5200]}]},{"id":"ch14p15","audio":true,"sents":[{"es":"Y volvió a encender su farol.","zh":"——嗯，对。","t":[100,1663]}]},{"id":"ch14p16","audio":true,"sents":[{"es":"El principito lo miró y le gustó este farolero que tan fielmente cumplía la consigna.","zh":"三十天。","t":[100,5225]},{"es":"Recordó las puestas de sol que en otro tiempo iba a buscar arrastrando su silla.","zh":"晚上好！","t":[5225,10300]},{"es":"Quiso ayudarle a su amigo.","zh":"点灯人说着，又把灯点亮了。","t":[10300,12825]},{"es":"-¿Sabes?","zh":"他喜欢这个不肯违背自己规矩的人。","t":[12825,14375]},{"es":"Yo conozco un medio para que descanses cuando quieras…","zh":"他想起自己从前也常挪动椅子，在星球上看日落。","t":[14375,17150]}]},{"id":"ch14p17","audio":true,"sents":[{"es":"-Yo quiero descansar siempre -dijo el farolero.","zh":"小王子便想帮帮这位新朋友。","t":[100,2663]}]},{"id":"ch14p18","audio":true,"sents":[{"es":"Se puede ser a la vez fiel y perezoso.","zh":"——听我说，——他说，——我好像知道，你怎么才能想歇就歇。","t":[100,2162]}]},{"id":"ch14p19","audio":true,"sents":[{"es":"El principito prosiguió:","zh":"——我无时无刻不想歇着。","t":[100,1388]}]},{"id":"ch14p20","audio":true,"sents":[{"es":"-Tu planeta es tan pequeño que puedes darle la vuelta en tres zancadas.","zh":"守着规矩和偷点懒，本可以两不耽误嘛。","t":[100,4475]},{"es":"No tienes que hacer más que caminar muy lentamente para quedar siempre al sol.","zh":"——你瞧，——小王子接着说。","t":[4475,9238]},{"es":"Cuando quieras descansar, caminarás…","zh":"——你的星球那么小，三步就能绕一圈。","t":[9238,11400]},{"es":"y el día durará tanto tiempo cuanto quieras.","zh":"想歇工了，只管往前走，你要白天多长，它就多长。","t":[11400,13562]}]},{"id":"ch14p21","audio":true,"sents":[{"es":"-Con eso no adelanto gran cosa -dijo el farolero-, lo que a mí me gusta en la vida es dormir.","zh":"——这法子顶不了什么用，——点灯人叹道。","t":[100,5062]}]},{"id":"ch14p22","audio":true,"sents":[{"es":"-No es una suerte -dijo el principito.","zh":"——我只求能安安稳稳睡上一觉。","t":[100,2137]}]},{"id":"ch14p23","audio":true,"sents":[{"es":"-No, no es una suerte -replicó el farolero-.","zh":"这才是我想要的！","t":[100,3475]},{"es":"¡Buenos días!","zh":"——唉，你这情况是不妙，——小王子替他难过。","t":[3475,4300]}]},{"id":"ch14p24","audio":true,"sents":[{"es":"Y apagó su farol.","zh":"——是啊，运气不好，——点灯人答道。","t":[100,1163]}]},{"id":"ch14p25","audio":true,"sents":[{"es":"Mientras el principito proseguía su viaje, se iba diciendo para sí: \"Este sería despreciado por los otros, por el rey, por el vanidoso, por el bebedor, por el hombre de negocios.","zh":"——早安！","t":[100,10500]},{"es":"Y, sin embargo, es el único que no me parece ridículo, quizás porque se ocupa de otra cosa y no de sí mismo.","zh":"说着，他又把灯灭了。","t":[10500,17075]},{"es":"Lanzó un suspiro de pena y continuó diciéndose:","zh":"可我倒不觉得他荒唐。","t":[17075,19825]}]},{"id":"ch14p26","audio":true,"sents":[{"es":"\"Es el único de quien pude haberme hecho amigo.","zh":"兴许是因为，他忙的是自己的本分，而不是自己本身。”","t":[100,3350]},{"es":"Pero su planeta es demasiado pequeño y no hay lugar para dos…","zh":"小王子叹了口气，又暗自补了一句：“这是唯一一个，可能成为我朋友的大人。","t":[3350,6587]},{"es":"\"","zh":"可他的星球那么小，两个人实在挤不下……”","t":[6587,7087]}]},{"id":"ch14p27","audio":true,"sents":[{"es":"Lo que el principito no se atrevía a confesarse, era que la causa por la cual lamentaba no quedarse en este bendito planeta se debía a las mil cuatrocientas cuarenta puestas de sol que podría disfrutar cada veinticuatro horas.","zh":"小王子不肯对自己承认，他惋惜这颗美丽的星球，其实只是因为——在它上面，二十四小时里他能看上一千四百四十场日落！","t":[100,11263]}]}]},{"id":"ch15","title_es":"Capítulo 15","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":true,"sents":[{"es":"El sexto planeta era diez veces más grande.","zh":"第六颗行星，比前面的足足大十倍。","t":[100,3588]},{"es":"Estaba habitado por un anciano que escribía grandes libros.","zh":"上面住着一位老先生，写的全是厚厚的书。","t":[3588,7625]},{"es":"-¡Anda, un explorador!","zh":"——啊哈！","t":[7625,10012]},{"es":"-exclamó cuando divisó al principito.","zh":"——旅行家来了！","t":[10012,12038]}]},{"id":"ch15p01","audio":true,"sents":[{"es":"Este se sentó sobre la mesa y reposó un poco.","zh":"小王子在一张桌子旁坐下，好喘口气。","t":[100,3575]},{"es":"¡Había viajado ya tanto!","zh":"他毕竟走了那么长的路。","t":[3575,5938]},{"es":"-¿De dónde vienes tú?","zh":"——你从哪儿来？","t":[5938,8062]},{"es":"-le preguntó el anciano.","zh":"——老先生问他。","t":[8062,10288]},{"es":"-¿Qué libro es ese tan grande?","zh":"——小王子反问他。","t":[10288,12700]},{"es":"-preguntó a su vez el principito-.","zh":"——您在这儿做什么呢？","t":[12700,15400]},{"es":"¿Qué hace usted aquí?","zh":"——我是地理学家，——老先生答道。","t":[15400,16375]}]},{"id":"ch15p02","audio":true,"sents":[{"es":"-Soy geógrafo -dijo el anciano.","zh":"——地理学家是什么人？","t":[100,2912]},{"es":"-¿Y qué es un geógrafo?","zh":"——是这么一种学者：他清楚海洋在哪儿，河流、城市、山脉、沙漠又在哪儿。","t":[2912,4137]}]},{"id":"ch15p03","audio":true,"sents":[{"es":"-Es un sabio que sabe donde están los mares, los ríos, las ciudades, las montañas y los desiertos.","zh":"——了不起！","t":[100,5513]}]},{"id":"ch15p04","audio":true,"sents":[{"es":"-Eso es muy interesante -dijo el principito-.","zh":"——这真是个顶呱呱的行当。","t":[100,3525]},{"es":"¡Y es un verdadero oficio!","zh":"说罢，他满心敬慕地环顾起地理学家的星球。","t":[3525,5000]}]},{"id":"ch15p05","audio":true,"sents":[{"es":"Dirigió una mirada a su alrededor sobre el planeta del geógrafo; nunca había visto un planeta tan majestuoso.","zh":"他还从没见过这么气派的星球。","t":[100,6000]}]},{"id":"ch15p06","audio":true,"sents":[{"es":"-Es muy hermoso su planeta.","zh":"——您的星球真美呀！","t":[100,2588]},{"es":"¿Hay océanos aquí?","zh":"有海洋吗？","t":[2588,3612]}]},{"id":"ch15p07","audio":true,"sents":[{"es":"-No puedo saberlo -dijo el geógrafo.","zh":"——原来如此……","t":[100,3288]},{"es":"-¡Ah!","zh":"——小王子略微有点失望。","t":[3288,3462]},{"es":"(El principito se sintió decepcionado).","zh":"——那山脉呢？","t":[3462,6400]},{"es":"¿Y montañas?","zh":"——这我也不知道，——地理学家答道。","t":[6400,7137]}]},{"id":"ch15p08","audio":true,"sents":[{"es":"-No puedo saberlo -repitió el geógrafo.","zh":"——城市、河流、沙漠呢？","t":[100,3462]},{"es":"-¿Y ciudades, ríos y desiertos?","zh":"——可您是地理学家呀！","t":[3462,5362]}]},{"id":"ch15p09","audio":true,"sents":[{"es":"-Tampoco puedo saberlo.","zh":"——这没错，可我不是旅行家。","t":[100,2338]},{"es":"-¡Pero usted es geógrafo!","zh":"我最缺的，就是旅行家。","t":[2338,3676]}]},{"id":"ch15p10","audio":true,"sents":[{"es":"-Exactamente -dijo el geógrafo-, pero no soy explorador, ni tengo exploradores que me informen.","zh":"因为城市、河流、山脉、海洋、大洋、沙漠，都不是地理学家亲自去考察的。","t":[100,6075]},{"es":"El geógrafo no puede estar de acá para allá contando las ciudades, los ríos, las montañas, los océanos y los desiertos; es demasiado importante para deambnlar por ahí.","zh":"地理学家身份太重要，不能到处闲逛。","t":[6075,15800]},{"es":"Se queda en su despacho y allí recibe a los exploradores.","zh":"却会在书房里接见旅行家。","t":[15800,19850]},{"es":"Les interroga y toma nota de sus informes.","zh":"向他们打听，把他们的见闻记下来。","t":[19850,23212]},{"es":"Si los informes de alguno de ellos le parecen interesantes, manda hacer una investigación sobre la moralidad del explorador.","zh":"哪段见闻他觉得有意思，地理学家还要派人去核实，看这讲述者靠不靠得住。","t":[23212,30538]},{"es":"-¿Para qué?","zh":"——这是为什么？","t":[30538,30950]}]},{"id":"ch15p11","audio":true,"sents":[{"es":"-Un explorador que mintiera sería una catástrofe para los libros de geografía.","zh":"——因为旅行家要是胡编乱造，地理课本里就要乱成一团了。","t":[100,5138]},{"es":"Y también lo sería un explorador que bebiera demasiado.","zh":"再说，万一是个酒鬼呢？","t":[5138,8975]},{"es":"-¿Por qué?","zh":"——小王子好奇地问。","t":[8975,10338]},{"es":"-preguntó el principito.","zh":"——酒鬼眼里，什么都成双的。","t":[10338,11537]}]},{"id":"ch15p12","audio":true,"sents":[{"es":"-Porque los borrachos ven doble y el geógrafo pondría dos montañas donde sólo habría una.","zh":"结果地理学家就会把只有一座的山，写成两座。","t":[100,4600]}]},{"id":"ch15p13","audio":true,"sents":[{"es":"-Conozco a alguien -dijo el principito-, que sería un mal explorador.","zh":"——我认识一个酒鬼，——小王子说。","t":[100,3512]}]},{"id":"ch15p14","audio":true,"sents":[{"es":"-Es posible.","zh":"——他若当旅行家，准是个蹩脚的。","t":[100,1838]},{"es":"Cuando se está convencído de que la moralidad del explorador es buena, se hace una investigación sobre su descubrimiento.","zh":"不过，旅行家要是可信，就该去核实他的发现。","t":[1838,7800]},{"es":"-¿","zh":"——要亲自去瞧瞧他发现了什么吗？","t":[7800,8775]},{"es":"Se va a ver?","zh":"——不用。","t":[8775,9474]}]},{"id":"ch15p15","audio":true,"sents":[{"es":"-No, eso sería demasiado complicado.","zh":"那太麻烦了。","t":[100,3125]},{"es":"Se exige al explorador que suministre pruebas.","zh":"旅行家得拿出证据来。","t":[3125,6738]},{"es":"Por ejemplo, si se trata del descubrimiento de una gran montaña, se le pide que traiga grandes piedras.","zh":"听到这儿，地理学家忽然激动起来。","t":[6738,11988]}]},{"id":"ch15p16","audio":true,"sents":[{"es":"Súbitamente el geógrafo se sintió emocionado:","zh":"——你可是从远方来的？","t":[100,2626]}]},{"id":"ch15p17","audio":true,"sents":[{"es":"-Pero…","zh":"你是个旅行家呀！","t":[100,450]},{"es":"¡tú vienes de muy lejos!","zh":"快给我讲讲你的星球！","t":[450,2688]},{"es":"¡Tú eres un explorador!","zh":"地理学家说着，翻开他那本厚厚的册子，削尖了铅笔。","t":[2688,4938]},{"es":"Vas a describirme tu planeta.","zh":"等证据交上来，才能用墨水誊清。","t":[4938,6550]}]},{"id":"ch15p18","audio":true,"sents":[{"es":"Y el geógrafo abriendo su regístro afiló su lápiz.","zh":"——嗯？","t":[100,3875]},{"es":"Los relatos de los exploradores se escriben primero con lápiz.","zh":"——地理学家催道。","t":[3875,7063]}]},{"id":"ch15p19","audio":true,"sents":[{"es":"Se espera que el explorador presente sus pruebas para pasarlos a tinta.","zh":"——我的星球上，——小王子说，——有意思的东西不太多。","t":[100,4825]},{"es":"-¿Y bien?","zh":"那儿样样都小得很。","t":[4825,6250]},{"es":"-interrogó el geógrafo.","zh":"有三座火山——两座是活的，一座是死的。","t":[6250,8575]},{"es":"-¡Oh!","zh":"——这倒是，——地理学家说。","t":[8575,9788]},{"es":"Mi tierra -dijo el principito- no es interesante, todo es muy pequeño.","zh":"——我还有一朵花。","t":[9788,14638]},{"es":"Tengo tres volcanes, dos en actividad y uno extinguido; pero nunca se sabe…","zh":"——花我们不感兴趣，——地理学家说。","t":[14638,18888]}]},{"id":"ch15p20","audio":true,"sents":[{"es":"-No, nunca se sabe -dijo el geógrafo.","zh":"——可为什么呢？","t":[100,2188]}]},{"id":"ch15p21","audio":true,"sents":[{"es":"-Tengo también una flor.","zh":"它们多美呀！","t":[100,1312]}]},{"id":"ch15p22","audio":true,"sents":[{"es":"-De las flores no tomamos nota.","zh":"——“转瞬即逝”是什么意思？","t":[100,2812]},{"es":"-¿Por qué?","zh":"——地理学著作，——地理学家说，——是世界上最珍贵的书。","t":[2812,4175]},{"es":"¡Son lo más bonito!","zh":"它们永远不过时。","t":[4175,5250]}]},{"id":"ch15p23","audio":true,"sents":[{"es":"-Porque las flores son efímeras.","zh":"因为山挪窝的事，少之又少。","t":[100,2812]},{"es":"-¿Qué significa \"efímera\"?","zh":"大洋干涸，也极为罕见。","t":[2812,4100]}]},{"id":"ch15p24","audio":true,"sents":[{"es":"-Las geografías -dijo el geógrafo- son los libros más preciados e interesantes; nunca pasan de moda.","zh":"——可死火山也会醒过来呀，——小王子插嘴道。","t":[100,6900]},{"es":"Es muy raro que una montaña cambie de sitio o que un océano quede sin agua.","zh":"——那“转瞬即逝”到底是怎么回事？","t":[6900,11825]},{"es":"Los geógrafos escribimos sobre cosas eternas.","zh":"——对我们地理学家来说，死火山也好，活火山也罢，统统一样，——地理学家解释道。","t":[11825,14425]}]},{"id":"ch15p25","audio":true,"sents":[{"es":"-Pero los volcanes extinguidos pueden despertarse -interrumpió el principito-.","zh":"我们看重的，是山本身。","t":[100,5012]},{"es":"¿Qué significa \"efímera\"?","zh":"它不会变。","t":[5012,6300]}]},{"id":"ch15p26","audio":true,"sents":[{"es":"-Que los volcanes estén o no en actividad es igual para nosotros.","zh":"——小王子又追问一遍。","t":[100,4325]},{"es":"Lo interesante es la montaña que nunca cambia.","zh":"他一旦问出口，就绝不罢休。","t":[4325,6725]}]},{"id":"ch15p27","audio":true,"sents":[{"es":"-Pero, ¿qué significa \"efímera\"?","zh":"——就是说，眼看就要消失的东西。","t":[100,2700]},{"es":"-repitió el principito que en su vida había renunciado a una pregunta una vez formulada.","zh":"——这么说，我的花也快消失了？","t":[2700,7074]}]},{"id":"ch15p28","audio":true,"sents":[{"es":"-Significa que está amenazado de próxima desaparición.","zh":"——那是自然。","t":[100,3975]},{"es":"-¿Mi flor está amenazada de desaparecer próximamente?","zh":"“我的花是转瞬即逝的！","t":[3975,6975]}]},{"id":"ch15p29","audio":true,"sents":[{"es":"-Indudablemente.","zh":"——它只有四根刺，拿什么去抵挡整个世界！","t":[100,1050]}]},{"id":"ch15p30","audio":true,"sents":[{"es":"\"Mi flor as efímera -se dijo el principito- y no tiene más que cuatro espinas para defenderse contra el mundo.","zh":"可我却把它孤零零地撇在了家里！”","t":[100,6625]},{"es":"¡Y la he dejado allá sola en mi casa!\" Por primera vez se arrepintió de haber dejado su planeta, pero bien pronto recobró su valor.","zh":"这一刻，他生平第一次后悔，自己离开了星球。","t":[6625,15125]},{"es":"-¿Qué me aconseja usted que visite ahora?","zh":"不过他还是稳住了心神。","t":[15125,18150]},{"es":"-preguntó.","zh":"——您推荐我去哪些地方看看？","t":[18150,18688]}]},{"id":"ch15p31","audio":true,"sents":[{"es":"-La Tierra -le contestó el geógrafo-.","zh":"——地球，——对方答道。","t":[100,3162]},{"es":"Tiene muy buena reputación…","zh":"——它的名声，还算不坏……","t":[3162,4713]}]},{"id":"ch15p32","audio":true,"sents":[{"es":"Y el principito partió pensando en su flor.","zh":"于是小王子又上了路，心里老惦记着那朵被他抛下的花。","t":[100,2313]}]}]},{"id":"ch16","title_es":"Capítulo 16","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":true,"sents":[{"es":"El séptimo planeta fue, por consiguiente, la Tierra.","zh":"就这样，按地理学家的建议，小王子拜访的第七颗星球，是地球。","t":[100,3788]},{"es":"¡La Tierra no es un planeta cualquiera!","zh":"这颗星球，可非同寻常。","t":[3788,6712]},{"es":"Se cuentan en él ciento once reyes (sin olvidar, naturalmente, los reyes negros), siete mil geógrafos, novecientos mil hombres de negocios, siete millones y medio de borrachos, trescientos once millones de vanidosos, es decir, alrededor de dos mil millones de personas mayores.","zh":"上面住着一百一十一位国王（还不算非洲的国王）、七千名地理学家、九十万个生意人、七百五十万个酒鬼、三亿一千一百万个虚荣的人，以及大约二十亿个大人。","t":[6712,22012]}]},{"id":"ch16p01","audio":true,"sents":[{"es":"Para darles una idea de las dimensiones de la Tierra yo les diría que antes de la invención de la electricidad había que mantener sobre el conjunto de los seis continentes un verdadero ejército de cuatrocientos sesenta y dos mil quinientos once faroleros.","zh":"为了让您知道地球有多大，我告诉您：在电灯发明之前，六大洲上有一支真正的点灯人大军——四十六万两千五百一十一人！","t":[100,12000]}]},{"id":"ch16p02","audio":true,"sents":[{"es":"Vistos desde lejos, hacían un espléndido efecto.","zh":"点灯人大军步调一致，宛如一场芭蕾。","t":[100,3862]},{"es":"Los movimientos de este ejército estaban regulados como los de un ballet de ópera.","zh":"最先上场的，是新西兰和澳大利亚的点灯人。","t":[3862,8800]},{"es":"Primero venía el turno de los faroleros de Nueva Zelandia y de Australia.","zh":"他们点亮路灯，便去睡了。","t":[8800,13438]},{"es":"Encendían sus faroles y se iban a dormir.","zh":"接着，中国和西伯利亚的点灯人开始忙活。","t":[13438,16812]},{"es":"Después tocaba el turno en la danza a los faroleros de China y Siberia, que a su vez se perdían entre bastidores.","zh":"随后，他们也退到了幕后。","t":[16812,23662]},{"es":"Luego seguían los faroleros de Rusia y la India, después los de Africa y Europa y finalmente, los de América del Sur y América del Norte.","zh":"接着轮到俄罗斯和印度，再往后，是非洲和欧洲的点灯人。","t":[23662,32200]},{"es":"Nunca se equivocaban en su orden de entrada en escena.","zh":"这场宏大演出的次序，从来不乱。","t":[32200,36000]},{"es":"Era grandioso.","zh":"真是一幕壮丽的奇观！","t":[36000,36863]}]},{"id":"ch16p03","audio":true,"sents":[{"es":"Solamente el farolero del único farol del polo norte y su colega del único farol del polo sur, llevaban una vida de ociosidad y descanso.","zh":"只有北极的点灯人，和他在南极的兄弟，过得悠闲自在。","t":[100,8225]},{"es":"No trabajaban más que dos veces al año.","zh":"他们每年只点亮、熄灭自己那盏灯，各一次。","t":[8225,10425]}]}]},{"id":"ch17","title_es":"Capítulo 17","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":true,"sents":[{"es":"Cuando se quiere ser ingenioso, sucede que se miente un poco.","zh":"想说句俏皮话，有时免不了要扯点小谎。","t":[100,4138]},{"es":"No he sido muy honesto al hablar de los faroleros y corro el riesgo de dar una falsa idea de nuestro planeta a los que no lo conocen.","zh":"讲点灯人大军时，我没能百分之百说实话。","t":[4138,11425]},{"es":"Los hombres ocupan muy poco lugar sobre la Tierra.","zh":"没见过这颗星球的人，说不定会得出错误的印象。","t":[11425,15000]},{"es":"Si los dos mil millones de habitantes que la pueblan se pusieran de pie y un poco apretados, como en un mitin, cabrían fácilmente en una plaza de veinte millas de largo por veinte de ancho.","zh":"其实，人在地球上占的地方极小。","t":[15000,25350]},{"es":"La humanidad podría amontonarse sobre el más pequeño islote del Pacífico.","zh":"倘若二十亿地球人像开大会那样聚在一处，他们轻轻松松就能挤进一块长宽各二十英里的广场。","t":[25350,29100]}]},{"id":"ch17p01","audio":true,"sents":[{"es":"Las personas mayores no les creerán, seguramente, pues siempre se imaginan que ocupan mucho sitio.","zh":"全世界的居民，随便哪个太平洋小岛都能装下。","t":[100,6350]},{"es":"Se creen importantes como los baobabs.","zh":"大人们自然不肯信。","t":[6350,9475]},{"es":"Les dirán, pues, que hagan el cálculo; eso les gustará ya que adoran las cifras.","zh":"他们总以为自己占着很大的地方。","t":[9475,14912]},{"es":"Pero no es necesario que pierdan el tiempo inútïlmente, puesto que tienen confianza en mí.","zh":"他们觉得自己又高大又了不起，像猴面包树似的。","t":[14912,19187]}]},{"id":"ch17p02","audio":true,"sents":[{"es":"El principito, una vez que llegó a la Tierra, quedó sorprendido de no ver a nadie.","zh":"所以，您不妨让他们算算这笔账。","t":[100,5200]},{"es":"Tenía miedo de haberse equivocado de planeta, cuando un anillo de color de luna se revolvió en la arena.","zh":"可您自己，还是别把时间浪费在这无聊又没用的事上。","t":[5200,10600]}]},{"id":"ch17p03","audio":true,"sents":[{"es":"-¡Buenas noches!","zh":"您是信我的吧？","t":[100,2050]},{"es":"-dijo el principito.","zh":"小王子一到地球，就惊讶不已。","t":[2050,4125]},{"es":"-¡Buenas noches!","zh":"他一个人也没瞧见，竟担心自己找错了星球。","t":[4125,6075]},{"es":"-dijo la serpiente.","zh":"这时，沙地上有一圈月白般的颜色蠕动了一下。","t":[6075,8100]},{"es":"-¿Sobre qué planeta he caído?","zh":"——晚上好，——小王子随口打了个招呼。","t":[8100,10550]},{"es":"-preguntó el principito.","zh":"——晚上好，——蛇说。","t":[10550,11750]}]},{"id":"ch17p04","audio":true,"sents":[{"es":"-Sobre la Tierra, en Africa -respondió la serpiente.","zh":"——我这是到了哪颗星球？","t":[100,3888]},{"es":"-¡Ah!","zh":"——小王子问。","t":[3888,5150]},{"es":"¿Y no hay nadie sobre la Tierra?","zh":"——地球。","t":[5150,6700]}]},{"id":"ch17p05","audio":true,"sents":[{"es":"-Esto es el desierto.","zh":"你在非洲，——蛇答道。","t":[100,2338]},{"es":"En los desiertos no hay nadie.","zh":"——啊！","t":[2338,4925]},{"es":"La Tierra es muy grande -dijo la serpiente.","zh":"这么说，地球上没有人住？","t":[4925,7275]}]},{"id":"ch17p06","audio":true,"sents":[{"es":"El principito se sentó en una piedra y elevó los ojos al cielo.","zh":"——你是在沙漠里。","t":[100,3363]}]},{"id":"ch17p07","audio":true,"sents":[{"es":"-Yo me pregunto -dijo- si las estrellas están encendidas para que cada cual pueda un día encontrar la suya.","zh":"沙漠里，没人住。","t":[100,6275]},{"es":"Mira mi planeta; está precisamente encima de nosotros…","zh":"地球大着呢，——蛇答道。","t":[6275,10500]},{"es":"Pero…","zh":"小王子在一块石头上坐下，抬眼望向天空。","t":[10500,10788]},{"es":"¡qué lejos está!","zh":"——真有意思，——他说，——星星发光，是为了让每个人，终有一天能找到自己的那颗吧？","t":[10788,11600]}]},{"id":"ch17p08","audio":true,"sents":[{"es":"-Es muy bella -dijo la serpiente-.","zh":"我的星球。","t":[100,3038]},{"es":"¿Y qué vienes tú a hacer aquí?","zh":"这会儿，它就正对着咱们头顶。","t":[3038,4500]}]},{"id":"ch17p09","audio":true,"sents":[{"es":"-Tengo problemas con una flor -dijo el principito.","zh":"可它那么远！","t":[100,3688]},{"es":"-¡Ah!","zh":"——它真美，——蛇说。","t":[3688,3813]}]},{"id":"ch17p10","audio":true,"sents":[{"es":"Y se callaron.","zh":"——你到这儿来做什么？","t":[100,1862]},{"es":"-¿Dónde están los hombres?","zh":"——我和一朵花闹了别扭，——小王子答道。","t":[1862,4188]},{"es":"-prosiguió por fin el principito.","zh":"——明白了，——蛇说。","t":[4188,6850]},{"es":"Se está un poco solo en el desierto…","zh":"——那人们都在哪儿？","t":[6850,8824]}]},{"id":"ch17p11","audio":true,"sents":[{"es":"-También se está solo donde los hombres -afirmó la serpiente.","zh":"——沉默片刻后，小王子接着问。","t":[100,3213]}]},{"id":"ch17p12","audio":true,"sents":[{"es":"El principito la miró largo rato y le dijo: -Eres un bicho raro, delgado como un dedo…","zh":"——在沙漠里，怪冷清的。","t":[100,4913]}]},{"id":"ch17p13","audio":true,"sents":[{"es":"-Pero soy más poderoso que el dedo de un rey -le interrumpió la serpiente.","zh":"——在人群里，也一样会孤单，——蛇答道。","t":[100,3950]}]},{"id":"ch17p14","audio":true,"sents":[{"es":"El principito sonrió:","zh":"小王子仔细打量着它。","t":[100,1363]}]},{"id":"ch17p15","audio":true,"sents":[{"es":"-No me pareces muy poderoso…","zh":"——你真有意思，——他终于说。","t":[100,1612]},{"es":"ni siquiera tienes patas…","zh":"——细得像……","t":[1612,3225]},{"es":"ni tan siquiera puedes viajar…","zh":"像一根手指。","t":[3225,4688]}]},{"id":"ch17p16","audio":true,"sents":[{"es":"-Puedo llevarte más lejos que un navío -dijo la serpiente.","zh":"——我可比国王的手指还厉害呢，——蛇说。","t":[100,3274]}]},{"id":"ch17p17","audio":true,"sents":[{"es":"Se enroscó alrededor del tobillo del principito como un brazalete de oro.","zh":"小王子笑了：——你可算不上厉害。","t":[100,3837]}]},{"id":"ch17p18","audio":true,"sents":[{"es":"-Al que yo toco, le hago volver a la tierra de donde salió.","zh":"你连爪子都没有，也没法去远行。","t":[100,4112]},{"es":"Pero tú eres puro y vienes de una estrella…","zh":"——可是，我能比任何船都送你走得更远，——蛇说。","t":[4112,6324]}]},{"id":"ch17p19","audio":true,"sents":[{"es":"El principito no respondió.","zh":"——凡被我碰过的，都会回到他来的那片土地去，——它补了一句。","t":[100,1625]}]},{"id":"ch17p20","audio":true,"sents":[{"es":"-Me das lástima, tan débil sobre esta tierra de granito.","zh":"——可你是洁净的，因为你来自星星。","t":[100,4225]},{"es":"Si algún día echas mucho de menos tu planeta, puedo ayudarte.","zh":"小王子对这话，什么也没回答。","t":[4225,8425]},{"es":"Puedo…","zh":"——我怜惜你，——蛇接着说。","t":[8425,9012]},{"es":"-¡Oh!","zh":"在这石头般的地球上，你太柔弱了。","t":[9012,10138]},{"es":"-dijo el principito-.","zh":"说不定哪天，你要是后悔离开了星球，我能帮上忙。","t":[10138,12212]},{"es":"Te he comprendido.","zh":"我本可以……","t":[12212,14150]},{"es":"Pero ¿por qué hablas con enigmas?","zh":"——我明白你的意思，——小王子答道。","t":[14150,15812]}]},{"id":"ch17p21","audio":true,"sents":[{"es":"-Yo los resuelvo todos -dijo la serpiente.","zh":"——可你为什么老说些谜语？","t":[100,2450]}]},{"id":"ch17p22","audio":true,"sents":[{"es":"Y se callaron.","zh":"——我的谜语，我自己来解，——蛇说。两人都不再作声。","t":[100,875]}]}]},{"id":"ch18","title_es":"Capítulo 18","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":true,"sents":[{"es":"El principito atravesó el desierto en el que sólo encontró una flor de tres pétalos, una flor de nada.","zh":"小王子穿过沙漠，途中只遇见一朵花。","t":[100,5350]}]},{"id":"ch18p01","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"它只有三片花瓣，毫不起眼。","t":[100,1950]},{"es":"-dijo el principito.","zh":"——你好，——小王子说。","t":[1950,4025]},{"es":"-¡Buenos días!","zh":"——你好，——花儿答道。","t":[4025,5875]},{"es":"-dijo la flor.","zh":"——那人们都在哪儿？","t":[5875,7588]},{"es":"-¿Dónde están los hombres?","zh":"——小王子客气地问。","t":[7588,9912]},{"es":"-preguntó cortésmente el principito.","zh":"花儿曾经见过一支商队从旁边经过。","t":[9912,11825]}]},{"id":"ch18p02","audio":true,"sents":[{"es":"La flor, un día, había visto pasar una caravana.","zh":"——人？","t":[100,3988]},{"es":"-¿Los hombres?","zh":"——人？","t":[3988,5712]},{"es":"No existen más que seis o siete, me parece.","zh":"我想，有六七个吧。","t":[5712,8175]}]},{"id":"ch18p03","audio":true,"sents":[{"es":"Los he visto hace ya años y nunca se sabe dónde encontrarlos.","zh":"那还是好多年前，我见过他们。","t":[100,4400]},{"es":"El viento los pasea.","zh":"你永远说不准，上哪儿去找他们。","t":[4400,6488]},{"es":"Les faltan las raíces.","zh":"风把他们吹得到处跑。","t":[6488,8875]},{"es":"Esto les molesta.","zh":"他们又没有根，这就麻烦……","t":[8875,9874]}]},{"id":"ch18p04","audio":true,"sents":[{"es":"-Adiós -dijo el principito.","zh":"——再见，——小王子说。","t":[100,1650]}]},{"id":"ch18p05","audio":true,"sents":[{"es":"-Adiós -dijo la flor.","zh":"——再见，——花儿答道。","t":[100,1350]}]}]},{"id":"ch19","title_es":"Capítulo 19","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":true,"sents":[{"es":"El principito escaló hasta la cima de una alta montaña.","zh":"小王子登上一座高山。","t":[100,3950]},{"es":"Las únicas montañas que él había conocido eran los tres volcanes que le llegaban a la rodilla.","zh":"他从前见过的山，只有自己星球上的三座火山。","t":[3950,9512]},{"es":"El volcán extinguido lo utilizaba como taburete.","zh":"他从前见过的山，只有自己星球上的三座火山。","t":[9512,13000]},{"es":"\"Desde una montaña tan alta como ésta, se había dicho, podré ver todo el planeta y a todos los hombres…\" Pero no alcanzó a ver más que algunas puntas de rocas.","zh":"它们都不高——刚到他的膝盖，那座死火山，他还当凳子坐。","t":[13000,22088]}]},{"id":"ch19p01","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"所以","t":[100,1950]},{"es":"-exclamó el principito al acaso.","zh":"小王子想，从这么高的山上，准能一眼望见整颗星球和上面所有的人。","t":[1950,4725]},{"es":"-¡Buenos días!","zh":"小王子想，从这么高的山上，准能一眼望见整颗星球和上面所有的人。","t":[4725,6575]},{"es":"¡Buenos días!","zh":"可他什么也没看见，只有尖削的岩石。","t":[6575,8425]},{"es":"¡Buenos días!","zh":"——你好，——他随口打了个招呼。","t":[8425,10275]},{"es":"-respondió el eco -¿Quién eres tú?","zh":"——你好，——他随口打了个招呼。","t":[10275,13125]},{"es":"-preguntó el principito.","zh":"——你好，你好，你好，——回声应道。","t":[13125,15312]},{"es":"-¿Quién eres tú?…","zh":"——你们是谁？","t":[15312,17075]},{"es":"¿Quién eres tú?…","zh":"——你们是谁？","t":[17075,18838]},{"es":"¿Quién eres tú?…","zh":"——小王子问。","t":[18838,19612]},{"es":"-contestó el eco.","zh":"——你们是谁，你们是谁，你们是谁？","t":[19612,20562]}]},{"id":"ch19p02","audio":true,"sents":[{"es":"-Sed mis amigos, estoy solo -dijo el principito.","zh":"——回声问。","t":[100,2950]}]},{"id":"ch19p03","audio":true,"sents":[{"es":"-Estoy solo…","zh":"——回声问。","t":[100,962]},{"es":"estoy solo…","zh":"——做我的朋友吧，——小王子提议，——我好孤单。","t":[962,1950]},{"es":"estoy solo…","zh":"——我孤单，我孤单，我孤单，——回声重复着。","t":[1950,2912]},{"es":"-repitió el eco.","zh":"——我孤单，我孤单，我孤单，——回声重复着。","t":[2912,3900]}]},{"id":"ch19p04","audio":true,"sents":[{"es":"\"¡Qué planeta más raro!","zh":"“这是颗多古怪的星球啊，”小王子想，“又干，又尖，又咸。","t":[100,2250]},{"es":"-pensó entonces el principito-, es seco, puntiagudo y salado.","zh":"人呢，一点想象力也没有。","t":[2250,6500]},{"es":"Y los hombres carecen de imaginación; no hacen más que repetir lo que se les dice…","zh":"只会重复别人说的话。","t":[6500,11725]},{"es":"En mi tierra tenía una flor: hablaba siempre la primera…","zh":"只会重复别人说的话。","t":[11725,14837]},{"es":"\"","zh":"可在我的星球上，有一朵花，我的美人儿，她总是先开口跟我说话。”","t":[14837,15337]}]}]},{"id":"ch20","title_es":"Capítulo 20","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":true,"sents":[{"es":"Pero sucedió que el principito, habiendo atravesado arenas, rocas y nieves, descubrió finalmente un camino.","zh":"就这样，小王子穿过沙地，越过岩石和雪原，终于撞见了一条路。","t":[100,7138]},{"es":"Y los caminos llevan siempre a la morada de los hombres.","zh":"天下的路，都通向有人烟的地方。","t":[7138,9838]}]},{"id":"ch20p01","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"——你们好，——小王子说。","t":[100,1950]},{"es":"-dijo.","zh":"因为眼前是一座玫瑰盛开的花园。","t":[1950,2338]}]},{"id":"ch20p02","audio":true,"sents":[{"es":"Era un jardín cuajado de rosas.","zh":"因为眼前是一座玫瑰盛开的花园。","t":[100,2925]},{"es":"-¡Buenos días!","zh":"——你们好，——玫瑰们说。","t":[2925,4775]},{"es":"-dijeran las rosas.","zh":"小王子望望她们，觉得她们和他的那朵花十分相像。","t":[4775,5887]}]},{"id":"ch20p03","audio":true,"sents":[{"es":"El principito las miró.","zh":"——你们是谁？","t":[100,2338]},{"es":"¡Todas se parecían tanto a su flor!","zh":"——他被眼前的景象惊住了，问道。","t":[2338,5100]},{"es":"-¿Quiénes son ustedes?","zh":"——我们是玫瑰，——玫瑰们答道。","t":[5100,7288]},{"es":"-les preguntó estupefacto.","zh":"——是吗？","t":[7288,8788]}]},{"id":"ch20p04","audio":true,"sents":[{"es":"-Somos las rosas -respondieron éstas.","zh":"——小王子说……","t":[100,3462]},{"es":"-¡Ah!","zh":"——小王子说……","t":[3462,4725]},{"es":"-exclamó el principito.","zh":"他觉得自己好不辛酸。","t":[4725,6024]}]},{"id":"ch20p05","audio":true,"sents":[{"es":"Y se sintió muy desgraciado.","zh":"他的那朵花曾对他说，自己是普天之下独一无二的。","t":[100,2650]},{"es":"Su flor le había dicho que era la única de su especie en todo el universo.","zh":"可这儿，单单一个园子里，就不下五千朵！","t":[2650,7312]},{"es":"¡Y ahora t.enía ante sus ojos más de cinco mil.todas semejantes, en un solo jardín!","zh":"“我的美人儿要是见了这光景，”小王子想，“准会伤心透顶。","t":[7312,12175]}]},{"id":"ch20p06","audio":true,"sents":[{"es":"Si ella viese todo esto, se decía el principito, se sentiría vejada, tosería muchísimo y simularía morir para escapar al ridículo.","zh":"为了不显得滑稽，她多半会拼命咳嗽，装出快死的样子。","t":[100,8138]},{"es":"Y yo tendría que fingirle cuidados, pues sería capaz de dejarse morir verdaderamente para humillarme a mí también…","zh":"而我，就得装作照料她的样子。","t":[8138,14037]},{"es":"\"","zh":"不然，为了跟我怄气，她说不定会真的去死。”","t":[14037,14537]}]},{"id":"ch20p07","audio":true,"sents":[{"es":"Y luego continuó diciéndose: \"Me creía rico con una flor única y resulta que no tengo más que una rosa ordinaria.","zh":"不然，为了跟我怄气，她说不定会真的去死。”","t":[100,7338]},{"es":"Eso y mis tres volcanes que apenas me llegan a la rodilla y uno de Ios cuales acaso esté extinguido para siempre.","zh":"接着他又暗自道：“我原以为自己是个富翁，拥有一朵举世无双的花，到头来不过是一朵寻常的玫瑰。","t":[7338,14450]},{"es":"Realmente no soy un gran príncipe…","zh":"她，加上三座火山——其中一座还灭了，说不定永远灭着——这点家当，对于一个真正的王子，实在少得可怜。”","t":[14450,17388]},{"es":"\" Y echándose sobre la hierba, el principito lloró.","zh":"说着，他扑倒在草地上，哭了起来。","t":[17388,19950]}]}]},{"id":"ch21","title_es":"Capítulo 21","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":true,"sents":[{"es":"Entonces apareció el zorro:","zh":"这时，狐狸出现了。","t":[100,1713]}]},{"id":"ch21p01","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"——你好，——他说。","t":[100,1950]},{"es":"-dijo el zorro.","zh":"——你好，——小王子彬彬有礼地答道。","t":[1950,3788]},{"es":"-¡Buenos días!","zh":"可他转过身，却什么人也没看见。","t":[3788,5638]},{"es":"-respondió cortésmente el principito que se volvió pero no vío nada.","zh":"——你是谁？","t":[5638,9038]}]},{"id":"ch21p02","audio":true,"sents":[{"es":"-Estoy aquí, bajo el manzano -díjo la voz.","zh":"——小王子问。","t":[100,3525]},{"es":"-¿Quién eres tú?","zh":"——你真好看……","t":[3525,5288]},{"es":"-preguntó el principito-.","zh":"——我是一只狐狸，——狐狸答道。","t":[5288,7475]},{"es":"¡Qué bonito eres!","zh":"——你不想跟我玩玩吗？","t":[7475,8425]}]},{"id":"ch21p03","audio":true,"sents":[{"es":"-Soy un zorro -dijo el zorro.","zh":"——小王子提议。","t":[100,1725]}]},{"id":"ch21p04","audio":true,"sents":[{"es":"-Ven a jugar conmigo -le propuso el principito-, ¡estoy tan triste!","zh":"——我心里好难过……","t":[100,3537]}]},{"id":"ch21p05","audio":true,"sents":[{"es":"-No puedo jugar contigo -dijo el zorro-, no estoy domesticado.","zh":"——我还没被驯养。","t":[100,4375]},{"es":"-¡Ah, perdón!","zh":"——啊……","t":[4375,6075]},{"es":"-dijo el principito.","zh":"那，真抱歉，——小王子说。","t":[6075,7163]}]},{"id":"ch21p06","audio":true,"sents":[{"es":"Pero después de una breve reflexión, añadió: -¿Qué significa \"domesticar\"?","zh":"可他想了想，又问：——“驯养”是什么意思？","t":[100,4200]}]},{"id":"ch21p07","audio":true,"sents":[{"es":"-Tú no eres de aquí -dijo el zorro- ¿qué buscas?","zh":"——我看你不是本地人，——狐狸答道。","t":[100,2650]}]},{"id":"ch21p08","audio":true,"sents":[{"es":"-Busco a los hombres -le respondió el principito-.","zh":"——你在这儿找什么？","t":[100,3700]},{"es":"¿Qué significa \"domesticar\"?","zh":"——那“驯养”到底是什么意思？","t":[3700,5113]}]},{"id":"ch21p09","audio":true,"sents":[{"es":"-Los hombres -dijo el zorro- tienen escopetas y cazan.","zh":"——人哪，——狐狸说，——他们有枪，还打猎。","t":[100,4112]},{"es":"¡Es muy molesto!","zh":"这真叫人受不了。","t":[4112,5988]},{"es":"Pero también crían gallinas.","zh":"而且他们还养鸡。","t":[5988,8525]},{"es":"Es lo único que les interesa.","zh":"他们只操心这个。","t":[8525,11125]},{"es":"¿Tú buscas gallinas?","zh":"你找鸡吗？","t":[11125,12250]}]},{"id":"ch21p10","audio":true,"sents":[{"es":"-No -díjo el principito-.","zh":"——不，——小王子答道。","t":[100,2500]},{"es":"Busco amigos.","zh":"那“驯养”到底是什么意思？","t":[2500,4412]},{"es":"¿Qué significa \"domesticar\"?","zh":"——这是一件早被忘掉的事，——狐狸答道。","t":[4412,6800]},{"es":"-volvió a preguntar el principito.","zh":"——意思是，建立牵系。","t":[6800,8463]}]},{"id":"ch21p11","audio":true,"sents":[{"es":"-Es una cosa ya olvidada -dijo el zorro-, significa \"crear vínculos…","zh":"——建立牵系？","t":[100,5100]},{"es":"\" -¿Crear vínculos?","zh":"——正是，——狐狸说。","t":[5100,6062]}]},{"id":"ch21p12","audio":true,"sents":[{"es":"-Efectivamente, verás -dijo el zorro-.","zh":"——此刻的你，不过是个小男孩，跟十万个别的小男孩一模一样。","t":[100,3175]},{"es":"Tú no eres para mí todavía más que un muchachito igual a otros cien mil muchachitos y no te necesito para nada.","zh":"我不需要你。","t":[3175,9675]},{"es":"Tampoco tú tienes necesidad de mí y no soy para ti más que un zorro entre otros cien mil zorros semejantes.","zh":"可一旦你驯养了我，我们便彼此需要了。","t":[9675,16012]},{"es":"Pero si tú me domesticas, entonces tendremos necesidad el uno del otro.","zh":"你于我，会是世上唯一的；我于你，也会是唯一的。","t":[16012,20700]},{"es":"Tú serás para mí único en el mundo, yo seré para ti único en el mundo…","zh":"——我好像有点明白了，——小王子说。","t":[20700,24512]}]},{"id":"ch21p13","audio":true,"sents":[{"es":"-Comienzo a comprender -dijo el principito-.","zh":"——我有一朵花，我的美人儿……","t":[100,3300]},{"es":"Hay una flor…","zh":"我觉得，是她驯养了我。","t":[3300,4225]},{"es":"creo que ella me ha domesticado…","zh":"——那是可能的，——狐狸答道。","t":[4225,5776]}]},{"id":"ch21p14","audio":true,"sents":[{"es":"-Es posible -concedió el zorro-, en la Tierra se ven todo tipo de cosas.","zh":"——这可不是在地球上发生的，——小王子说。","t":[100,4900]},{"es":"-¡Oh, no es en la Tierra!","zh":"狐狸大吃一惊：——在别的星球上？","t":[4900,7075]},{"es":"-exclamó el principito.","zh":"——对。","t":[7075,8374]}]},{"id":"ch21p15","audio":true,"sents":[{"es":"El zorro pareció intrigado: -¿En otro planeta?","zh":"——那儿有猎人吗？","t":[100,2500]}]},{"id":"ch21p16","audio":true,"sents":[{"es":"-Sí.","zh":"——没有。","t":[100,1438]},{"es":"-¿Hay cazadores en ese planeta?","zh":"——有鸡吗？","t":[1438,3062]}]},{"id":"ch21p17","audio":true,"sents":[{"es":"-No.","zh":"——没有。","t":[100,1450]},{"es":"-¡Qué interesante!","zh":"可他又回到原来的话题：“你瞧，我的日子相当单调。","t":[1450,3312]},{"es":"¿Y gallinas?","zh":"我追鸡，猎人追我。","t":[3312,3962]}]},{"id":"ch21p18","audio":true,"sents":[{"es":"-No.","zh":"所有的鸡都一个样，所有的人也都彼此相像。","t":[100,338]}]},{"id":"ch21p19","audio":true,"sents":[{"es":"-Nada es perfecto -suspiró el zorro.","zh":"所以我有点腻烦。","t":[100,2288]}]},{"id":"ch21p20","audio":true,"sents":[{"es":"Y después volviendo a su idea:","zh":"可你要是驯养了我，我的生活便仿佛洒满了阳光。","t":[100,1774]}]},{"id":"ch21p21","audio":true,"sents":[{"es":"-Mi vida es muy monótona.","zh":"我能认出你脚步的声音，那声音，和所有人的都不一样。","t":[100,2462]},{"es":"Cazo gallinas y los hombres me cazan a mí.","zh":"别人的脚步声，我就钻回地底；你的，却会把我从洞里唤出来。","t":[2462,5562]},{"es":"Todas las gallinas se parecen y todos los hombres son iguales; por consiguiente me aburro un poco.","zh":"还有，你瞧！","t":[5562,11375]},{"es":"Si tú me domesticas, mi vida estará llena de sól.","zh":"那边那片麦田，看见了吗？","t":[11375,13950]}]},{"id":"ch21p22","audio":true,"sents":[{"es":"Conoceré el rumor de unos pasos diferentes a todos los demás.","zh":"我不吃面包。","t":[100,4375]},{"es":"Los otros pasos me hacen esconder bajo la tierra; los tuyos me llamarán fuera de la madriguera como una música.","zh":"麦子对我毫无用处。","t":[4375,11150]},{"es":"Y además, ¡mira!","zh":"而麦田","t":[11150,13112]},{"es":"¿Ves allá abajo los campos de trigo?","zh":"对我毫无意义，想想也够叫人伤感的。","t":[13112,15962]},{"es":"Yo no como pan y por lo tanto el trigo es para mí algo inútil.","zh":"你想想，等你驯养了我，该多美呀？","t":[15962,19962]},{"es":"Los campos de trigo no me recuerdan nada y eso me pone triste.","zh":"金色的麦浪，会让我想起你。","t":[19962,24188]},{"es":"¡Pero tú tienes los cabellos dorados y será algo maravilloso cuando me domestiques!","zh":"我会爱上它在风里沙沙作响的声音……","t":[24188,29275]},{"es":"El trigo, que es dorado también, será un recuerdo de ti.","zh":"狐狸住了口，久久地望着小王子：“求求你，驯养我吧！”","t":[29275,33238]},{"es":"Y amaré el ruido del viento en el trigo.","zh":"——我也乐意，——小王子答道。","t":[33238,35212]}]},{"id":"ch21p23","audio":true,"sents":[{"es":"El zorro se calló y miró un buen rato al principito:","zh":"——可我的时间不多。","t":[100,2850]}]},{"id":"ch21p24","audio":true,"sents":[{"es":"-Por favor…","zh":"我得去找朋友，还有那么多东西要懂。","t":[100,762]},{"es":"domestícame -le dijo.","zh":"——人已经没有耐性，去好好懂点什么了。","t":[762,2038]}]},{"id":"ch21p25","audio":true,"sents":[{"es":"-Bien quisiera -le respondió el principito pero no tengo mucho tiempo.","zh":"商人把现成的东西卖给他们。","t":[100,4738]},{"es":"He de buscar amigos y conocer muchas cosas.","zh":"却没有哪个商人，出售朋友。","t":[4738,7138]}]},{"id":"ch21p26","audio":true,"sents":[{"es":"-Sólo se conocen bien las cosas que se domestican -dijo el zorro-.","zh":"所以人也就没有朋友。","t":[100,4475]},{"es":"Los hombres ya no fienen tiempo de conocer nada.","zh":"你要是想找个朋友，就驯养我吧！","t":[4475,7888]},{"es":"Lo compran todo hecho en las tiendas.","zh":"——那该怎么做呢？","t":[7888,10838]},{"es":"Y como no hay tiendas donde vendan amigos, Ios hombres no tienen ya amigos.","zh":"——小王子问。","t":[10838,16075]},{"es":"¡Si quieres un amigo, domestícame!","zh":"——先像这样，在离我稍远些的草地上坐下。","t":[16075,18888]},{"es":"-¿Qué debo hacer?","zh":"我拿眼角瞄着你，你什么也别说。","t":[18888,20662]},{"es":"-preguntó el príncipito.","zh":"言语，是误会的根源。","t":[20662,21937]}]},{"id":"ch21p27","audio":true,"sents":[{"es":"-Debes tener mucha paciencia -respondió el zorro-.","zh":"不过，一天天过去，你可以坐得离我近一点……","t":[100,3962]},{"es":"Te sentarás al principio ún poco lejos de mí, así, en el suelo; yo te miraré con el rabillo del ojo y tú no me dirás nada.","zh":"第二天，小王子又来和狐狸相会。","t":[3962,11538]},{"es":"El lenguaje es fuente de malos entendidos.","zh":"——最好，——狐狸说，——你每天同一个时辰来。","t":[11538,14762]},{"es":"Pero cada día podrás sentarte un poco más cerca…","zh":"越是临近相会的时刻，我就越发高兴。","t":[14762,17288]}]},{"id":"ch21p28","audio":true,"sents":[{"es":"El principito volvió al día siguiente.","zh":"到了四点整，我就会坐立不安、心慌起来。","t":[100,2075]}]},{"id":"ch21p29","audio":true,"sents":[{"es":"-Hubiera sido mejor -dijo el zorro- que vinieras a la misma hora.","zh":"这样，我便懂得了“幸福”的代价！","t":[100,4500]},{"es":"Si vienes, por ejempló, a las cuatro de la tarde; desde las tres yo empezaría a ser dichoso.","zh":"可你要是每次来的时辰都不一样，我就不知道该什么时候开始盼着相会……","t":[4500,10262]},{"es":"Cuanto más avance la hora, más feliz me sentiré.","zh":"得有个仪式……","t":[10262,13950]},{"es":"A las cuatro me sentiré agitado e inquieto, descubriré así lo que vale la feliçidad.","zh":"——“仪式”是什么？","t":[13950,19275]},{"es":"Pero si tú vienes a cualquier hora, nunça sabré cuándo preparar mi corazón…","zh":"——小王子问。","t":[19275,24038]},{"es":"Los ritos son necesarios.","zh":"——它让某一天不同于别的日子，让某一时刻变得特别。","t":[24038,26638]},{"es":"-¿Qué es un rito?","zh":"比如，我的那些猎人，有个仪式。","t":[26638,28500]},{"es":"-inquirió el principito.","zh":"每星期四，他们和村里的姑娘跳舞。","t":[28500,29787]}]},{"id":"ch21p30","audio":true,"sents":[{"es":"-Es también algo demasiado olvidado -dijo el zorro-.","zh":"所以星期四，对他们来说就是好日子。","t":[100,3888]},{"es":"Es lo que hace que un día no se parezca a otro día y que una hora sea diferente a otra.","zh":"那会儿我就能一路溜达到葡萄园去。","t":[3888,8362]}]},{"id":"ch21p31","audio":true,"sents":[{"es":"Entre los cazadores, por ejemplo, hay un rito.","zh":"要是猎人爱跳就跳，所有的日子就都一个样了，我也没法给自己找点小乐趣。","t":[100,3675]},{"es":"Los jueves bailan con las muchachas del pueblo.","zh":"终于，小王子驯养了狐狸。可临到分别，狐狸叹道：——没了你，我会哭的。","t":[3675,6975]},{"es":"Los jueves entonces son días maravillosos en los que puedo ir de paseo hasta la viña.","zh":"——我本不想让你难过。","t":[6975,12162]},{"es":"Si los cazadores no bailaran en día fijo, todos los días se parecerían y yo no tendría vacaciones.","zh":"是你自己，要我驯养你的。","t":[12162,17738]}]},{"id":"ch21p32","audio":true,"sents":[{"es":"De esta manera el principito domesticó al zorro.","zh":"——这倒是，——狐狸说。","t":[100,3575]},{"es":"Y cuando se fue acercando eI día de la partida: -¡Ah!","zh":"——可你也会哭的！","t":[3575,7212]},{"es":"-dijo el zorro-, lloraré.","zh":"——那当然，——狐狸叹道。","t":[7212,8637]}]},{"id":"ch21p33","audio":true,"sents":[{"es":"-Tuya es la culpa -le dijo el principito-, yo no quería hacerte daño, pero tú has querido que te domestique…","zh":"——那你到底得了什么好处呢？","t":[100,5600]}]},{"id":"ch21p34","audio":true,"sents":[{"es":"-Ciertamente -dijo el zorro.","zh":"接着狐狸说：——去吧，再去看一眼那些玫瑰，这回你会明白，你的玫瑰是世上唯一的。","t":[100,1575]}]},{"id":"ch21p35","audio":true,"sents":[{"es":"-Y vas a llorar!, -dijo él principito.","zh":"等你回来向我道别，我再告诉你一个秘密。","t":[100,3050]},{"es":"-¡Seguro!","zh":"于是小王子走去，看那些玫瑰。","t":[3050,3562]}]},{"id":"ch21p36","audio":true,"sents":[{"es":"-No ganas nada.","zh":"——你们和我的玫瑰一点都不像，——他对她们说。","t":[100,1038]}]},{"id":"ch21p37","audio":true,"sents":[{"es":"-Gano -dijo el zoro- he ganado a causa del color del trigo.","zh":"——你们根本不是她。","t":[100,3362]}]},{"id":"ch21p38","audio":true,"sents":[{"es":"Y luego añadió:","zh":"你们谁也没被驯养过，也没驯养过谁。","t":[100,1000]}]},{"id":"ch21p39","audio":true,"sents":[{"es":"-Vete a ver las rosas; comprenderás que la tuya es única en el mundo.","zh":"你们就像我那狐狸当初的样子。","t":[100,4762]},{"es":"Volverás a decirme adiós y yo te regalaré un secreto.","zh":"他成了我的朋友，如今于我，是这世上唯一的。","t":[4762,7650]}]},{"id":"ch21p40","audio":true,"sents":[{"es":"El principito se fue a ver las rosas a las que dijo:","zh":"玫瑰们仿佛被他的话触动了。","t":[100,2724]}]},{"id":"ch21p41","audio":true,"sents":[{"es":"-No son nada, ni en nada se parecen a mi rosa.","zh":"——你们很美，——小王子补了一句，——却是空的。","t":[100,3775]},{"es":"Nadie las ha domesticado ni ustedes han domesticado a nadie.","zh":"不值得为你们去死。","t":[3775,6863]}]},{"id":"ch21p42","audio":true,"sents":[{"es":"Son como el zorro era antes, que en nada se diferenciaba de otros cien mil zorros.","zh":"当然，我的玫瑰……","t":[100,5412]},{"es":"Pero yo le hice mi amigo y ahora es único en el mundo.","zh":"一个过路人，准会说她跟你们一个样。","t":[5412,8012]}]},{"id":"ch21p43","audio":true,"sents":[{"es":"Las rosas se sentían molestas oyendo al principito, que continuó diciéndoles:","zh":"可对我来说，她比你们全都重要。","t":[100,4188]}]},{"id":"ch21p44","audio":true,"sents":[{"es":"-Son muy bellas, pero están vacías y nadie daría la vida por ustedes.","zh":"正是她，我用屏风遮过，把毛毛虫从她身上赶走——只留下两三只要它们变蝴蝶。","t":[100,4688]},{"es":"Cualquiera que las vea podrá creer indudablemente que mí rosa es igual que cualquiera de ustedes.","zh":"我听过她的抱怨和吹嘘。","t":[4688,10400]},{"es":"Pero ella se sabe más importante que todas, porque yo la he regado, porque ha sido a ella a la que abrigué con el fanal, porque yo le maté los gusanos (salvo dos o tres que se hicieron mariposas) y es a ella a la que yo he oído quejarse, alabarse y algunas veces hasta callarse.","zh":"连她沉默不语，我也听得出。","t":[10400,26062]},{"es":"Porque es mi rosa, en fin.","zh":"因为，她是我的玫瑰！","t":[26062,27712]}]},{"id":"ch21p45","audio":true,"sents":[{"es":"Y volvió con el zorro.","zh":"接着，他回到狐狸身边。","t":[100,1274]}]},{"id":"ch21p46","audio":true,"sents":[{"es":"-Adiós -le dijo.","zh":"——再见，——他对狐狸说。","t":[100,1163]}]},{"id":"ch21p47","audio":true,"sents":[{"es":"-Adiós -dijo el zorro-.","zh":"——这是我的秘密。","t":[100,2450]},{"es":"He aquí mi secreto, que no puede ser más simple: sólo con el corazón se puede ver bien; lo esencial es invisible para los ojos.","zh":"它很简单。","t":[2450,9500]}]},{"id":"ch21p48","audio":true,"sents":[{"es":"-Lo esencial es invisible para los ojos -repitió el principito para acordarse.","zh":"只有用心，才能看清楚。","t":[100,4325]}]},{"id":"ch21p49","audio":true,"sents":[{"es":"-Lo que hace más importante a tu rosa, es el tiempo que tú has perdido con ella.","zh":"最重要的东西，用眼睛是看不见的。","t":[100,4112]}]},{"id":"ch21p50","audio":true,"sents":[{"es":"-Es el tiempo que yo he perdido con ella…","zh":"——最重要的东西，用眼睛是看不见的，——小王子重复着，好把它记住。","t":[100,2350]},{"es":"-repitió el principito para recordarlo.","zh":"——正是因为你为你的玫瑰，花费了时间，她才对你变得如此重要。","t":[2350,4387]}]},{"id":"ch21p51","audio":true,"sents":[{"es":"-Los hombres han olvidado esta verdad -dijo el zorro-, pero tú no debes olvidarla.","zh":"——我为我的玫瑰，花费的时间……——小王子重复着，好把它记住。","t":[100,5025]},{"es":"Eres responsable para siempre de lo que has domesticado.","zh":"——可你不该把它忘了。","t":[5025,8775]},{"es":"Tú eres responsable de tu rosa…","zh":"你要对你驯养过的一切，永远负责。","t":[8775,10550]}]},{"id":"ch21p52","audio":true,"sents":[{"es":"-Yo soy responsable de mi rosa…","zh":"你也要对你的玫瑰负责。","t":[100,2188]},{"es":"-repitió el principito a fin de recordarlo","zh":"——我对我的玫瑰负责，——小王子重复着，好把它记住。","t":[2188,4337]}]}]},{"id":"ch22","title_es":"Capítulo 22","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"“你好，”小王子说。","t":[100,1950]},{"es":"-dijo el principito.","zh":"“你好，”扳道工回答。","t":[1950,4025]},{"es":"-¡Buenos días!","zh":"“你在这里做什么？”","t":[4025,5875]},{"es":"-respondió el guardavías.","zh":"小王子问。","t":[5875,8338]},{"es":"-¿Qué haces aquí?","zh":"“我把乘客分类，成千上万地，”扳道工回答。","t":[8338,10075]},{"es":"-le preguntó el principito.","zh":"“我发出一列列火车，把他们带走——有的向右，有的向左。”","t":[10075,11474]}]},{"id":"ch22p01","audio":true,"sents":[{"es":"-Formo con los viajeros paquetes de mil y despacho los trenes que los llevan, ya a la derecha, ya a la izquierda.","zh":"就在这时，一列灯火通明的快车从扳道工颤抖的小屋旁轰隆隆驶过。","t":[100,5926]}]},{"id":"ch22p02","audio":true,"sents":[{"es":"Y un tren rápido iluminado, rugiendo como el trueno, hizo temblar la caseta del guardavías.","zh":"“他们很匆忙，”小王子说。","t":[100,5312]}]},{"id":"ch22p03","audio":true,"sents":[{"es":"-Tienen mucha prisa -dijo el principito-.","zh":"“他们在寻找什么？”","t":[100,3425]},{"es":"¿Qué buscan?","zh":"“这连火车司机自己也不知道，”扳道工回答。","t":[3425,4062]}]},{"id":"ch22p04","audio":true,"sents":[{"es":"-Ni siquiera el conductor de la locomotora lo sabe -dijo el guardavías.","zh":"这时，那列灯火通明的快车又朝相反方向轰隆驶过。","t":[100,3788]}]},{"id":"ch22p05","audio":true,"sents":[{"es":"Un segundo rápido iluminado rugió en sentido inverso.","zh":"“他们已经回来了吗？”","t":[100,4088]},{"es":"-¿Ya vuelve?","zh":"小王子问。","t":[4088,5650]},{"es":"-preguntó el principito.","zh":"“对开的火车。”","t":[5650,6850]}]},{"id":"ch22p06","audio":true,"sents":[{"es":"-No son los mismos -contestó el guardvías-.","zh":"“他们不喜欢自己待过的地方吗？”","t":[100,3438]},{"es":"Es un cambio.","zh":"小王子问。","t":[3438,5212]},{"es":"-¿No se sentían contentos donde estaban?","zh":"“他们对什么都永远不满意，”扳道工回答。","t":[5212,7437]}]},{"id":"ch22p07","audio":true,"sents":[{"es":"-Nunca se siente uno contento donde está -respondió el guardavías.","zh":"第三列灯火通明的特快列车又轰鸣着驶过。","t":[100,3975]}]},{"id":"ch22p08","audio":true,"sents":[{"es":"Y rugió el trueno de un tercer rápido iluminado.","zh":"“这些人是想追上前面的乘客吗？”","t":[100,3675]},{"es":"-¿Van persiguiendo a los primeros viajeros?","zh":"小王子问。","t":[3675,6800]},{"es":"-preguntó el principito.","zh":"“他们并没有在追赶谁，”扳道工回答。","t":[6800,8000]}]},{"id":"ch22p09","audio":true,"sents":[{"es":"-No persiguen absolutamente nada -le dijo el guardavías-; duermen o bostezan allí dentro.","zh":"“车里的人不是在睡觉，就是在打哈欠。”","t":[100,5812]},{"es":"Unicamente los niños aplastan su nariz contra los vidrios.","zh":"只有孩子们把鼻子贴在玻璃上。","t":[5812,9050]}]},{"id":"ch22p10","audio":true,"sents":[{"es":"-Unicamente los niños saben lo que buscan -dijo el principito.","zh":"“只有孩子知道自己在寻找什么，”小王子说。","t":[100,4288]},{"es":"Pierden el tiempo con una muñeca de trapo que viene a ser lo más importante para ellos y si se la quitan, lloran…","zh":"“他们把时间花在布偶娃娃上，于是娃娃对他们就变得非常重要。”","t":[4288,10038]},{"es":"-¡Qué suerte tienen!","zh":"如果有人把娃娃拿走，他们就会哭。","t":[10038,11875]},{"es":"-dijo el guardavías.","zh":"“他们真幸福，”扳道工说。","t":[11875,13000]}]}]},{"id":"ch23","title_es":"Capítulo 23","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":true,"sents":[{"es":"-¡Buenos días!","zh":"“你好，”小王子说。","t":[100,1950]},{"es":"-dijo el principito.","zh":"“你好，”商贩回答。","t":[1950,4025]},{"es":"-¡Buenos días!","zh":"这是个贩卖高效止渴药丸的商贩。","t":[4025,5875]},{"es":"-respondió el comerciante.","zh":"这是个贩卖高效止渴药丸的商贩。","t":[5875,7287]}]},{"id":"ch23p01","audio":true,"sents":[{"es":"Era un comerciante de píldoras perfeccionadas que quitan la sed.","zh":"吞下一粒这样的药丸，整整一周都不用喝水。","t":[100,4200]},{"es":"Se toma una por semana y ya no se sienten ganas de beber.","zh":"“你为什么要卖这个？”","t":[4200,8112]},{"es":"-¿Por qué vendes eso?","zh":"小王子问。","t":[8112,10138]},{"es":"-preguntó el principito.","zh":"小王子问。","t":[10138,11337]}]},{"id":"ch23p02","audio":true,"sents":[{"es":"-Porque con esto se economiza mucho tiempo.","zh":"“因为它们能大大节省时间，”商贩回答。","t":[100,3275]},{"es":"Según el cálculo hecho por los expertos, se ahorran cincuenta y tres minutos por semana.","zh":"“专家们算过——每周能省下五十三分钟。”","t":[3275,8850]},{"es":"-¿Y qué se hace con esos cincuenta y tres minutos?","zh":"“那这省下的五十三分钟，用来做什么呢？”","t":[8850,11250]}]},{"id":"ch23p03","audio":true,"sents":[{"es":"-Lo que cada uno quiere…","zh":"“那这省下的五十三分钟，用来做什么呢？”","t":[100,1313]},{"es":"\"","zh":"“想做什么就做什么。”","t":[1313,1813]}]},{"id":"ch23p04","audio":true,"sents":[{"es":"\"Si yo dispusiera de cincuenta y tres minutos -pensó el principito- caminaría suavemente hacia una fuente…\"","zh":"“要是我能多出这五十三分钟，”小王子心想，“我就慢慢散步到泉水边去……”","t":[100,5637]}]}]},{"id":"ch24","title_es":"Capítulo 24","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":true,"sents":[{"es":"Era el octavo día de mi avería en el desierto y había escuchado la historia del comerciante bebiendo la última gota de mi provisión de agua.","zh":"从我飞机在沙漠失事到现在，已经过了八天。","t":[100,7900]},{"es":"-¡Ah -le dije al principito-, son muy bonitos tus cuentos, pero yo no he reparado mi avión, no tengo nada para beber y sería muy feliz si pudiera irme muy tranquilo en busca de una fuente!","zh":"听着商贩的故事，我喝光了存水里的最后一滴。","t":[7900,17250]}]},{"id":"ch24p01","audio":true,"sents":[{"es":"-Mi amigo el zorro…, me dijo…","zh":"“我的朋友狐狸曾经对我说过……”","t":[100,1675]}]},{"id":"ch24p02","audio":true,"sents":[{"es":"-No se trata ahora del zorro, muchachito…","zh":"“我的小朋友，现在说的可不是狐狸！”","t":[100,2475]},{"es":"-¿Por qué?","zh":"“因为我会渴死的。”","t":[2475,2812]}]},{"id":"ch24p03","audio":true,"sents":[{"es":"-Porque nos vamos a morir de sed…","zh":"他好像没听懂我的话，因为他说：“哪怕要死，有个朋友也是好的。”","t":[100,1663]}]},{"id":"ch24p04","audio":true,"sents":[{"es":"No comprendió mi razonamiento y replicó:","zh":"比方说，我很高兴曾经有过狐狸这个朋友。","t":[100,2337]}]},{"id":"ch24p05","audio":true,"sents":[{"es":"-Es bueno haber tenido un amigo, aún si vamos a morir.","zh":"“因为他从没尝过饥饿，也没尝过干渴。”","t":[100,4062]},{"es":"Yo estoy muy contento de haber tenido un amigo zorro.","zh":"“对他来说，只要有阳光就够了……”","t":[4062,6850]}]},{"id":"ch24p06","audio":true,"sents":[{"es":"\"Es incapaz de medir el peligro -me dije - Nunca tiene hambre ni sed y un poco de sol le basta…\"","zh":"“我也想喝水……”","t":[100,5000]}]},{"id":"ch24p07","audio":true,"sents":[{"es":"El principito me miró y respondió a mi pensamiento:","zh":"我们去找井吧。","t":[100,2788]}]},{"id":"ch24p08","audio":true,"sents":[{"es":"-Tengo sed también…","zh":"我绝望地摆了摆手——在茫茫沙漠里瞎找水井，毫无意义。","t":[100,1300]},{"es":"vamos a buscar un pozo…","zh":"我们默默地走了好几个小时。","t":[1300,2588]}]},{"id":"ch24p09","audio":true,"sents":[{"es":"Tuve un gesto de cansancio; es absurdo buscar un pozo, al azar, en la inmensidad del desierto.","zh":"夜幕降临，天空中开始亮起星星。","t":[100,6100]},{"es":"Sin embargo, nos pusimos en marcha.","zh":"干渴让我有些发热。","t":[6100,7987]}]},{"id":"ch24p10","audio":true,"sents":[{"es":"Después de dos horas de caminar en silencio, cayó la noche y las estrellas comenzaron a brillar.","zh":"小王子的话在我脑海里翻腾。","t":[100,5875]},{"es":"Yo las veía como en sueño, pues a causa de la sed tenía un poco de fiebre.","zh":"“你是说，你也感到口渴了？”","t":[5875,10550]},{"es":"Las palabras del principito danzaban en mi mente.","zh":"他没有正面回答，只是说：“水对心灵也是好的。”","t":[10550,14038]},{"es":"-¿Tienes sed, tú también?","zh":"我没明白他的意思，但没再追问。","t":[14038,16275]},{"es":"-le pregunté.","zh":"他看起来累了。","t":[16275,18038]},{"es":"Pero no respondió a mi pregunta, diciéndome simplemente:","zh":"小王子坐到沙地上，我也挨着他坐下。","t":[18038,21175]}]},{"id":"ch24p11","audio":true,"sents":[{"es":"-El agua puede ser buena también para el corazón…","zh":"沉默片刻，他说：“星星真美；因为某处有一朵花，虽然从这里看不见它。”","t":[100,2412]}]},{"id":"ch24p12","audio":true,"sents":[{"es":"No comprendí sus palabras, pero me callé; sabía muy bien que no había que interrogarlo.","zh":"“沙漠真美，”他又说。","t":[100,4687]}]},{"id":"ch24p13","audio":true,"sents":[{"es":"El principito estaba cansado y se sentó; yo me senté a su lado y después de un silencio me dijo:","zh":"这话说得对。","t":[100,5075]}]},{"id":"ch24p14","audio":true,"sents":[{"es":"-Las estrellas son hermosas, por una flor que no se ve…","zh":"我一直喜欢沙漠。","t":[100,2975]}]},{"id":"ch24p15","audio":true,"sents":[{"es":"Respondí \"seguramente\" y miré sin hablar los pliegues que la arena formaba bajo la luna.","zh":"一片寂静。","t":[100,4512]}]},{"id":"ch24p16","audio":true,"sents":[{"es":"-El desierto es bello -añadió el principito.","zh":"没有任何动静。","t":[100,2575]}]},{"id":"ch24p17","audio":true,"sents":[{"es":"Era verdad; siempre me ha gustado el desierto.","zh":"“沙漠之所以美，”小王子说，“还因为它在某处藏着一口井。”","t":[100,3575]},{"es":"Puede uno sentarse en una duna, nada se ve, nada se oye y sin embargo, algo resplandece en el silencio…","zh":"我吃了一惊，忽然明白了沙地那神秘的闪烁意味着什么。","t":[3575,9450]}]},{"id":"ch24p18","audio":true,"sents":[{"es":"-Lo que más embellece al desierto -dijo el principito- es el pozo que oculta en algún sitio…","zh":"我小的时候，住在一栋老房子里。","t":[100,5012]}]},{"id":"ch24p19","audio":true,"sents":[{"es":"Me quedé sorprendido al comprender súbitamente ese misterioso resplandor de la arena.","zh":"当然，谁也没找到它。","t":[100,5500]},{"es":"Cuando yo era niño vivía en una casa antigua en la que, según la leyenda, había un tesoro escondido.","zh":"也许，根本没人去找过。","t":[5500,11525]},{"es":"Sin duda que nadie supo jamás descubrirlo y quizás nadie lo buscó, pero parecía toda encantada por ese tesoro.","zh":"房子仿佛把秘密藏在心底……","t":[11525,18488]},{"es":"Mi casa ocultaba un secreto en el fondo de su corazón…","zh":"“没错，”我对小王子说，“无论是房子、星星，还是沙漠。’","t":[18488,21350]}]},{"id":"ch24p20","audio":true,"sents":[{"es":"-Sí -le dije al principito- ya se trate de la casa, de las estrellas o del desierto, lo que les embellece es invisible.","zh":"让它们变得美丽的东西，是肉眼看不见的。”","t":[100,6576]}]},{"id":"ch24p21","audio":true,"sents":[{"es":"-Me gusta -dijo el principito- que estés de acuerdo con mi zorro.","zh":"小王子打起了瞌睡。","t":[100,3162]}]},{"id":"ch24p22","audio":true,"sents":[{"es":"Como el principito se dormía, lo tomé en mis brazos y me puse nuevamente en camino.","zh":"我把他抱在怀里，重新上路。","t":[100,5475]},{"es":"Me sentía emocionado llevando aquel frágil tesoro, y me parecía que nada más frágil había sobre la Tierra.","zh":"我觉得手里抱着一件脆弱的珍宝。","t":[5475,11962]},{"es":"Miraba a la luz de la luna aquella frente pálida, aquellos ojos cerrados, los cabellos agitados por el viento y me decía: \"lo que veo es sólo la corteza; lo más importante es invisible…","zh":"而且我觉得，整个地球上再没有比这更脆弱的东西。","t":[11962,22212]},{"es":"\"","zh":"借著月光，我望着他苍白的额头、闭着的眼睛、被风吹动的发丝，对自己说：我看到的只是外表。","t":[22212,22712]}]},{"id":"ch24p23","audio":true,"sents":[{"es":"Como sus labios entreabiertos esbozaron una sonrisa, me dije: \"Lo que más me emociona de este principito dormido es su fidelidad a una flor, es la imagen de la rosa que resplandece en él como la llama de una lámpara, incluso cuando duerme…","zh":"他半张的嘴唇泛起一丝几乎察觉不到的微笑，我想：“这位睡着的王子让我如此感动，是因为他对自己的花忠贞不渝。”","t":[100,13400]},{"es":"\" Y lo sentí más frágil aún.","zh":"玫瑰的形象在他心中闪烁，如同烛火，即便在他睡着时也是如此。","t":[13400,15875]},{"es":"Pensaba que a las lámparas hay que protegerlas: una racha de viento puede apagarlas…","zh":"这样的火苗必须小心守护，因为一阵风就能把它吹灭。","t":[15875,20362]}]},{"id":"ch24p24","audio":true,"sents":[{"es":"Continué caminando y al rayar el alba descubrí el pozo.","zh":"我走啊走，终于在黎明时看见了那口井。","t":[100,2975]}]}]},{"id":"ch25","title_es":"Capítulo 25","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":true,"sents":[{"es":"-Los hombres -dijo el principito- se meten en los rápidos pero no saben dónde van ni lo que quieren…","zh":"“人们，”小王子说，“他们钻进快车，却不知道自己要奔向何方。”","t":[100,5975]},{"es":"Entonces se agitan y dan vueltas…","zh":"所以他们白白折腾，兜着圈子跑。","t":[5975,7850]}]},{"id":"ch25p01","audio":true,"sents":[{"es":"Y añadió: -¡No vale la pena!…","zh":"接着他又说：“这毫无意义……”","t":[100,1588]}]},{"id":"ch25p02","audio":true,"sents":[{"es":"El pozo que habíamos encontrado no se parecía en nada a los pozos saharianos.","zh":"我们抵达的这口井，非同寻常。","t":[100,5088]},{"es":"Estos pozos son simples agujeros que se abren en la arena.","zh":"因为撒哈拉的井，不过是在沙里挖出的简单坑洞。","t":[5088,9188]},{"es":"El que teníamos ante nosotros parecía el pozo de un pueblo; pero por allí no había ningún pueblo y me parecía estar soñando.","zh":"而这口却像个乡村的井，尽管附近并无村落。","t":[9188,15388]}]},{"id":"ch25p03","audio":true,"sents":[{"es":"-¡Es extraño!","zh":"我简直以为自己在做梦。","t":[100,1862]},{"es":"-le dije al principito-.","zh":"“真怪，”我对小王子说，“这儿什么都是现成的：辘轳、水桶和绳子……”","t":[1862,4062]},{"es":"Todo está a punto: la roldana, el balde y la cuerda…","zh":"他笑着回答，拉了拉绳子，辘轳便转了起来。","t":[4062,7062]}]},{"id":"ch25p04","audio":true,"sents":[{"es":"Se rió y tocó la cuerda; hizo mover la roldana.","zh":"辘轳随之发出呻吟，像那为早已沉睡的风而鸣的旧风标。","t":[100,3800]},{"es":"Y la roldana gimió como una vieja veleta cuando el viento ha dormido mucho.","zh":"“你听见了吗，”小王子说，“我们把这口井唤醒了，它唱起歌来。”","t":[3800,8425]},{"es":"-¿Oyes?","zh":"我不想让他太费力。","t":[8425,9888]},{"es":"-dijo el principito-.","zh":"“让我来吧，”我对他说，“这活儿你干不动。”","t":[9888,11962]},{"es":"Hemos despertado al pozo y canta.","zh":"我慢慢提起水桶，重重地把它放在井沿上。","t":[11962,13800]}]},{"id":"ch25p05","audio":true,"sents":[{"es":"No quería que el principito hiciera el menor esfuerzo y le dije:","zh":"我耳中仍回响着辘轳的歌声，而颤动的波光上，跃动着太阳的倒影。","t":[100,3163]}]},{"id":"ch25p06","audio":true,"sents":[{"es":"-Déjame a mí, es demasiado pesado para ti.","zh":"“让我喝这水吧，”小王子说，“给我喝吧。”","t":[100,2500]}]},{"id":"ch25p07","audio":true,"sents":[{"es":"Lentamente subí el cubo hasta el brocal donde lo dejé bien seguro.","zh":"于是我明白了他要找的是什么。","t":[100,3475]}]},{"id":"ch25p08","audio":true,"sents":[{"es":"En mis oídos sonaba aún el canto de la roldana y veía temblar al sol en el agua agitada.","zh":"我把水桶举到他唇边。","t":[100,4775]}]},{"id":"ch25p09","audio":true,"sents":[{"es":"-Tengo sed de esta agua -dijo el principito-, dame de beber…","zh":"他闭着眼睛喝水。","t":[100,4288]},{"es":"¡Comprendí entonces lo que él había buscado!","zh":"这水对他而言是一场盛宴。","t":[4288,6563]}]},{"id":"ch25p10","audio":true,"sents":[{"es":"Levanté el balde hasta sus labios y el principito bebió con los ojos cerrados.","zh":"它全然不同，不是供日常解渴之水。","t":[100,5038]},{"es":"Todo era bello como una fiesta.","zh":"这水诞生于星空之下，诞生于辘轳的歌声之中，诞生于我双手的努力。","t":[5038,6750]}]},{"id":"ch25p11","audio":true,"sents":[{"es":"Aquella agua era algo más que un alimento.","zh":"它对心灵如此甘美，宛如礼物。","t":[100,3362]},{"es":"Había nacido del caminar bajo las estrellas, del canto de la roldana, del esfuerzo de mis brazos.","zh":"当我还是个小男孩时，圣诞树的光芒、晚祷的教堂乐曲、四周洋溢的温柔笑容，也曾是我收到的璀璨节日礼物。","t":[3362,9462]},{"es":"Era como un regalo para el corazón.","zh":"“你们这里的人，”小王子说，“在一个园子里种出五千朵玫瑰，却找不到自己所求……”","t":[9462,12312]},{"es":"Cuando yo era niño, las luces del árbol de Navidad, la música de la misa de medianoche, la dulzura de las sonrisas, daban su resplandor a mi regalo de Navidad.","zh":"“是找不到，”我确认说……","t":[12312,21137]}]},{"id":"ch25p12","audio":true,"sents":[{"es":"-Los hombres de tu tierra -dijo el principito- cultivan cinco mil rosas en un jardín y no encuentran lo que buscan.","zh":"“可他们寻找的一切，都能在一朵玫瑰和几口水中找到。”","t":[100,6125]}]},{"id":"ch25p13","audio":true,"sents":[{"es":"-No lo encuentran nunca -le respondí.","zh":"“当然，”我同意。","t":[100,3088]},{"es":"-Y sin embargo, lo que buscan podrían encontrarlo en una sola rosa o en un poco de agua…","zh":"小王子又道：“他们的眼睛是盲的。”","t":[3088,7450]}]},{"id":"ch25p14","audio":true,"sents":[{"es":"-Sin duda, respondí.","zh":"必须用心灵去寻找。","t":[100,2400]},{"es":"Y el principito añadió:","zh":"我畅饮了个够。","t":[2400,3688]}]},{"id":"ch25p15","audio":true,"sents":[{"es":"-Pero los ojos son ciegos.","zh":"黎明时分，呼吸格外舒畅。","t":[100,2500]},{"es":"Hay que buscar con el corazón.","zh":"沙子泛着蜜糖般的色泽。","t":[2500,4050]}]},{"id":"ch25p16","audio":true,"sents":[{"es":"Yo había bebido y me encontraba bien.","zh":"那色调让我欢喜。","t":[100,2988]},{"es":"La arena, al alba, era color de miel, del que gozaba hasta sentirme dichoso.","zh":"我再没有什么可担忧和悲伤的了。","t":[2988,8012]},{"es":"¿Por qué había de sentirme triste?","zh":"“你一定会信守承诺吧？”","t":[8012,9737]}]},{"id":"ch25p17","audio":true,"sents":[{"es":"-Es necesario que cumplas tu promesa -dijo dulcemente el principito que nuevamente se había sentado junto a mi.","zh":"小王子挨着我坐下，问道。","t":[100,6712]},{"es":"-¿Qué promesa?","zh":"“什么承诺？”","t":[6712,7362]}]},{"id":"ch25p18","audio":true,"sents":[{"es":"-Ya sabes…","zh":"我对我的花是负有责任的。","t":[100,788]},{"es":"el bozal para mi cordero…","zh":"我从口袋里掏出草图。","t":[788,2350]},{"es":"soy responsable de mi flor.","zh":"小王子看了看，笑了起来。","t":[2350,3800]}]},{"id":"ch25p19","audio":true,"sents":[{"es":"Saqué del bolsillo mis esbozos de dibujo.","zh":"“你的猴面包树，画得像棵花椰菜……”","t":[100,3288]},{"es":"El principito los miró y dijo riendo:","zh":"“竟是这样？”","t":[3288,5374]}]},{"id":"ch25p20","audio":true,"sents":[{"es":"-Tus baobabs parecen repollos…","zh":"而我原本对自己的猴面包树是那么得意……","t":[100,2038]},{"es":"-¡Oh!","zh":"“你的狐狸……它的耳朵……有点像鹿角——太长了。”","t":[2038,3100]},{"es":"¡Y yo que estaba tan orgulloso de mis baobabs!","zh":"他又笑了起来。","t":[3100,5362]}]},{"id":"ch25p21","audio":true,"sents":[{"es":"-Tu zorro tíene orejas que parecen cuernos; son demasiado largas.","zh":"“你对我不公平，我的小朋友。”","t":[100,3775]}]},{"id":"ch25p22","audio":true,"sents":[{"es":"Y volvió a reír.","zh":"除了蟒蛇——从外面和里面——我本来什么都不会画。","t":[100,1075]}]},{"id":"ch25p23","audio":true,"sents":[{"es":"-Eres injusto, muchachito; yo no sabía dibujar más que boas cerradas y boas abiertas.","zh":"“啊……”","t":[100,6062]},{"es":"-¡Oh, todo se arreglará!","zh":"“那也凑合。”","t":[6062,8312]},{"es":"-dijo el principito-.","zh":"“孩子们会懂的，”小王子回答。","t":[8312,10388]},{"es":"Los niños entienden.","zh":"我拿起铅笔，画了个嘴套。","t":[10388,11650]}]},{"id":"ch25p24","audio":true,"sents":[{"es":"Bosquejé, pues, un bozal y se lo alargué con el corazón oprimido:","zh":"可当我将画递给他时，我的心猛地一颤：“你打算做什么？”","t":[100,3474]}]},{"id":"ch25p25","audio":true,"sents":[{"es":"-Tú tienes proyectos que yo ignoro…","zh":"你没跟我说过……”","t":[100,1962]}]},{"id":"ch25p26","audio":true,"sents":[{"es":"Pero no me respondió.","zh":"小王子对此没有作答。","t":[100,2188]},{"es":"-¿Sabes?","zh":"他只说：“你知道的……到明天，我降临地球正好满一年……”","t":[2188,3738]},{"es":"-me dijo-.","zh":"他沉默了，接着又说：“这事就发生在离这儿不远的地方。”","t":[3738,5262]},{"es":"Mañana hace un año de mi caída en la Tierra…","zh":"说着，他脸红了。","t":[5262,7612]}]},{"id":"ch25p27","audio":true,"sents":[{"es":"Y después de un silencio, añadió:","zh":"我的心揪了一下，虽然我不明白为什么。","t":[100,2050]}]},{"id":"ch25p28","audio":true,"sents":[{"es":"-Caí muy cerca de aquí…","zh":"我脑中浮起一个问题：“这么说，八天前的那个早晨，我第一次见到你时，你出现在这里并非偶然？”","t":[100,1313]}]},{"id":"ch25p29","audio":true,"sents":[{"es":"El principito se sonrojó y nuevamente, sin comprender por qué, experimenté una extraña tristeza.","zh":"孤零零一个人，离人烟有千里之遥！”","t":[100,5012]}]},{"id":"ch25p30","audio":true,"sents":[{"es":"Sin embargo, se me ocurrió preguntar:","zh":"你是回自己坠落的地方去？”","t":[100,2063]}]},{"id":"ch25p31","audio":true,"sents":[{"es":"-Entonces no te encontré por azar hace ocho días, cuando paseabas por estos lugares, a mil millas de distancia del lugar habitado más próximo.","zh":"小王子又脸红了。","t":[100,8588]},{"es":"¿Es que volvías al punto de tu caída?","zh":"我迟疑地又补了一句：“跟这周年纪念有关？”","t":[8588,10500]}]},{"id":"ch25p32","audio":true,"sents":[{"es":"El principito enrojeció nuevamente.","zh":"小王子再次脸红。","t":[100,2025]}]},{"id":"ch25p33","audio":true,"sents":[{"es":"Y añadí vacilante.","zh":"他从不直接回答问题，可脸红，不就意味著“是”吗？","t":[100,2162]},{"es":"-¿Quizás por el aniversario?","zh":"“是这样？”","t":[2162,3563]}]},{"id":"ch25p34","audio":true,"sents":[{"es":"El principito se ruborizó una vez más.","zh":"我对他说。","t":[100,3250]},{"es":"Aunque nunca respondía a las preguntas, su rubor signifícaba una respuesta afirmativa.","zh":"“我怕……”","t":[3250,8962]},{"es":"-¡Ah!","zh":"但他打断我：“你该去干活了。”","t":[8962,10225]},{"es":"-le dije- tengo miedo.","zh":"回到你的飞机那儿去。","t":[10225,11476]}]},{"id":"ch25p35","audio":true,"sents":[{"es":"Pero él me respondió:","zh":"我在这儿等你。","t":[100,1137]}]},{"id":"ch25p36","audio":true,"sents":[{"es":"-Tú debes trabajar ahora; vuelve, pues, junto a tu máquina, que yo te espero aquí.","zh":"明天傍晚回来……”","t":[100,5762]},{"es":"Vuelve mañana por la tarde.","zh":"听了这话，我反而更不安了。","t":[5762,7188]}]},{"id":"ch25p37","audio":true,"sents":[{"es":"Pero yo no estaba tranquilo y me acordaba del zorro.","zh":"我想起了狐狸。","t":[100,3638]},{"es":"Si se deja uno domesticar, se expone a llorar un poco…","zh":"一旦让自己被驯养，就有落泪的风险……","t":[3638,6813]}]}]},{"id":"ch26","title_es":"Capítulo 26","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":true,"sents":[{"es":"A1 lado del pozo había una ruina de un viejo muro de piedras.","zh":"井旁有一道旧石墙的残垣。","t":[100,3524]}]},{"id":"ch26p01","audio":true,"sents":[{"es":"Cuando volví de mi trabajo al día siguiente por la tarde, vi desde lejos al principito sentado en lo alto con las piernas colgando.","zh":"第二天傍晚，我干完活回来，老远就看见小王子坐在墙上，双腿垂着。","t":[100,7512]},{"es":"Lo oí que hablaba.","zh":"我听见他对谁说：“难道你把这事忘了吗？”","t":[7512,8488]}]},{"id":"ch26p02","audio":true,"sents":[{"es":"-¿No te acuerdas?","zh":"那不在这里……”","t":[100,2012]},{"es":"¡No es aquí con exactitud!","zh":"毫无疑问，有人答了他，因为他反驳道：“不，才不是！”","t":[2012,3462]}]},{"id":"ch26p03","audio":true,"sents":[{"es":"Alguien le respondió sín duda, porque él replicó: -¡Sí, sí; es el día, pero no es este el lugar!","zh":"是整整一年前，但不是在这儿。”","t":[100,5487]}]},{"id":"ch26p04","audio":true,"sents":[{"es":"Proseguí mi marcha hacia el muro, pero no veía ni oía a nadie.","zh":"我走近墙边，却依旧谁也没看见，也没听见。","t":[100,4550]},{"es":"Y sin embargo, el principito replicó de nuevo.","zh":"可小王子又答道：“哦，当然。","t":[4550,7812]},{"es":"-¡Claro!","zh":"你会在沙上看见我的脚印。","t":[7812,9175]},{"es":"Ya verás dónde comienza mi huella en la arena.","zh":"你只需等我就好。","t":[9175,12400]},{"es":"No tienes más que esperarme, que allí estaré yo esta noche.","zh":"今夜我会来的……”","t":[12400,15562]},{"es":"¿","zh":"当时我离墙只有二十米，却依旧什么人也看不见。","t":[15562,16538]},{"es":"Yo estaba a veinte metros y continuaba sin distinguir nada.","zh":"小王子沉默片刻，问道：“你的毒，厉害吗？”","t":[16538,19663]}]},{"id":"ch26p05","audio":true,"sents":[{"es":"El principito, después de un silencio, dijo aún:","zh":"你能保证我不会受太久的苦吗？”","t":[100,2776]}]},{"id":"ch26p06","audio":true,"sents":[{"es":"Tienes un buen veneno?","zh":"我停住脚步，心猛地一紧，却仍没完全明白。","t":[100,2188]},{"es":"¿Estás segura de no hacerme sufrir mucho?","zh":"“现在你走开吧，”小王子说，“我想下去了。”","t":[2188,4363]}]},{"id":"ch26p07","audio":true,"sents":[{"es":"Me detuve con el corazón oprimido, siempre sin comprender.","zh":"我垂眼望向墙根，随即惊得退开一步。","t":[100,4288]},{"es":"-¡Ahora vete -dijo el principito-, quiero volver a bajarme!","zh":"墙根下，一条黄色的蛇正朝小王子游来。","t":[4288,7087]}]},{"id":"ch26p08","audio":true,"sents":[{"es":"Dirigí la mirada hacia el pie del muro e instintivamente di un brinco.","zh":"这种蛇半分钟就能要人命。","t":[100,4612]},{"es":"Una serpiente de esas amarillas que matan a una persona en menos de treínta segundos, se erguía en dirección al principito.","zh":"我摸索着口袋里的左轮手枪，我向前探身，但听到声响，蛇便顺着沙地轻轻滑走，发出轻微的金属声，像一缕即将干涸的水流般消失在石块间。","t":[4612,11825]},{"es":"Echando mano al bolsillo para sacar mi revólver, apreté el paso, pero, al ruido que hice, la serpiente se dejó deslizar suavemente por la arena como un surtidor que muere, y, sin apresurarse demasiado, se escurrió entre las piedras con un lígero ruido metálico.","zh":"我刚好跑到墙边，及时把我的小王子接进怀里。","t":[11825,26074]}]},{"id":"ch26p09","audio":true,"sents":[{"es":"Llegué junto al muro a tiempo de recibir en mis brazos a mi principito, que estaba blanco como la nieve.","zh":"他苍白如雪。","t":[100,6288]},{"es":"-¿Pero qué historia es ésta?","zh":"“你到底在打什么主意？！”","t":[6288,8638]},{"es":"¿De charla también con las serpientes?","zh":"你为什么要跟蛇说话？”","t":[8638,10563]}]},{"id":"ch26p10","audio":true,"sents":[{"es":"Le quité su eterna bufanda de oro, le humedecí las sienes y le di de beber, sin atreverme a hacerle pregunta alguna.","zh":"我解开他那条从不离身的金色围巾。","t":[100,7212]},{"es":"Me miró gravemente rodeándome el cuello con sus brazos.","zh":"我润湿他的太阳穴，又喂他喝水。","t":[7212,11250]},{"es":"Sentí latir su corazón, como el de un pajarillo que muere a tiros de carabina.","zh":"我不敢问他什么。","t":[11250,15300]}]},{"id":"ch26p11","audio":true,"sents":[{"es":"-Me alegra -dijo el principito- que hayas encontrado lo que faltaba a tu máquina.","zh":"他认真地望着我，用双臂搂住我的脖子。","t":[100,5250]},{"es":"Así podrás volver a tu tierra…","zh":"我感觉到他的心在跳动，","t":[5250,7250]},{"es":"-¿Cómo lo sabes?","zh":"像一只被枪击中的垂死鸟儿的心。","t":[7250,8063]}]},{"id":"ch26p12","audio":true,"sents":[{"es":"Precisamente venía a comunicarle que, a pesar de que no lo esperaba, había logrado terminar mi trabajo.","zh":"他对我说：“我很高兴，你把飞机修好了。”","t":[100,5537]}]},{"id":"ch26p13","audio":true,"sents":[{"es":"No respondió a mi pregunta, sino que añadió:","zh":"现在你能回家了。”","t":[100,2400]}]},{"id":"ch26p14","audio":true,"sents":[{"es":"-También yo vuelvo hoy a mi planeta…","zh":"“你怎么知道？”","t":[100,1862]}]},{"id":"ch26p15","audio":true,"sents":[{"es":"Luego, con melancolía:","zh":"我正想告诉他，我终究还是成功完成了工作。","t":[100,1400]}]},{"id":"ch26p16","audio":true,"sents":[{"es":"-Es mucho más lejos…","zh":"他没回答我的问题，只说：“今天我也要回自己的家了……”","t":[100,1400]},{"es":"y más difícil…","zh":"接着又悲伤地补了一句：“但那要远得多，也难得多……”","t":[1400,2200]}]},{"id":"ch26p17","audio":true,"sents":[{"es":"Me daba cuenta de que algo extraordinario pasaba en aquellos momentos.","zh":"我感到有什么不寻常的事正在发生。","t":[100,4662]},{"es":"Estreché al principito entre mis brazos como sí fuera un niño pequeño, y no obstante, me pareció que descendía en picada hacia un abismo sin que fuera posible hacer nada para retenerlo.","zh":"他的目光严肃，却又透着几分怅惘。","t":[4662,13862]}]},{"id":"ch26p18","audio":true,"sents":[{"es":"Su mirada, seria, estaba perdída en la lejanía.","zh":"我有着你的小羊。","t":[100,2725]}]},{"id":"ch26p19","audio":true,"sents":[{"es":"Tengo tu cordero y la caja para el cordero.","zh":"也有着给它的箱子。","t":[100,3088]},{"es":"Y tengo tambíén el bozal.","zh":"还有嘴套……”","t":[3088,4550]}]},{"id":"ch26p20","audio":true,"sents":[{"es":"Y sonreía melancólicamente.","zh":"说到这里，他凄然一笑。","t":[100,1850]}]},{"id":"ch26p21","audio":true,"sents":[{"es":"Esperé un buen rato.","zh":"我等了很久，感到他渐渐缓了过来。","t":[100,2325]},{"es":"Sentía que volvía a entrar en calor poco a poco:","zh":"“小王子，你害怕……”","t":[2325,4900]}]},{"id":"ch26p22","audio":true,"sents":[{"es":"-Has tenido miedo, muchachito…","zh":"他当然害怕。","t":[100,1775]}]},{"id":"ch26p23","audio":true,"sents":[{"es":"Lo había tenido, sin duda, pero sonrió con dulzura:","zh":"“今天夜里，我会怕得更厉害……”","t":[100,2862]}]},{"id":"ch26p24","audio":true,"sents":[{"es":"-Esta noche voy a tener más miedo…","zh":"想到那逼近的、无可挽回的灾祸，我再次感到一阵寒意。","t":[100,1937]}]},{"id":"ch26p25","audio":true,"sents":[{"es":"Me quedé de nuevo helado por un sentimiento de algo irreparable.","zh":"我明白了——想到再也听不见他的笑声，我无法忍受。","t":[100,4300]},{"es":"Comprendí que no podía soportar la idea de no volver a oír nunca más su risa.","zh":"因为对我来说，他犹如沙漠中的清泉。","t":[4300,9212]},{"es":"Era para mí como una fuente en el desierto.","zh":"“小王子，我想一直听见你的笑声……”","t":[9212,11387]}]},{"id":"ch26p26","audio":true,"sents":[{"es":"-Muchachito, quiero oír otra vez tu risa…","zh":"他回答我：“今夜，我的星星会正好在我一年前坠落之地的正上方……”","t":[100,2438]}]},{"id":"ch26p27","audio":true,"sents":[{"es":"Pero él me dijo:","zh":"“小王子，求你告诉我，这整桩蛇的事、与星星相会的事，不过是一场噩梦吧？”","t":[100,850]}]},{"id":"ch26p28","audio":true,"sents":[{"es":"-Esta noche hará un año.","zh":"他没回答我的问题，只说：“重要的东西，是肉眼看不见的……”","t":[100,2438]},{"es":"Mi estrella se encontrará precisamente encima del lugar donde caí el año pasado…","zh":"“哦，当然……”","t":[2438,6775]}]},{"id":"ch26p29","audio":true,"sents":[{"es":"-¿No es cierto -le interrumpí- que toda esta historia de serpientes, de citas y de estrellas es tan sólo una pesadilla?","zh":"“这就和那朵花一样。","t":[100,6575]}]},{"id":"ch26p30","audio":true,"sents":[{"es":"Pero el principito no respondió a mi pregunta y dijo:","zh":"如果你爱一朵生长远星上的花，夜里望天便是件美事。","t":[100,2700]}]},{"id":"ch26p31","audio":true,"sents":[{"es":"-Lo más importante nunca se ve…","zh":"所有的星星都会绽放……”","t":[100,1700]}]},{"id":"ch26p32","audio":true,"sents":[{"es":"-Indudablemente…","zh":"“哦，当然……”","t":[100,1062]}]},{"id":"ch26p33","audio":true,"sents":[{"es":"-Es lo mismo que la flor.","zh":"“这也和水一样。","t":[100,2300]},{"es":"Si te gusta una flor que habita en una estrella, es muy dulce mirar al cielo por la noche.","zh":"你给我的那水，宛如音乐……","t":[2300,6938]}]},{"id":"ch26p34","audio":true,"sents":[{"es":"Todas las estrellas han florecido.","zh":"辘轳和绳子……”","t":[100,1900]}]},{"id":"ch26p35","audio":true,"sents":[{"es":"-Es indudable…","zh":"你还记得吗？……”","t":[100,962]}]},{"id":"ch26p36","audio":true,"sents":[{"es":"-Es como el agua.","zh":"那水真美。","t":[100,2012]},{"es":"La que me diste a beber, gracias a la roldana y la cuerda, era como una música ¿te acuerdas?","zh":"“当然……”","t":[2012,7962]},{"es":"¡Qué buena era!","zh":"“夜里，你会望着星星。","t":[7962,8700]}]},{"id":"ch26p37","audio":true,"sents":[{"es":"-Sí, cierto…","zh":"我的家太小，没法指给你看我的星星在哪儿。","t":[100,963]}]},{"id":"ch26p38","audio":true,"sents":[{"es":"-Por la noche mirarás las estrellas; mi casa es demasiado pequeña para que yo pueda señalarte dónde se encuentra.","zh":"但这样反而更好。","t":[100,6688]},{"es":"Así es mejor; mi estrella será para ti una cualquiera de ellas.","zh":"我的那颗，对你而言只是其中一颗，而你会欣赏所有的星星。","t":[6688,11338]},{"es":"Te gustará entonces mirar todas las estrellas.","zh":"它们全都会成为你的朋友。","t":[11338,14850]},{"es":"Todas ellas serán tus amigas.","zh":"而且，我会送你一件礼物……”","t":[14850,17538]},{"es":"Y además, te haré un regalo…","zh":"小王子又笑了起来。","t":[17538,19050]}]},{"id":"ch26p39","audio":true,"sents":[{"es":"Y rió una vez más.","zh":"“啊，小王子，小王子！”","t":[100,2238]},{"es":"-¡Ah, muchachito, muchachito, cómo me gusta oír tu risa!","zh":"我喜欢听你的笑声。”","t":[2238,5276]}]},{"id":"ch26p40","audio":true,"sents":[{"es":"-Mi regalo será ése precisamente, será como el agua…","zh":"“这就是我的礼物……和水一样……”","t":[100,3112]},{"es":"-¿Qué quieres decir?","zh":"“你这话是什么意思？”","t":[3112,4038]}]},{"id":"ch26p41","audio":true,"sents":[{"es":"La gente tiene estrellas que no son las mismas.","zh":"“每个人都有属于自己的星星。","t":[100,3575]},{"es":"Para los que viajan, las estrellas son guías; para otros sólo son pequeñas lucecítas.","zh":"对旅人来说，它们是引路的明灯。","t":[3575,9188]},{"es":"Para los sabios las estrellas son problemas.","zh":"对旁人来说，它们只是小小的光点。","t":[9188,12400]},{"es":"Para mi hombre de negocios, eran oro.","zh":"对学者来说，它们是谜题。","t":[12400,15338]},{"es":"Pero todas esas estrellas se callan.","zh":"对我的那位商人来说，它们是金子做的。","t":[15338,18262]},{"es":"Tú tendrás estrellas como nadie ha tenido…","zh":"但所有的星星都沉默不语。","t":[18262,20662]},{"es":"-¿Qué quieres decir?","zh":"而你，会拥有别人都不曾拥有的星星。","t":[20662,22525]},{"es":"-Cuando por las noches mires al cielo, al pensar que en una de aquellas estrellas estoy yo riendo, será para ti como si todas las estrellas riesen.","zh":"“你这话是什么意思？”","t":[22525,31012]},{"es":"¡Tú sólo tendrás estrellas que saben reír!","zh":"“夜里你会望天，而我将住在其中一颗星上，在其中一颗上欢笑，于是你会觉得，所有的星星都在为你而笑。”","t":[31012,33262]}]},{"id":"ch26p42","audio":true,"sents":[{"es":"Y rió nuevamente.","zh":"你会拥有会笑的星星！”","t":[100,1150]}]},{"id":"ch26p43","audio":true,"sents":[{"es":"-Cuando te hayas consolado (siempre se consuela uno) estarás contento de haberme conocido.","zh":"他又放声大笑起来。","t":[100,6025]},{"es":"Serás mi amigo y tendrás ganas de reír conmigo.","zh":"“等你安慰好自己——人总会安慰好自己的——你会庆幸认识了我。","t":[6025,9575]},{"es":"Algunas veces abrirás tu ventana sólo por placer y tus amigos quedarán asombrados de verte reír mirando al cielo.","zh":"你将永远是我的朋友。","t":[9575,16450]},{"es":"Tú les explicarás: \"Las estrellas me hacen reír siempre\".","zh":"你会和我一起欢笑。","t":[16450,20575]},{"es":"Ellos te creerán loco.","zh":"你的朋友们会奇怪，你为什么望着天空笑。","t":[20575,22925]},{"es":"Y yo te habré jugado una mala pasada…","zh":"而你会回答他们，星星总是让你发笑。”","t":[22925,24950]}]},{"id":"ch26p44","audio":true,"sents":[{"es":"Y se rió otra vez.","zh":"他们会以为你有点失常。","t":[100,1187]}]},{"id":"ch26p45","audio":true,"sents":[{"es":"-Será como si en vez de estrellas, te hubiese dado multitud de cascabelitos que saben reír…","zh":"是的，我会跟你开个有趣的玩笑……”","t":[100,4726]}]},{"id":"ch26p46","audio":true,"sents":[{"es":"Una vez más dejó oír su risa y luego se puso serio.","zh":"小王子又笑了。","t":[100,3075]}]},{"id":"ch26p47","audio":true,"sents":[{"es":"-Esta noche ¿sabes?","zh":"“这就好像，我没给你星星，而是给了你一大堆会笑的铃铛。”","t":[100,1375]},{"es":"no vengas…","zh":"他哈哈大笑，随后又严肃起来。","t":[1375,1988]}]},{"id":"ch26p48","audio":true,"sents":[{"es":"-No te dejaré.","zh":"“今夜……你知道……你最好别来。","t":[100,875]}]},{"id":"ch26p49","audio":true,"sents":[{"es":"-Pareceré enfermo…","zh":"“我不会丢下你。”","t":[100,2038]},{"es":"Parecerá un poco que me muero…","zh":"“你会觉得我很难受。","t":[2038,3700]},{"es":"es así.","zh":"我会像在死去一样。","t":[3700,5150]},{"es":"¡No vale la pena que vengas a ver eso…!","zh":"事情总是这样……你不必看见，也不该看见……”","t":[5150,7076]}]},{"id":"ch26p50","audio":true,"sents":[{"es":"-No te dejaré.","zh":"“我不会丢下你。”","t":[100,875]}]},{"id":"ch26p51","audio":true,"sents":[{"es":"Pero estaba preocupado.","zh":"小王子显得真的担心起来。","t":[100,1363]}]},{"id":"ch26p52","audio":true,"sents":[{"es":"-Te digo esto por la serpiente; no debe morderte.","zh":"“我跟你这么说……是因为蛇……","t":[100,3812]},{"es":"Las serpientes son malas.","zh":"怕它咬了你。","t":[3812,6288]},{"es":"A veces muerden por gusto…","zh":"蛇……它们是恶的。","t":[6288,7737]}]},{"id":"ch26p53","audio":true,"sents":[{"es":"-He dicho que no te dejaré.","zh":"它们甚至会无缘无故地咬人……”","t":[100,1325]}]},{"id":"ch26p54","audio":true,"sents":[{"es":"Pero algo lo tranquilizó.","zh":"“我不会丢下你！”","t":[100,1338]}]},{"id":"ch26p55","audio":true,"sents":[{"es":"-Bien es verdad que no tienen veneno para la segunda mordedura…","zh":"不过，有什么让他安心了。","t":[100,3176]}]},{"id":"ch26p56","audio":true,"sents":[{"es":"Aquella noche no lo vi ponerse en camino.","zh":"“嗯，也对！","t":[100,3212]},{"es":"Cuando le alcancé marchaba con paso rápido y decidido y me dijo solamente: -¡Ah, estás ahí!","zh":"这一夜，我没看见他是怎么离开的。","t":[3212,8025]}]},{"id":"ch26p57","audio":true,"sents":[{"es":"Me cogió de la mano y todavía se atormentó:","zh":"他就这样悄然消失了。","t":[100,2338]}]},{"id":"ch26p58","audio":true,"sents":[{"es":"-Has hecho mal.","zh":"等我追上他时，他正快速而坚定地向前走。","t":[100,1812]},{"es":"Tendrás pena.","zh":"看见我，他只说：“啊……你在这儿……”","t":[1812,3612]},{"es":"Parecerá que estoy muerto, pero no es verdad.","zh":"他依旧满心忧虑，握住我的手。","t":[3612,5924]}]},{"id":"ch26p59","audio":true,"sents":[{"es":"Yo me callaba.","zh":"“你不该来……看着这情景，你会难受的。","t":[100,1912]},{"es":"-¿Comprendes?","zh":"我会像死了一样，但其实并非如此……”","t":[1912,3612]},{"es":"Es demasiado lejos y no puedo llevar este cuerpo que pesa demasiado.","zh":"我沉默着。","t":[3612,7063]}]},{"id":"ch26p60","audio":true,"sents":[{"es":"-Seguí callado.","zh":"“你明白吗——我的家，对这副躯壳来说太远了。","t":[100,900]}]},{"id":"ch26p61","audio":true,"sents":[{"es":"-Será como una corteza vieja que se abandona.","zh":"它太重，我带不走它……","t":[100,3425]},{"es":"No son nada tristes las viejas cortezas…","zh":"我沉默着。","t":[3425,5825]}]},{"id":"ch26p62","audio":true,"sents":[{"es":"Yo me callaba.","zh":"“这就像抛弃一件旧外壳。","t":[100,1912]},{"es":"El principito perdió un poco de ánimo.","zh":"丢弃旧外壳，并不悲伤……","t":[1912,4875]},{"es":"Pero hizo un esfuerzo y dijo:","zh":"我沉默着。","t":[4875,6463]}]},{"id":"ch26p63","audio":true,"sents":[{"es":"Será agradable ¿sabes?","zh":"他有些泄气，却仍再做一次努力。","t":[100,2638]},{"es":"Yo miraré también las estrellas.","zh":"“你知道，这会很妙！","t":[2638,5375]},{"es":"Todas serán pozos con roldana herrumbrosa.","zh":"我也会望着星星。","t":[5375,8662]},{"es":"Todas las estrellas me darán de beber.","zh":"它们全都会像生了锈辘轳的井。","t":[8662,10650]}]},{"id":"ch26p64","audio":true,"sents":[{"es":"Yo me callaba.","zh":"所有的星星都会让我喝个够。","t":[100,1912]},{"es":"-¡Será tan divertido!","zh":"我沉默着。","t":[1912,3988]},{"es":"Tú tendrás quinientos millones de cascabeles y yo quinientos millones de fuentes…","zh":"“这该多有趣！","t":[3988,7937]}]},{"id":"ch26p65","audio":true,"sents":[{"es":"El principito se calló también; estaba llorando.","zh":"你会有五亿只铃铛，而我会有五亿眼清泉。”","t":[100,2700]}]},{"id":"ch26p66","audio":true,"sents":[{"es":"-Es allí; déjame ir solo.","zh":"他也沉默了，因为他哭了起来。","t":[100,1888]}]},{"id":"ch26p67","audio":true,"sents":[{"es":"Se sentó porque tenía miedo.","zh":"“就在这儿。","t":[100,2638]},{"es":"Dijo aún: -¿Sabes?…","zh":"让我独自走完最后一步吧。”","t":[2638,4888]},{"es":"mi flor…","zh":"他在沙地上坐下。","t":[4888,5612]},{"es":"soy responsable…","zh":"他害怕了。","t":[5612,6800]},{"es":"¡y ella es tan débil y tan inocente!","zh":"接着他说：“你知道……我的花……我的美人儿……","t":[6800,9750]},{"es":"Sólo tiene cuatro espinas para defenderse contra todo el mundo…","zh":"她是那么柔弱，那么天真！","t":[9750,13013]}]},{"id":"ch26p68","audio":true,"sents":[{"es":"Me senté, ya no podía mantenerme en pie.","zh":"她只有四根刺，用来抵御整个世界……","t":[100,2276]}]},{"id":"ch26p69","audio":true,"sents":[{"es":"-Ahí está…","zh":"我在沙地上坐下。","t":[100,1038]},{"es":"eso es todo…","zh":"我的双腿支撑不住身子。","t":[1038,1800]}]},{"id":"ch26p70","audio":true,"sents":[{"es":"Vacíló todavía un instante, luego se levantó y dio un paso.","zh":"“嗯，就这么结束了……”","t":[100,4325]},{"es":"Yo no pude moverme.","zh":"他略一迟疑，然后起身，向前迈了一步。","t":[4325,5413]}]},{"id":"ch26p71","audio":true,"sents":[{"es":"Un relámpago amarillo centelleó en su tobillo.","zh":"我无力动弹。","t":[100,3600]},{"es":"Quedó un instante inmóvil, sin exhalar un grito.","zh":"我看见一道小小的黄色闪电，在他脚边一闪而过。","t":[3600,7238]},{"es":"Luego cayó lentamente camo cae un árbol, sin hacer el menor ruido a causa de la arena.","zh":"他静止地站了一瞬，随后像被砍倒的树一般，无声而缓慢地倒在沙地上，沙掩住了他落地的声响。","t":[7238,11863]}]}]},{"id":"ch27","title_es":"Capítulo 27","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":true,"sents":[{"es":"Ahora hace ya seis años de esto.","zh":"从那以后，已经过去了六年。","t":[100,3000]},{"es":"Jamás he contado esta historia y los compañeros que me vuelven a ver se alegran de encontrarme vivo.","zh":"我至今没对任何人讲过这个故事。","t":[3000,8688]},{"es":"Estaba triste, pero yo les decía: \"Es el cansancio\".","zh":"而我满心忧伤，却只对他们说，我只是累了。","t":[8688,11788]}]},{"id":"ch27p01","audio":true,"sents":[{"es":"AI correr del tiempo me he consolado un poco, pero no completamente.","zh":"如今我已平静下来。","t":[100,4525]},{"es":"Sé que ha vuelto a su planeta, pues al amanecer no encontré su cuerpo, que no era en realidad tan pesado…","zh":"嗯，当然，也没完全平静……","t":[4525,10850]},{"es":"Y me gusta por la noche escuchar a las estrellas, que suenan como quinientos millones de cascabeles…","zh":"我确信，他已经回到了自己的星球。","t":[10850,15862]}]},{"id":"ch27p02","audio":true,"sents":[{"es":"Pero sucede algo extraordinario.","zh":"也许，它本来就没那么重……","t":[100,2862]},{"es":"AI bozal que dibujé para el principito se me olvidó añadirle la correa de cuero; no habrá podido atárselo al cordero.","zh":"现在，我喜欢在夜里聆听星星。","t":[2862,9762]},{"es":"Entonces me pregunto:","zh":"它们为我叮当作响，像五亿只铃铛。","t":[9762,10975]}]},{"id":"ch27p03","audio":true,"sents":[{"es":"\"¿Qué habrá sucedido en su planeta?","zh":"我画了嘴套，把那张画交给了小王子。","t":[100,2688]},{"es":"Quízás el cordero se ha comido la flor…\"","zh":"然而我忘了给嘴套画上那条皮带。","t":[2688,4676]}]},{"id":"ch27p04","audio":true,"sents":[{"es":"A veces me digo: \"¡Seguro que no!","zh":"那他还怎么把嘴套套到小羊头上呢？","t":[100,2762]},{"es":"El príncipito cubre la flor con su fanal todas las noches y vigila a su cordero\".","zh":"或许，小羊终究还是吃了那朵花？","t":[2762,6900]}]},{"id":"ch27p05","audio":true,"sents":[{"es":"Entonces me siento dichoso y todas las estrellas ríen dulcemente.","zh":"可我随即安慰自己——当然不会！","t":[100,3675]}]},{"id":"ch27p06","audio":true,"sents":[{"es":"Pero otras veces pienso: \"Alguna que otra vez se distrae uno y eso basta.","zh":"因为每天夜里，小王子都会用玻璃罩罩住他的花，又细心照看他的小羊。","t":[100,5262]},{"es":"Si una noche ha olvidado poner el fanal o el cordero ha salido sin hacer ruido, durante la noche…\".","zh":"可有时我又想——只要有一次疏忽，就全完了！","t":[5262,11175]},{"es":"Y entonces los cascabeles se convierten en lágrimas…","zh":"万一有天傍晚他忘了罩子，或是小羊夜里悄悄走开呢？","t":[11175,13926]}]},{"id":"ch27p07","audio":true,"sents":[{"es":"Y ahí está el gran misterio.","zh":"那样的夜里，所有的铃铛都会哭泣……","t":[100,2600]},{"es":"Para ustedes que quieren al principito, lo mismo que para mí, nada en el universo habrá cambiado si en cualquier parte, quien sabe dónde, un cordero desconocido se ha comido o no se ha comido una rosa…","zh":"这里面藏着巨大的奥秘。","t":[2600,12426]}]},{"id":"ch27p08","audio":true,"sents":[{"es":"Pero miren al cielo y pregúntense: el cordero ¿se ha comido la flor?","zh":"在宇宙中是和从前一样了，如果某处那头你们甚至从未见过的羊，已经吃掉了他的玫瑰。","t":[100,4950]},{"es":"Y veréis cómo todo cambia…","zh":"仰望天空，问问自己——这事已经发生，还是尚未发生？","t":[4950,7312]},{"es":"¡Ninguna persona mayor comprenderá jamás que esto sea verdaderamente importante!","zh":"你会看见，周遭的一切都因这个问题的答案而改变。","t":[7312,11450]}]},{"id":"ch27p09","audio":true,"sents":[{"es":"Este es para mí el paisaje más hermoso y el más triste del mundo.","zh":"这幅画里，有对我来说世界上最美丽、也最忧伤的风景。","t":[100,3462]}]},{"id":"ch27p10","audio":true,"sents":[{"es":"Es el mismo paisaje de la página anterior que he dibujado una vez más para que lo vean bien.","zh":"这风景与上一页所画的是同一处。","t":[100,5512]},{"es":"Fue aquí donde el principito apareció sobre la Tierra, desapareciendo luego.","zh":"我重画了一遍，好让你们看得更清楚。","t":[5512,9487]}]},{"id":"ch27p11","audio":true,"sents":[{"es":"Exaxnínenlo atentamente para que sepan reconocerlo, si algún día, viajando por Africa cruzan el desierto.","zh":"小王子正是在这里降临地球，随后又消失。","t":[100,7025]},{"es":"Si por casualidad pasan por allí, no se apresuren, se los ruego, y deténganse un poco, precisamente bajo la estrella.","zh":"只是为了在你们万一来到","t":[7025,14325]},{"es":"Si un niño llega hasta ustedes, si este niño ríe y tiene cabellos de oro y nunca responde a sus preguntas, adivinarán en seguida quién es.","zh":"非洲沙漠时，能够认出他。","t":[14325,22800]},{"es":"¡Sean amables con él!","zh":"若你们真到了这里，我恳请你们，不要匆忙。","t":[22800,24025]}]},{"id":"ch27p12","audio":true,"sents":[{"es":"Y comuníquenme rápidamente que ha regresado.","zh":"若有个小男孩走来对你笑，若他有一头金色头发，且对你的问话不予回答，你便知他是谁。","t":[100,3438]},{"es":"¡No me dejen tan triste!","zh":"那时，请行行好——别再让我悲伤，快写信告诉我：他回来了……","t":[3438,4775]}]}]}]};